E["item:azure-agate"] = {t="item",n="Azure Agate",z="arathi",s="Boulderfist shamans near the Tower of Arathor have taken Azure Agates from the tower. Apprentice Kryten needs one at Refuge Pointe to enchant as a key for its defenses.",h="Boulderfist shamans near the Tower of Arathor have taken Azure Agates from the tower.",sec={{t="A Gem for the Tower",b="At Refuge Pointe, Apprentice Kryten needs an Azure Agate from the Boulderfist shamans in Stromgarde. The shamans took the gems from the Tower of Arathor, whose defenses must be activated against the ogres nearby. Bring an agate to Kryten, and he will enchant it so it can serve as a key.",sp=0}},faq={{q="Where can I find an Azure Agate?",a="Boulderfist shamans in Stromgarde Keep, in the Arathi Highlands, have Azure Agates.",al={"azure agate location","where agate","find agate"}},{q="Who needs the Azure Agate?",a="Apprentice Kryten at Refuge Pointe needs an Azure Agate.",al={"who wants it","give agate to who","kryten agate"}},{q="What is the agate for?",a="Kryten enchants the Azure Agate so it can serve as a key to the Tower of Arathor's defenses.",al={"agate purpose","what's it for","why agate"}},{q="Why does Kryten need it?",a="The Tower of Arathor's defenses must be activated to stand against the ogres around it. Kryten needs an Azure Agate to enchant as a key.",al={"why kryten needs agate","tower defenses","ogres tower"}}},kw={"agate","apprentice kryten","arathi highlands","azure agate","boulderfist shaman","refuge pointe","stromgarde","tower of arathor"},rel={"quest:694","zone:arathi","subzone:refuge-pointe","subzone:stromgarde-keep","subzone:tower-of-arathor"},src={"Wowpedia: Azure Agate","Trelane's Defenses (Classic)"}}
E["item:befouled-bloodstone-orb"] = {t="item",n="Befouled Bloodstone Orb",z="arathi",s="The Befouled Bloodstone Orb is a magical relic held by a warlock in Stromgarde Keep. Tor'gan in Hammerfall seeks it to end its power over the land.",h="The Befouled Bloodstone Orb is a magical relic held by a warlock in Stromgarde Keep.",sec={{t="A Tainted Relic",b="Tor'gan fears a warlock in Stromgarde Keep is using a magical relic to summon demons. The Befouled Bloodstone Orb is the object he seeks, so its power can be destroyed before it taints Arathi Highlands further.",sp=0}},faq={{q="What is the Befouled Bloodstone Orb?",a="The Befouled Bloodstone Orb is a magical relic held by Marez Cowl, a warlock in Stromgarde Keep.",al={"bloodstone orb","befouled orb"}},{q="Who has the orb?",a="Marez Cowl, a warlock within Stromgarde Keep, holds the Befouled Bloodstone Orb.",al={"marez orb","who holds bloodstone"}},{q="Why does Tor'gan want it?",a="Tor'gan wants the orb so he can destroy it and keep its power from tainting Arathi Highlands.",al={"tor'gan orb","why retrieve orb"}},{q="What is the orb used for?",a="Tor'gan believes a warlock has used the orb to summon demons in large numbers.",al={"orb demons","bloodstone magic"}},{q="Where is the orb?",a="Marez Cowl holds the orb inside the walls of Stromgarde Keep in Arathi Highlands.",al={"orb location","stromgarde bloodstone"}}},ang={["class:Warlock"]="As a warlock, you know the danger of a relic used to summon demons. Tor'gan seeks to destroy the orb before its power can further taint Arathi Highlands."},kw={"arathi highlands","befouled bloodstone orb","bloodstone orb","demons","foul magics","marez cowl","stromgarde keep","tor'gan","warlock"},rel={"quest:671","zone:arathi","subzone:stromgarde-keep","subzone:hammerfall","topic:warlock"},src={"Wowpedia: Befouled Bloodstone Orb","Foul Magics (2)"}}
E["item:eldritch-shackles"] = {t="item",n="Eldritch Shackles",z="arathi",s="The Eldritch Shackles are used with the Shards of Myzrael at the Circle of Inner Binding in the Arathi Highlands. The stones hold a power that stirs when the shackles are placed.",h="The Eldritch Shackles are used with the Shards of Myzrael at the Circle of Inner Binding in the Arathi...",sec={{t="At the Shards",b="At the Circle of Inner Binding, the Eldritch Shackles are used with the Shards of Myzrael. Myzrael must be summoned and defeated before the shackles can bind her again.",sp=0},{t="A Wail Below",b="When the shackles are placed around the Shards, an inhuman wail rises from far below, followed by a roar. The stones pulse with menace, and the thing beneath them seems to bear ill will toward the surface.",sp=1}},faq={{q="What are the Eldritch Shackles for?",a="The Eldritch Shackles are bound around the Shards of Myzrael to trap Myzrael again.",al={"what do shackles do","eldritch shackles purpose"},sp=1},{q="Where do I use the Eldritch Shackles?",a="The Eldritch Shackles are used at the Shards of Myzrael in the Circle of Inner Binding, in the Arathi Highlands.",al={"where to use shackles","shackles location"}},{q="Who is Myzrael?",a="Myzrael is called the princess, and she is held beneath the Shards of Myzrael.",al={"myzrael who","who is the princess"},sp=1},{q="Why must Myzrael be defeated?",a="Myzrael must be defeated before she gathers enough power to challenge her captors.",al={"why kill myzrael","stop myzrael"},sp=1},{q="What happens when the shackles bind Myzrael?",a="An inhuman wail rises from far below, followed by a roar, and the Shards pulse with menace.",al={"shackles effect","what happens at shards"},sp=1}},kw={"arathi highlands","circle of inner binding","eldritch shackles","myzrael","shards of myzrael","summoning the princess"},rel={"quest:656","item:scroll-of-myzrael","subzone:circle-of-inner-binding","zone:arathi"},src={"Wowpedia: Eldritch Shackles","Summoning the Princess"}}
E["item:elven-gem"] = {t="item",n="Elven Gem",z="arathi",s="Elven Gems are calcified stones lying on the sea floor near Faldir’s Cove. Doctor Draxlegauge’s goggles help you find them for Captain O’Breen’s search for lost treasure.",h="Elven Gems are calcified stones lying on the sea floor near Faldir’s Cove.",sec={{t="Stones Below",b="The sea has covered the treasure for so long that its gems have hardened inside thick stone. Near Faldir’s Cove, Doctor Draxlegauge lends you his Goggles of Gem Hunting to find them. He asks you to gather ten Elven Gems for Captain O’Breen, then return the goggles.",sp=0}},faq={{q="Where do Elven Gems come from?",a="Elven Gems lie on the sea floor near Faldir’s Cove, sealed in calcified stone.",al={"where find elven gems","elven gem source"}},{q="Why are the gems calcified?",a="The treasure has rested on the sea floor so long that the gems have calcified into thick stone.",al={"why stone gems","calcified gems why"}},{q="Who wants the Elven Gems?",a="Doctor Draxlegauge asks you to collect ten Elven Gems for Captain O’Breen’s search for lost treasure.",al={"who needs gems","captain obreen gems"}},{q="How do you find the gems?",a="Doctor Draxlegauge lends you the Goggles of Gem Hunting, which help you locate the calcified gems.",al={"find gems how","goggles work"}},{q="Who is Doctor Draxlegauge?",a="Doctor Draxlegauge is a gnome in Faldir’s Cove who lends you his gem-hunting goggles. He prefers to keep to safe, dry land.",al={"draxlegauge","who is the doctor"}}},kw={"calcified elven gems","captain o'breen","doctor draxlegauge","elven gem","elven gems","faldir's cove","goggles of gem hunting","sunken treasure"},rel={"subzone:faldir-s-cove","item:elven-gems","item:goggles-of-gem-hunting","quest:665","npc:fleet-master-seahorn","zone:arathi"},src={"Wowpedia: Elven Gem","Sunken Treasure (2)"}}
E["item:elven-gems"] = {t="item",n="Elven Gems",z="arathi",s="Elven Gems are treasure recovered from a sunken vessel in Arathi Highlands. Captain O'Breen is waiting to inspect them.",h="Elven Gems are treasure recovered from a sunken vessel in Arathi Highlands.",sec={{t="A Pirate's Treasure",b="Doctor Draxlegauge and the professor have spent weeks among Captain O'Breen's pirates. Now they fear being caught with the treasure, so they send you to bring the Elven Gems to the captain. O'Breen is waiting on the bridge.",sp=0}},faq={{q="What are the Elven Gems?",a="They are treasure recovered from a sunken vessel and meant for Captain O'Breen to inspect.",al={"elven gems","what gems","gem treasure"}},{q="Who wants the Elven Gems?",a="Captain O'Breen wants to see the Elven Gems firsthand.",al={"who wants gems","captain obreen gems","take gems where"}},{q="Why am I carrying the gems?",a="Doctor Draxlegauge and the professor fear being caught holding the pirates' treasure, so they send you to Captain O'Breen.",al={"why take gems","why me","gems purpose"}},{q="Where do I take the Elven Gems?",a="Take the Elven Gems to Captain O'Breen on the bridge.",al={"gems location","where gems go","captain bridge"}}},kw={"arathi highlands","captain o'breen","elven gems","pirates","professor","sunken treasure"},rel={"quest:665","item:elven-gem","zone:arathi"},src={"Wowpedia: Elven Gems","Sunken Treasure (3)"}}
E["item:enchanted-agate"] = {t="item",n="Enchanted Agate",z="arathi",s="The Enchanted Agate activates the Tower of Arathor's defenses. Apprentice Kryten gives it to you before you enter to search for Trelane's remaining items.",h="The Enchanted Agate activates the Tower of Arathor's defenses.",sec={{t="At the Tower",b="At Refuge Pointe, Kryten hands over the Enchanted Agate and sends you on to Skuerto for the rest of the details. Press it against a pedestal near the tower's base when you are ready to enter. The gem activates the tower's defenses, clearing your way toward Trelane's remaining items.",sp=0}},faq={{q="What does the Enchanted Agate do?",a="The Enchanted Agate activates the defenses of the Tower of Arathor when pressed against a pedestal near its base.",al={"enchanted agate use","agate purpose","what gem do"}},{q="Where do I use the Enchanted Agate?",a="Press the Enchanted Agate against one of the pedestals near the base of the Tower of Arathor.",al={"where use agate","tower pedestal","agate location"}},{q="Who gives me the Enchanted Agate?",a="Apprentice Kryten gives you the Enchanted Agate at Refuge Pointe, then sends you to Skuerto.",al={"who gave me agate","skuerto agate","agate from who"}},{q="Why am I taking the Enchanted Agate into the tower?",a="The gem activates the tower's defenses before you enter to find Trelane's remaining items.",al={"why agate tower","agate for trelane","what gem for"}}},kw={"agate","defenses","enchanted agate","pedestal","skuerto","tower of arathor","trelane"},rel={"quest:695","npc:skuerto","subzone:tower-of-arathor","zone:arathi"},src={"Wowpedia: Enchanted Agate","An Apprentice's Enchantment"}}
E["item:goggles-of-gem-hunting"] = {t="item",n="Goggles of Gem Hunting",z="arathi",s="The Goggles of Gem Hunting are a gnomish device used to find treasure beneath the waters off Arathi Highlands. Their enchantment reveals gems buried in stone on the sea floor.",h="The Goggles of Gem Hunting are a gnomish device used to find treasure beneath the waters off Arathi Highlands.",sec={{t="Beneath the Waves",b="Off Faldir's Cove, Doctor Draxlegauge lends the Goggles of Gem Hunting to Captain O'Breen's crew. Professor Phizzlethorpe empowers the device with an enchanted stone, giving it the power to locate gems below. The treasure has lain underwater so long that its gems have calcified into thick stone. Draxlegauge asks that the goggles be returned when the search is done.",sp=0}},faq={{q="Who made the goggles?",a="Doctor Draxlegauge constructed the Goggles of Gem Hunting, and Professor Phizzlethorpe empowered them with an enchanted stone.",al={"goggles maker","who built them","draxlegauge goggles"}},{q="What do the goggles do?",a="The goggles let their wearer locate gems beneath the sea, even when the gems have calcified into thick stone.",al={"how do goggles work","find gems","gem hunting goggles"}},{q="Where are the goggles used?",a="The Goggles of Gem Hunting are used to search the sea floor off Faldir's Cove in Arathi Highlands.",al={"where to use goggles","goggles location","faldir cove goggles"}},{q="Why does Captain O'Breen want the gems?",a="Doctor Draxlegauge asks you to find the sunken gems for Captain O'Breen. The provided account gives no further reason for the Captain's interest.",al={"captain wants gems","why collect elven gems","o'breen treasure"}}},ang={["race:Gnome"]="As a gnome, you can see Doctor Draxlegauge's ingenuity at work in a device built to find gems beneath the sea.",["profession:Engineering"]="As an engineer, you may admire how Doctor Draxlegauge's goggles join gnomish construction with Professor Phizzlethorpe's enchantment."},kw={"arathi highlands","doctor draxlegauge","elven gems","faldir's cove","goggles","goggles of gem hunting","professor phizzlethorpe","sunken treasure"},rel={"quest:665","item:elven-gem","item:elven-gems","subzone:faldir-s-cove","zone:arathi"},src={"Wowpedia: Goggles of Gem Hunting","Sunken Treasure (2)"}}
E["item:maiden-s-folly-charts"] = {t="item",n="Maiden's Folly Charts",z="arathi",s="Maiden's Folly Charts are navigational records recovered from a wreck in the Arathi Highlands. First Mate Nilzlix wants them secured before the ships leave the cove.",h="Maiden's Folly Charts are navigational records recovered from a wreck in the Arathi Highlands.",sec={{t="Charts from the Wreck",b="In the Arathi Highlands, the Maiden's Folly lies wrecked beside the Spirit of Silverpine. Their charts and logs record information the crew fears could reach enemy hands. First Mate Nilzlix asks you to recover the charts, including those from the Maiden's Folly, and bring them back to him before the ships leave the cove.",sp=0}},faq={{q="What are the Maiden's Folly Charts?",a="They are navigational charts that belonged to the Maiden's Folly, now wrecked in the Arathi Highlands.",al={"maiden's folly charts","folly charts","what charts"}},{q="Where can I find the charts?",a="The Maiden's Folly lies wrecked in a cove in the Arathi Highlands.",al={"where charts","find folly charts","chart location"}},{q="Who wants the charts recovered?",a="First Mate Nilzlix asks you to recover the Maiden's Folly Charts and the ships' other records.",al={"who wants them","nilzlix charts","first mate"}},{q="Why must the charts be secured?",a="The crew fears the charts and logs could fall into enemy hands, and Fleet Master Seahorn would hold them responsible.",al={"why recover charts","enemy hands","why charts matter"}},{q="Where will the charts go?",a="The recovered charts go back to First Mate Nilzlix in the cove; knowing they are secure eases the command in Booty Bay.",al={"where return charts","booty bay charts","charts destination"}}},kw={"arathi highlands","booty bay","charts","deep sea salvage","first mate nilzlix","maiden's folly","maiden's folly charts"},rel={"quest:662","item:maiden-s-folly-log","zone:arathi","npc:fleet-master-seahorn"},src={"Wowpedia: Maiden's Folly Charts","Deep Sea Salvage"}}
E["item:maiden-s-folly-log"] = {t="item",n="Maiden's Folly Log",z="arathi",s="The Maiden's Folly Log is the captain's record from a ship wrecked in Arathi's reef. Its pages and charts hold information Fleet Master Seahorn wants kept from prying eyes.",h="The Maiden's Folly Log is the captain's record from a ship wrecked in Arathi's reef.",sec={{t="A Wreck's Record",b="First Mate Nilzlix seeks the log from the Maiden's Folly, wrecked alongside the Spirit of Silverpine. The ships ran aground on a reef temple after the tides began to fall, and sank quickly. Their records matter to the command in Booty Bay, which fears the information could reach enemy hands.",sp=0}},faq={{q="What is the Maiden's Folly Log?",a="It is the captain's log from the Maiden's Folly, one of the ships wrecked in Arathi's reef.",al={"maiden's folly log","captain log","ship's log"}},{q="Where did the Maiden's Folly sink?",a="The Maiden's Folly ran aground on a reef temple in Arathi and sank.",al={"where's the wreck","maiden folly location","ship wreck arathi"}},{q="Why does First Mate Nilzlix want the log?",a="First Mate Nilzlix wants the Maiden's Folly's log and charts recovered before their information falls into enemy hands.",al={"why recover the log","nilzlix wants what","why get the book"}},{q="What happened to the Maiden's Folly?",a="The tides began to fall as the Maiden's Folly approached a cove, and the ship ran aground on a reef temple before sinking.",al={"maiden folly wreck","how did it sink","what happened to the ship"}},{q="Who wants the records kept safe?",a="Fleet Master Seahorn's command in Booty Bay wants the logs and charts kept from prying eyes.",al={"who wants the charts","fleet master seahorn","booty bay records"}}},kw={"arathi","booty bay","captain's log","deep sea salvage","log","maiden's folly","nilzlix","reef","seahorn","temple"},rel={"item:maiden-s-folly-charts","quest:662","item:spirit-of-silverpine-log","item:spirit-of-silverpine-charts","npc:fleet-master-seahorn","zone:arathi"},src={"Wowpedia: Maiden's Folly Log","Deep Sea Salvage"}}
E["item:or-kalar-s-head"] = {t="item",n="Or'Kalar's Head",z="arathi",s="Or'Kalar's Head is proof that Hammerfall's attacks have a dangerous source. Korin Fel asks you to bring it to her at the outpost.",h="Or'Kalar's Head is proof that Hammerfall's attacks have a dangerous source.",sec={{t="A Threat at Hammerfall",b="Korin Fel sends you to find Or'Kalar near the Tower of Arathor. The ogre serves Mug'thol in Stromgarde and bears a fierce hatred for Korin's husband, who defeated him years ago. Korin believes Or'Kalar has laid a trap for her husband. She asks you to slay him and bring his head to Hammerfall.",sp=0}},faq={{q="Who is Or'Kalar?",a="Or'Kalar is an ogre in Stromgarde who serves Mug'thol and hates Korin Fel's husband for defeating him years ago.",al={"or kalar","or'kalar identity"}},{q="Why does Korin Fel want Or'Kalar dead?",a="Korin believes Or'Kalar has laid a trap for her husband and wants the ogre slain to protect him and Hammerfall.",al={"why kill or'kalar","korin's request"}},{q="Where can I find Or'Kalar?",a="Or'Kalar is near the Tower of Arathor in the Arathi Highlands.",al={"or'kalar location","tower ogre"}},{q="Who receives Or'Kalar's Head?",a="Korin Fel receives Or'Kalar's Head at the Hammerfall outpost.",al={"where take head","korin fel head"}}},ang={["faction:Horde"]="As a member of the Horde, you can help protect Hammerfall and Korin Fel's husband from Or'Kalar's attack."},kw={"arathi highlands","hammerfall","korin fel","mug'thol","or'kalar","or'kalar's head","stromgarde","tower of arathor"},rel={"quest:680","subzone:tower-of-arathor","subzone:hammerfall","zone:arathi"},src={"Wowpedia: Or'Kalar's Head","The Real Threat (Classic)"}}
E["item:sample-elven-gem"] = {t="item",n="Sample Elven Gem",z="arathi",s="The Sample Elven Gem is proof of a treasure found by Shakes O’Breen’s crew. Fleet Master Seahorn in Booty Bay needs it as word of their discovery.",h="The Sample Elven Gem is proof of a treasure found by Shakes O’Breen’s crew.",sec={{t="A Sample for Seahorn",b="Shakes O’Breen’s crew has found treasure, but low tide and watchful creatures keep them from leaving. They need you to carry the Sample Elven Gem to Fleet Master Seahorn in Booty Bay. The gem proves their find and tells Seahorn they are working to recover more.",sp=0}},faq={{q="What is the Sample Elven Gem?",a="The Sample Elven Gem is proof of the treasure Shakes O’Breen’s crew discovered.",al={"sample gem","elven gem sample"}},{q="Who gave me the Sample Elven Gem?",a="Shakes O’Breen provided the Sample Elven Gem for you to take to Fleet Master Seahorn.",al={"who gave me the gem","shakes gem"}},{q="Who needs the gem?",a="Fleet Master Seahorn in Booty Bay needs the Sample Elven Gem as proof of the crew’s discovery.",al={"who wants this gem","gem for seahorn"}},{q="Why can’t Shakes O’Breen’s crew leave?",a="The tide is too low, and the creatures the crew disturbed are watching their movements.",al={"why stuck","why can't they leave"}}},kw={"booty bay","elven gem","fleet master seahorn","sample elven gem","shakes o’breen","sunken treasure","treasure"},rel={"quest:665","item:elven-gem","npc:fleet-master-seahorn","subzone:booty-bay"},src={"Wowpedia: Sample Elven Gem","Sunken Treasure (4)"}}
E["item:scroll-of-myzrael"] = {t="item",n="Scroll of Myzrael",z="arathi",s="The Scroll of Myzrael is used at the Shards of Myzrael in the Arathi Highlands to call her forth again.",h="The Scroll of Myzrael is used at the Shards of Myzrael in the Arathi Highlands to call her forth again.",sec={{t="At the Shards",b="At the Shards of Myzrael in the Arathi Highlands, the scroll calls forth the being held beneath them. Myzrael must be defeated, and her Eldritch Shackles bound to the shards. The work is meant to keep her captive as her power grows.",sp=0}},faq={{q="What does the Scroll of Myzrael do?",a="The Scroll of Myzrael is used to summon Myzrael at the Shards of Myzrael in the Arathi Highlands.",al={"scroll of myzrael use","what is this scroll for","summon myzrael"}},{q="Where do I use the scroll?",a="The scroll is used at the Shards of Myzrael in the Arathi Highlands, where Myzrael was first encountered.",al={"where scroll","myzrael shards location","where summon her"}},{q="Why summon Myzrael?",a="Myzrael must be defeated before her power grows, then bound again at the shards with her Eldritch Shackles.",al={"why summon myzrael","what is the point","why call her"},sp=1},{q="What are the Eldritch Shackles for?",a="The Eldritch Shackles are bound to the Shards of Myzrael to trap her again.",al={"eldritch shackles purpose","shackles myzrael","bind her how"},sp=1}},kw={"arathi highlands","eldritch shackles","myzrael","princess","scroll of myzrael","shards of myzrael","summoning"},rel={"quest:656","item:eldritch-shackles","zone:arathi"},src={"Wowpedia: Scroll of Myzrael","Summoning the Princess"}}
E["item:seahorn-s-sealed-letter"] = {t="item",n="Seahorn's Sealed Letter",z="arathi",s="Seahorn's Sealed Letter carries secret correspondence from Booty Bay to Shakes O'Breen off the Arathi coast. The Blackwater Raiders are counting on its safe delivery.",h="Seahorn's Sealed Letter carries secret correspondence from Booty Bay to Shakes O'Breen off the Arathi coast.",sec={{t="A Sealed Message",b="From Booty Bay, Seahorn asks you to carry his sealed letter to Shakes O'Breen, whose ship lies off the Arathi coast. Seahorn's fleet is waiting in the bay for supplies, while troubling matters gather nearby and far away. He asks for confidence as well as safe passage. The Blackwater Raiders await word that the message has reached its mark.",sp=0}},faq={{q="Who sent the sealed letter?",a="Seahorn sent the sealed letter from Booty Bay. He asks that it reach Shakes O'Breen safely and in confidence.",al={"who wrote it","seahorn letter","letter from seahorn"}},{q="Who is supposed to receive it?",a="Shakes O'Breen, who is tied up off the Arathi coast, is the letter's intended recipient.",al={"who gets the letter","deliver to who","shakes letter"}},{q="Why does Seahorn need a courier?",a="Seahorn needs the sealed correspondence carried to Shakes O'Breen while his fleet is stuck in Booty Bay awaiting supplies.",al={"why deliver it","what's in the letter","secret message"}},{q="What happens if I deliver it safely?",a="The Blackwater Raiders are grateful for the long and perilous journey, and Seahorn is pleased when the message reaches its recipient.",al={"what for delivering","blackwater raiders","seahorn pleased"},sp=1}},kw={"arathi coast","blackwater raiders","booty bay","seahorn","sealed letter","secret correspondence","shakes o'breen"},rel={"quest:665","zone:arathi","subzone:booty-bay"},src={"Wowpedia: Seahorn's Sealed Letter","Sunken Treasure (5)"}}
E["item:sealed-letter-to-archmage-malin"] = {t="item",n="Sealed Letter to Archmage Malin",z="arathi",s="The sealed letter carries word from Arathi Highlands to Archmage Malin in Stormwind. Malin receives news from companions there.",h="The sealed letter carries word from Arathi Highlands to Archmage Malin in Stormwind.",sec={{t="Word from Arathi",b="In Stormwind's Mage Quarter, Archmage Malin opens the letter and recognizes the news it bears. Trelane will be pleased, and Kryten and Skuerto are eager to make their way back to Stormwind. Malin thanks the courier and offers help for the road ahead.",sp=0}},faq={{q="Who is the letter for?",a="The sealed letter is addressed to Archmage Malin in Stormwind's Mage Quarter.",al={"letter for malin","malin's letter"}},{q="Where does the letter come from?",a="The letter comes from Arathi Highlands, where Kryten and Skuerto say they will soon be home.",al={"letter from arathi","where's the letter from"},sp=1},{q="What does the letter say?",a="It tells Archmage Malin that Kryten and Skuerto will soon be home.",al={"letter contents","what's in the letter"},sp=1},{q="Who is Kryten?",a="Kryten is one of the companions expected to return to Stormwind with Skuerto.",al={"kryten letter","who's kryten"}},{q="Who is Skuerto?",a="Skuerto is one of the companions expected to return to Stormwind with Kryten.",al={"skuerto letter","who's skuerto"}}},kw={"arathi highlands","archmage malin","kryten","mage quarter","malin","sealed letter","skuerto","stormwind","trelane"},rel={"quest:690","npc:archmage-malin","npc:skuerto","zone:arathi","subzone:mage-quarter"},src={"Wowpedia: Sealed Letter to Archmage Malin","Malin's Request (2)"}}
E["item:shadow-hunter-knife"] = {t="item",n="Shadow Hunter Knife",z="arathi",s="The Shadow Hunter Knife is a Witherbark troll blade sought by Apprentice Kryten at Refuge Pointe. It is tied to the rites of the tribe’s shadow hunters.",h="The Shadow Hunter Knife is a Witherbark troll blade sought by Apprentice Kryten at Refuge Pointe.",sec={{t="A Troll's Blade",b="Apprentice Kryten seeks the Shadow Hunter Knife at Refuge Pointe for Archmage Malin’s research. He says the strongest Witherbark shadow hunters receive the special blade after completing their rites of passage. Their village lies southeast of Arathi, and Kryten cannot tell which hunter carries one until the struggle is done.",sp=0}},faq={{q="Who wants the Shadow Hunter Knife?",a="Apprentice Kryten at Refuge Pointe seeks the Shadow Hunter Knife for Archmage Malin’s research.",al={"who needs the knife","kryten knife","who wants it"}},{q="Who carries the Shadow Hunter Knife?",a="The strongest Witherbark shadow hunters may carry the special knife given after their rites of passage.",al={"who has knife","which troll has it","shadow hunter blade"}},{q="Why is the knife special?",a="Kryten says the Witherbark give the knife to their strongest shadow hunters after they complete their rites of passage.",al={"why special knife","troll knife meaning","what's special about it"}},{q="Where do the Witherbark live?",a="The Witherbark live southeast of Arathi, near Witherbark Village.",al={"where are witherbark","troll village location","withbark where"}}},ang={["faction:Alliance"]="As an Alliance traveler, Kryten’s work at Refuge Pointe serves Archmage Malin’s research in Arathi."},kw={"archmage malin","kryten","refuge pointe","rites of passage","shadow hunter knife","troll","witherbark"},rel={"quest:691","item:witherbark-tusk","item:witherbark-medicine-pouch","subzone:witherbark-village","zone:arathi","topic:troll"},src={"Wowpedia: Shadow Hunter Knife","Worth Its Weight in Gold (Classic)"}}
E["item:sheathed-trol-kalar"] = {t="item",n="Sheathed Trol'kalar",z="arathi",s="Trol'kalar lies freed within its stone sheath in Arathi Highlands. Zengu at Hammerfall awaits the sword, prized by the Darkspear trolls.",h="Trol'kalar lies freed within its stone sheath in Arathi Highlands.",sec={{t="The Stone Sheath",b="From Trollbane's Tomb in Arathi Highlands, you carry Trol'kalar within its stone sheath. The light that held the sword fades, freeing the weapon. Zengu waits at Hammerfall to receive it.",sp=0}},faq={{q="What is Sheathed Trol'kalar?",a="Sheathed Trol'kalar holds the sword Trol'kalar within a stone sheath. The fading light releases the weapon.",al={"sheathed trolkalar","stone sheath sword"}},{q="Where did I find Trol'kalar?",a="You find Sheathed Trol'kalar in Trollbane's Tomb in Arathi Highlands.",al={"trolkalar location","trollbane tomb"}},{q="Who wants the sword?",a="Zengu at Hammerfall awaits Trol'kalar. He says it will be delivered to Nimboya at Grom'gol.",al={"who gets trolkalar","zengu sword"}},{q="Why does Trol'kalar matter to the trolls?",a="Trol'kalar is called the greatest weapon of Strom and Arathor. Zengu says the Darkspear trolls are indebted to you for returning it.",al={"trolkalar importance","why trolls want sword"}}},ang={["race:Troll"]="As a troll, you carry a weapon Zengu calls the greatest of Strom and Arathor. The Darkspear are indebted to you for returning it."},kw={"darkspear","hammerfall","nimboya","sheathed trol'kalar","stone sheath","trol'kalar","trollbane's tomb","zengu"},rel={"quest:645","quest:638","zone:arathi","subzone:hammerfall","topic:troll"},src={"Wowpedia: Sheathed Trol'kalar","Trol'kalar (2)"}}
E["item:sigil-fragment"] = {t="item",n="Sigil Fragment",z="arathi",s="The Sigil Fragment is one piece of a protective sigil sought in the Arathi Highlands. Tor’gan in Hammerfall can bind the gathered fragments together.",h="The Sigil Fragment is one piece of a protective sigil sought in the Arathi Highlands.",sec={{t="Pieces of a Sigil",b="Stromgarde defenders hold fragments of the sigil in the ruins of Stromgarde. Galen, son of Thoras Trollbane, divided the Sigil of Thoradin into eleven pieces and scattered them among the defenders. Tor’gan, a troll shaman in Hammerfall, can bind the gathered pieces back into the complete sigil.",sp=0}},faq={{q="What is a Sigil Fragment?",a="A Sigil Fragment is one piece of the Sigil of Thoradin, which Galen divided into eleven parts.",al={"sigil piece","what's this fragment","fragment meaning"}},{q="Who has the fragments?",a="Stromgarde defenders in the Arathi Highlands hold the fragments.",al={"where find fragments","who holds sigil pieces","stromgarde fragments"}},{q="Who can put the sigil back together?",a="Tor’gan, the troll shaman in Hammerfall, can bind the fragments into the complete Sigil of Thoradin.",al={"who fixes sigil","tor'gan fragments","rebuild broken sigil"},sp=1},{q="Why was the sigil broken apart?",a="Galen, son of Thoras Trollbane, divided the Sigil of Thoradin into eleven pieces and scattered them among Stromgarde defenders.",al={"why split sigil","who broke it","galen sigil"},sp=1}},ang={["class:Shaman"]="As a shaman, you may recognize Tor’gan’s role: the troll shaman can bind the fragments into a whole sigil."},kw={"arathi highlands","broken sigil","galen","hammerfall","sigil fragment","sigil of thoradin","stromgarde","thoras trollbane","tor'gan"},rel={"quest:640","quest:641","quest:645","zone:arathi","subzone:hammerfall"},src={"Wowpedia: Sigil Fragment","The Broken Sigil"}}
E["item:sigil-of-arathor"] = {t="item",n="Sigil of Arathor",z="arathi",s="The Sigil of Arathor is held by Lieutenant Valorcall, leader of Stromgarde’s cavalry. Zengu in Hammerfall wants it for his search for Trol’kalar.",h="The Sigil of Arathor is held by Lieutenant Valorcall, leader of Stromgarde’s cavalry.",sec={{t="A Cavalry Sigil",b="Lieutenant Valorcall carries the Sigil of Arathor across the Arathi Highlands. He leads the cavalry that serves the human prince and Stromgarde’s defenders. Zengu in Hammerfall seeks the sigil, and Valorcall’s horse lets him cover the countryside swiftly.",sp=0},{t="Zengu’s Purpose",b="Zengu wants the sigil returned to him in Hammerfall. He believes taking it from Valorcall will weaken Stromgarde’s defenders. He also says the sigil brings him one step closer to claiming Trol’kalar.",sp=1}},faq={{q="What is the Sigil of Arathor?",a="The Sigil of Arathor is a token carried by Lieutenant Valorcall, the leader of Stromgarde’s cavalry.",al={"sigil of arathor","arathor sigil"}},{q="Who has the sigil?",a="Lieutenant Valorcall carries the Sigil of Arathor as he rides through the Arathi Highlands.",al={"valorcall sigil","who has it"}},{q="Where is Lieutenant Valorcall?",a="Lieutenant Valorcall rides through the Arathi Highlands, where his horse lets him travel quickly.",al={"where valorcall","find valorcall"}},{q="Who wants the Sigil of Arathor?",a="Zengu in Hammerfall wants the Sigil of Arathor returned to him.",al={"who wants the sigil","zengu wants"}},{q="Why does Zengu want the sigil?",a="Zengu believes taking the sigil will weaken Stromgarde’s defenders and bring him closer to claiming Trol’kalar.",al={"why zengu wants it","trolkalar sigil"}}},ang={["faction:Horde"]="As a member of the Horde, you may hear Zengu in Hammerfall seek the sigil to weaken Stromgarde’s defenders."},kw={"arathi highlands","cavalry","hammerfall","lieutenant valorcall","sigil of arathor","stromgarde","trol'kalar","zengu"},rel={"quest:643","quest:645","zone:arathi","subzone:hammerfall"},src={"Wowpedia: Sigil of Arathor","Sigil of Arathor (Classic)"}}
E["item:sigil-of-ignaeus"] = {t="item",n="Sigil of Ignaeus",z="arathi",s="The Sigil of Ignaeus is formed from four ancient sigils in Hammerfall. Its light can open the way through the wardings on Trollbane's tomb.",h="The Sigil of Ignaeus is formed from four ancient sigils in Hammerfall.",sec={{t="The Joined Sigils",b="In Hammerfall, Zengu gives you the Sigil of Ignaeus after the four separate sigils are brought together. Its glowing lines match the etchings on the face of Trollbane's tomb in the Sanctum at Stromgarde. The tomb's wardings bar the way to what lies within.",sp=0},{t="At Trollbane's Tomb",b="When you match the sigil's lines to the etchings on Trollbane's tomb, a flash of light consumes it. The stone hands release the legendary sword Trol'kalar.",sp=1}},faq={{q="What is the Sigil of Ignaeus?",a="The Sigil of Ignaeus is a single sigil formed when the Sigils of Strom, Thoradin, Arathor, and Trollbane are brought together.",al={"sigil of ig","igneaus sigil","what's the sigil"}},{q="Who gives you the Sigil of Ignaeus?",a="Zengu gives you the Sigil of Ignaeus in Hammerfall.",al={"who has ig sigil","where get sigil","zengu sigil"}},{q="What does the sigil do?",a="Its glowing lines match the etchings on Trollbane's tomb and break the wardings that guard it.",al={"sigil use","why need ig sigil","break tomb ward"},sp=1},{q="Where is Trollbane's tomb?",a="Trollbane's tomb lies in the Sanctum behind the chapel in Stromgarde.",al={"trollbane tomb location","where is tomb","sanctum location"}},{q="What happens to the sigil at the tomb?",a="A flash of light consumes the Sigil of Ignaeus when its lines are matched to the tomb's etchings.",al={"sigil consumed","what happens to sigil","tomb flash"},sp=1}},kw={"hammerfall","igneaus","sanctum","sigil","sigil of ignaeus","stromgarde","trol'kalar","trollbane","zengu"},rel={"quest:645","quest:639","quest:641","quest:643","quest:644","subzone:sanctum-stromgarde-keep","subzone:hammerfall","zone:arathi"},src={"Wowpedia: Sigil of Ignaeus","Trol'kalar (Classic)"}}
E["item:sigil-of-strom"] = {t="item",n="Sigil of Strom",z="arathi",s="The Sigil of Strom is one of the seals protecting Trol'kalar in Trollbane's tomb. Zengu of Hammerfall seeks it among the Syndicate in Stromgarde.",h="The Sigil of Strom is one of the seals protecting Trol'kalar in Trollbane's tomb.",sec={{t="A Stromgarde Sigil",b="The Syndicate took one of the sigils that guard Trol'kalar, the ancient troll-slaying sword. Zengu of Hammerfall needs it as the first step in gathering the seals protecting the blade in Trollbane's tomb.",sp=0}},faq={{q="What is the Sigil of Strom?",a="The Sigil of Strom is one of several seals protecting Trol'kalar in Trollbane's tomb.",al={"sigil of strom meaning","strom sigil","what's the sigil"}},{q="Who wants the Sigil of Strom?",a="Zengu in Hammerfall seeks the Sigil of Strom to begin gathering the seals that protect Trol'kalar.",al={"who needs sigil","zengu sigil","who wants it"}},{q="Where can I find the Sigil of Strom?",a="The Syndicate took the Sigil of Strom, and one of its agents in Stromgarde carries it.",al={"sigil location","where is the strom sigil","find sigil"}},{q="Why does Zengu need the sigil?",a="The sigil is one of several seals Zengu needs to remove Trol'kalar from Trollbane's tomb.",al={"why get sigil","why zengu wants it","trolkalar seals"},sp=1},{q="What is Trol'kalar?",a="Trol'kalar is an ancient sword whose name means troll-slayer in the trolls' tongue. Lord Ignaeus of Strom, called Trollbane, wielded it in battle.",al={"trolkalar sword","troll slayer","trolkalar meaning"}}},kw={"hammerfall","sigil of strom","stromgarde","syndicate","trol'kalar","troll-slayer","trollbane","zengu"},rel={"quest:639","quest:645","quest:638","zone:arathi","subzone:hammerfall","topic:syndicate","topic:troll"},src={"Wowpedia: Sigil of Strom","Sigil of Strom (Classic)"}}
E["item:sigil-of-thoradin"] = {t="item",n="Sigil of Thoradin",z="arathi",s="The Sigil of Thoradin is a restored seal tied to Trollbane's tomb in Arathi Highlands. Zengu at Hammerfall needs it to help open the tomb.",h="The Sigil of Thoradin is a restored seal tied to Trollbane's tomb in Arathi Highlands.",sec={{t="A Restored Seal",b="Zengu in Hammerfall needs the Sigil of Thoradin to help unlock the seal on Trollbane's tomb. Its reconstruction has worked, and the work to reach Trol'kalar can continue. Zengu says the search is only halfway done; the holders of the third sigil move around Arathi.",sp=0}},faq={{q="What does the Sigil of Thoradin open?",a="The restored Sigil of Thoradin can help unlock the seal on Trollbane's tomb.",al={"sigil opens what","tomb seal"}},{q="Who needs the sigil?",a="Zengu at Hammerfall needs the restored Sigil of Thoradin.",al={"who wants the sigil","give sigil to who"}},{q="Why is the sigil important?",a="It is needed to help remove Trol'kalar from Trollbane's tomb.",al={"why sigil matters","sigil purpose"},sp=1},{q="Where is the third sigil?",a="Zengu does not know where the third sigil is; its holders move around Arathi.",al={"third sigil location","where third one"}}},kw={"arathi","hammerfall","sigil of thoradin","thoradin","tomb","trol'kalar","trollbane","zengu"},rel={"quest:641","quest:645","quest:638","subzone:hammerfall","zone:arathi"},src={"Wowpedia: Sigil of Thoradin","Sigil of Thoradin (Classic)"}}
E["item:sigil-of-trollbane"] = {t="item",n="Sigil of Trollbane",z="arathi",s="Prince Galen Trollbane keeps the Sigil of Trollbane within Stromgarde. Zengu in Hammerfall seeks it, and you must face the prince to claim it.",h="Prince Galen Trollbane keeps the Sigil of Trollbane within Stromgarde.",sec={{t="The Last Sigil",b="Zengu in Hammerfall seeks the final sigil, which Prince Galen keeps within Stromgarde. Galen lives in a chapel in the militia-held district and is well protected. Bring the sigil to Zengu, and the way to Thoras Trollbane’s tomb can be opened.",sp=0}},faq={{q="What is the Sigil of Trollbane for?",a="The Sigil of Trollbane is the final sigil needed to open Thoras Trollbane’s tomb and claim Trol’kalar.",al={"sigil purpose","why need the sigil","trollbane sigil"},sp=2},{q="Who has the Sigil of Trollbane?",a="Prince Galen Trollbane holds the Sigil of Trollbane in Stromgarde.",al={"who has it","sigil holder","galen sigil"}},{q="Where can I find Prince Galen?",a="Prince Galen resides in a chapel in the militia-held district of Stromgarde.",al={"where is galen","galen location","find prince trollbane"}},{q="Who wants the sigil?",a="Zengu in Hammerfall seeks the Sigil of Trollbane.",al={"who wants it","sigil for zengu","hammerfall sigil"}},{q="What comes after the sigils are gathered?",a="With the sigils in hand, Zengu plans to strike against the trolls of Zul’Gurub and take Trol’kalar from Thoras Trollbane’s tomb.",al={"what next after sigils","trolkalar next","unlock tomb"},sp=1}},ang={["class:Warrior"]="As a warrior, you may find Prince Galen a fitting guardian for the last sigil; he is himself a seasoned fighter."},kw={"galen trollbane","prince galen","sigil of trollbane","stromgarde","thoras trollbane","trol'kalar","trollbane","zengu"},rel={"quest:644","quest:645","quest:638","zone:arathi","subzone:hammerfall","subzone:zul-gurub"},src={"Wowpedia: Sigil of Trollbane","Sigil of Trollbane (quest)"}}
E["item:spirit-of-silverpine-charts"] = {t="item",n="Spirit of Silverpine Charts",z="arathi",s="The Spirit of Silverpine Charts are the ship’s maps, now sought from its wreck in the Arathi Highlands. First Mate Nilzlix wants them secured before the information reaches prying eyes.",h="The Spirit of Silverpine Charts are the ship’s maps, now sought from its wreck in the Arathi Highlands.",sec={{t="Aground in the Cove",b="The wreck’s charts are wanted alongside the ship’s log, so First Mate Nilzlix asks you to recover both. The crew says the Spirit of Silverpine ran aground on a temple in the reef when the tides fell. Its charts hold information the crew fears could reach enemy hands, and Fleet Master Seahorn expects them brought back to Booty Bay.",sp=0}},faq={{q="What are the Spirit of Silverpine Charts?",a="They are map charts belonging to the Spirit of Silverpine, a ship wrecked in the Arathi Highlands.",al={"silverpine charts","spirit charts"}},{q="Where can I find the charts?",a="The Spirit of Silverpine Charts are sought from the wreck of the Spirit of Silverpine in the Arathi Highlands.",al={"where charts","silverpine map location"}},{q="Who wants the charts?",a="First Mate Nilzlix wants the charts and logs from the Spirit of Silverpine and the Maiden's Folly recovered.",al={"who needs charts","nilzlix charts"}},{q="Why are the charts wanted?",a="The crew fears the charts could expose information to prying eyes if left behind.",al={"why charts matter","what's in the charts"}},{q="How did the Spirit of Silverpine sink?",a="The crew says the Spirit of Silverpine ran aground on a temple in the reef when the tides began to lower.",al={"silverpine wreck","why ship sank"}},{q="Where are the charts being taken?",a="The recovered charts are meant to be secured for Fleet Master Seahorn and the command in Booty Bay.",al={"charts to booty bay","who gets the charts"}}},kw={"arathi highlands","charts","deep sea salvage","first mate nilzlix","fleet master seahorn","spirit of silverpine","spirit of silverpine charts"},rel={"quest:662","item:spirit-of-silverpine-log","item:maiden-s-folly-charts","item:maiden-s-folly-log","npc:fleet-master-seahorn","zone:arathi"},src={"Wowpedia: Spirit of Silverpine Charts","Deep Sea Salvage"}}
E["item:spirit-of-silverpine-log"] = {t="item",n="Spirit of Silverpine Log",z="arathi",s="The Spirit of Silverpine Log is the captain’s record from a ship wrecked in Arathi’s reef. Its charts and log hold information the crew wants kept from enemy hands.",h="The Spirit of Silverpine Log is the captain’s record from a ship wrecked in Arathi’s reef.",sec={{t="The Wrecked Ships",b="First Mate Nilzlix wants the ship’s log and charts recovered before the crew leaves the cove. The Spirit of Silverpine and the Maiden’s Folly ran aground when the tide fell, striking what seemed to be a temple in the reef. Both ships sank quickly. Their records now matter to the command in Booty Bay, which fears the information could reach its enemies.",sp=0}},faq={{q="What is the Spirit of Silverpine Log?",a="It is the captain’s log book from the Spirit of Silverpine, one of the ships wrecked in the Arathi Highlands.",al={"silverpine log","ship log","captain log"}},{q="Where did the Spirit of Silverpine sink?",a="The Spirit of Silverpine ran aground on what seemed to be a temple in the reef at a cove in the Arathi Highlands.",al={"where is silverpine","silverpine wreck","ship in arathi"}},{q="Why does First Mate Nilzlix want the log?",a="First Mate Nilzlix wants the Spirit of Silverpine’s log and charts recovered before the crew leaves, so their information does not fall into enemy hands.",al={"why get the log","nilzlix wants what","retrieve silverpine log"}},{q="What happened to the Spirit of Silverpine?",a="As the tide lowered, the Spirit of Silverpine ran aground on what seemed to be a temple in the reef and sank quickly.",al={"silverpine wreck","what happened to ship","ship sank how"}},{q="Why are the charts and logs important?",a="The crew fears the records could fall into enemy hands, and Fleet Master Seahorn would hold them responsible if that happened.",al={"why recover charts","enemy hands","booty bay records"}}},kw={"arathi highlands","booty bay","captain's log","deep sea salvage","first mate nilzlix","fleet master seahorn","shipwreck","spirit of silverpine","spirit of silverpine log"},rel={"quest:662","item:spirit-of-silverpine-charts","item:maiden-s-folly-log","item:maiden-s-folly-charts","zone:arathi","npc:fleet-master-seahorn"},src={"Wowpedia: Spirit of Silverpine Log","Deep Sea Salvage"}}
E["item:tor-gan-s-orb"] = {t="item",n="Tor'gan's Orb",z="arathi",s="Tor'gan's Orb carries raptor essence to Gor'mul at Hammerfall. Tor'gan hopes its power will restore the old warrior's purpose.",h="Tor'gan's Orb carries raptor essence to Gor'mul at Hammerfall.",sec={{t="Raptor Essence",b="At Hammerfall, Tor'gan gives you an orb charged with the power and spirit of raptors. He asks you to bring it to Gor'mul, hoping its energy will restore the warrior's spirit and give him new purpose.",sp=0}},faq={{q="What does Tor'gan's Orb do?",a="Tor'gan's Orb carries raptor power and spirit, meant to give Gor'mul the essence of the raptor.",al={"what orb do","orb purpose"}},{q="Who is the orb for?",a="Tor'gan asks you to bring the orb to Gor'mul at Hammerfall.",al={"orb for who","who gets tor'gan orb"}},{q="Who made Tor'gan's Orb?",a="Tor'gan provides the orb and charges it with raptor essence.",al={"who made orb","tor'gan orb maker"}},{q="Why does Gor'mul need the orb?",a="Tor'gan hopes the raptor essence will invigorate Gor'mul's spirit and give him new purpose.",al={"why gor'mul orb","gor'mul purpose"}}},ang={["faction:Horde"]="As a member of the Horde, you carry the orb to Gor'mul so he may learn the Horde's present state and lend his strength to its battles."},kw={"arathi highlands","gor'mul","hammerfall","raptor essence","raptor hearts","tor'gan","tor'gan's orb"},rel={"subzone:hammerfall","topic:horde","quest:701","zone:arathi"},src={"Wowpedia: Tor'gan's Orb","Guile of the Raptor (2)"}}
E["item:trelane-s-ember-agate"] = {t="item",n="Trelane's Ember Agate",z="arathi",s="Trelane's Ember Agate is kept in a chest within a tower in Arathi Highlands. Skuerto at Refuge Pointe seeks it alongside two other relics belonging to Trelane.",h="Trelane's Ember Agate is kept in a chest within a tower in Arathi Highlands.",sec={{t="The Agate",b="Within the tower in Arathi Highlands, Trelane's Ember Agate rests in a chest. Skuerto at Refuge Pointe asks you to recover it with Trelane's Orb and Trelane's Phylactery. Ogres guard the tower, so the search is not without danger.",sp=0}},faq={{q="Where is Trelane's Ember Agate?",a="Trelane's Ember Agate is in a chest within a tower in Arathi Highlands.",al={"ember agate location","where agate","trelane agate"}},{q="Who wants the Ember Agate?",a="Skuerto at Refuge Pointe asks you to bring back Trelane's Ember Agate, along with Trelane's Orb and Trelane's Phylactery.",al={"who wants agate","skuerto agate","return agate to who"}},{q="What else is in the tower?",a="Trelane's Orb and Trelane's Phylactery are also sought from chests in the tower.",al={"other items tower","trelane relics","orb and phylactery"}},{q="What guards the tower?",a="Ogres guard the tower where Trelane's Ember Agate is kept.",al={"tower guards","ogres in tower","trelane tower danger"}}},kw={"arathi highlands","attack on the tower","ember agate","refuge pointe","skuerto","trelane","trelane's ember agate"},rel={"quest:696","item:trelane-s-orb","item:trelane-s-phylactery","npc:skuerto","zone:arathi","subzone:refuge-pointe"},src={"Wowpedia: Trelane's Ember Agate","Attack on the Tower (Classic)"}}
E["item:trelane-s-orb"] = {t="item",n="Trelane's Orb",z="arathi",s="In the ogre-held tower in Arathi Highlands, Trelane’s Orb is one of three objects Skuerto asks you to recover. It is kept in a chest alongside Trelane’s Phylactery and Trelane’s Ember Agate.",h="In the ogre-held tower in Arathi Highlands, Trelane’s Orb is one of three objects Skuerto asks you to recover.",sec={{t="The Tower Chest",b="Skuerto at Refuge Pointe sends you to the tower in Arathi Highlands for Trelane’s Orb and two other objects. The orb is kept in a chest within the tower. Ogres guard the place, so Skuerto warns you to be ready if they discover you among their chests.",sp=0}},faq={{q="Where is Trelane’s Orb?",a="Trelane’s Orb is in a chest inside the tower in Arathi Highlands.",al={"orb location","where orb","trelane orb chest"}},{q="Who wants Trelane’s Orb?",a="Skuerto at Refuge Pointe asks you to recover Trelane’s Orb and bring it back.",al={"who wants orb","skuerto orb","who do i take it to"}},{q="What else is in the tower?",a="Trelane’s Phylactery and Trelane’s Ember Agate are also kept in chests within the tower.",al={"other tower items","trelane items","what else to find"}},{q="Who guards the tower?",a="Ogres guard the tower in Arathi Highlands.",al={"tower guards","ogres there","what's in the tower"}}},kw={"arathi highlands","ogres","orb","refuge pointe","skuerto","tower","trelane","trelane's orb"},rel={"quest:696","item:trelane-s-phylactery","item:trelane-s-ember-agate","npc:skuerto","zone:arathi","subzone:refuge-pointe"},src={"Wowpedia: Trelane's Orb","Attack on the Tower (Classic)"}}
E["item:trelane-s-phylactery"] = {t="item",n="Trelane's Phylactery",z="arathi",s="Trelane’s Phylactery is one of three objects sought from the tower in Arathi Highlands. Skuerto at Refuge Pointe asks you to bring it back with Trelane’s Orb and Trelane’s Ember Agate.",h="Trelane’s Phylactery is one of three objects sought from the tower in Arathi Highlands.",sec={{t="The Tower’s Chests",b="Skuerto at Refuge Pointe sends you to find Trelane’s Phylactery in the tower. Trelane’s Orb and Trelane’s Ember Agate are there as well, kept in chests among the ogres. Bring all three objects back, and Malin will hear of your success.",sp=0}},faq={{q="Where do I find Trelane’s Phylactery?",a="Trelane’s Phylactery is in a chest inside the tower in Arathi Highlands.",al={"phylactery location","where is trelane's phylactery"}},{q="Who wants the phylactery?",a="Skuerto at Refuge Pointe asks you to bring Trelane’s Phylactery back with Trelane’s Orb and Trelane’s Ember Agate.",al={"who wants it","skuerto phylactery"}},{q="What else is in the tower’s chests?",a="Trelane’s Orb and Trelane’s Ember Agate are also kept in chests inside the tower.",al={"other tower items","trelane items"}},{q="Why does Skuerto want these objects?",a="Archmage Malin sent Skuerto to Arathi to gather what he needs, and Skuerto says Malin will be pleased when you return with Trelane’s Phylactery, Trelane’s Orb and Trelane’s Ember Agate.",al={"why collect them","what does malin want"}}},kw={"arathi highlands","ember agate","phylactery","refuge pointe","skuerto","tower","trelane","trelane's orb","trelane's phylactery"},rel={"quest:696","item:trelane-s-orb","item:trelane-s-ember-agate","npc:skuerto","zone:arathi","subzone:refuge-pointe"},src={"Wowpedia: Trelane's Phylactery","Attack on the Tower (Classic)"}}
E["item:trelane-s-wand-of-invocation"] = {t="item",n="Trelane's Wand of Invocation",z="arathi",s="Trelane's Wand of Invocation is held by Kor'gresh in Boulderfist Hall. Skuerto at Refuge Pointe wants it recovered before the ogre masters its powers.",h="Trelane's Wand of Invocation is held by Kor'gresh in Boulderfist Hall.",sec={{t="The Wand's Trail",b="Skuerto has traced Trelane's Wand of Invocation to Boulderfist Hall in the Arathi Highlands. Kor'gresh keeps it there and uses blasts of ice to control the other ogres. The wand is the first item on Skuerto's list, and its recovery is part of his plan concerning Stromgarde.",sp=0}},faq={{q="Who has Trelane's wand?",a="Kor'gresh has Trelane's Wand of Invocation in Boulderfist Hall, east of Thandol Span.",al={"who has the wand","kor'gresh wand","wand location"}},{q="Where do I take the wand?",a="Take Trelane's Wand of Invocation to Skuerto at Refuge Pointe.",al={"where return wand","skuerto wand","wand over fist"}},{q="What is Kor'gresh doing with it?",a="Kor'gresh uses blasts of ice to keep the other ogres in line, suggesting he is learning the wand's powers.",al={"ogre ice blasts","kor'gresh powers","what's the ogre doing"}},{q="Why does Skuerto want the wand?",a="The wand is the first of four items on Skuerto's list. He is working on a plan concerning Stromgarde.",al={"why get wand","skuerto's plan","stromgarde plan"}}},kw={"boulderfist hall","kor'gresh","refuge pointe","skuerto","stromgarde","trelane's wand","wand of invocation","wand over fist"},rel={"quest:693","npc:skuerto","subzone:boulderfist-hall","subzone:refuge-pointe","zone:arathi","subzone:thandol-span"},src={"Wowpedia: Trelane's Wand of Invocation","Wand over Fist (Classic)"}}
E["item:witherbark-medicine-pouch"] = {t="item",n="Witherbark Medicine Pouch",z="arathi",s="A Witherbark Medicine Pouch is carried by the witch doctors of Witherbark Village in the Arathi Highlands. Apprentice Kryten seeks several for Archmage Malin’s research.",h="A Witherbark Medicine Pouch is carried by the witch doctors of Witherbark Village in the Arathi Highlands.",sec={{t="A Witch Doctor’s Pouch",b="At Witherbark Village in the Arathi Highlands, the witch doctors carry medicine pouches. Apprentice Kryten needs four of them, along with Witherbark tusks and a Shadow Hunter Knife, for Archmage Malin.",sp=0}},faq={{q="Who needs the medicine pouches?",a="Apprentice Kryten at Refuge Pointe needs four Witherbark Medicine Pouches for Archmage Malin’s research.",al={"who wants the pouch","medicine pouch for who"}},{q="Where do the pouches come from?",a="Witherbark Witch Doctors at Witherbark Village in the Arathi Highlands carry the medicine pouches.",al={"where pouch from","witherbark pouch location"}},{q="How many pouches does Kryten need?",a="Kryten needs four Witherbark Medicine Pouches.",al={"how many pouches","number of medicine pouches"}},{q="What else is Kryten collecting?",a="Kryten also seeks ten Witherbark Tusks and a Shadow Hunter Knife for Archmage Malin.",al={"what else does kryten need","other items for malin"}}},kw={"arathi highlands","archmage malin","kryten","medicine pouch","refuge pointe","witch doctor","witherbark","witherbark medicine pouch"},rel={"quest:691","zone:arathi","subzone:witherbark-village","subzone:refuge-pointe","item:witherbark-tusk","item:shadow-hunter-knife"},src={"Wowpedia: Witherbark Medicine Pouch","Worth Its Weight in Gold (Classic)"}}
E["item:witherbark-tusk"] = {t="item",n="Witherbark Tusk",z="arathi",s="A Witherbark Tusk is a trophy taken from the trolls of southeastern Arathi. Apprentice Kryten needs ten for Archmage Malin’s research at Refuge Pointe.",h="A Witherbark Tusk is a trophy taken from the trolls of southeastern Arathi.",sec={{t="A Troll’s Tusk",b="At Refuge Pointe, Apprentice Kryten gathers reagents for Archmage Malin’s research. The tusks come from Witherbark trolls in the southeastern highlands, where the tribe makes its home. Kryten needs ten, alongside medicine pouches and a shadow hunter’s knife.",sp=0}},faq={{q="Who needs Witherbark Tusks?",a="Apprentice Kryten at Refuge Pointe needs ten Witherbark Tusks for Archmage Malin’s research.",al={"who wants the tusks","Kryten tusks","tusks for Malin"}},{q="Where do Witherbark Tusks come from?",a="Witherbark Tusks come from the Witherbark trolls living southeast of Refuge Pointe in Arathi Highlands.",al={"where tusks from","tusk location","find Witherbark tusks"}},{q="Why does Kryten need the tusks?",a="Kryten is collecting reagents for Archmage Malin’s research, and the tusks are among the items he needs.",al={"why tusks","Kryten research","Malin reagents"}},{q="How many tusks does Kryten need?",a="Kryten needs ten Witherbark Tusks, along with four medicine pouches and a Shadow Hunter Knife.",al={"tusk count","how many tusks","ten tusks"}}},kw={"arathi highlands","archmage malin","kryten","reagents","refuge pointe","tusk","witherbark","witherbark tusk"},rel={"quest:691","item:witherbark-medicine-pouch","item:shadow-hunter-knife","zone:arathi","subzone:witherbark-village"},src={"Wowpedia: Witherbark Tusk","Worth Its Weight in Gold (Classic)"}}
E["npc:doctor-gregory-victor"] = {t="npc",n="Doctor Gregory Victor",z="arathi",s="At Hammerfall, Doctor Gregory Victor tends the Horde’s wounded and trains medics for the fighting in the Arathi Highlands. Renowned as its premier trauma physician, he teaches advanced triage and battlefield first aid.",h="At Hammerfall, Doctor Gregory Victor tends the Horde’s wounded and trains medics for the fighting in the...",sec={{t="Surgeon of Hammerfall",b="Doctor Gregory Victor treats the Horde’s wounded at Hammerfall, in the contested Arathi Highlands. Though many distrust Forsaken apothecaries, he uses surgery instead of blighted alchemy on soldiers hurt by Syndicate brigands, Boulderfist ogres, and Alliance forces. Hammerfall is the Horde’s main proving ground for field medics, and Victor demands speed and care when the most critical patients are under pressure.",sp=0}},faq={{q="Who is Doctor Gregory Victor?",a="Doctor Gregory Victor is a Forsaken physician at Hammerfall in the Arathi Highlands and the Horde’s premier trauma surgeon. He oversees triage and trains advanced field medics.",al={"doctor victor","gregory victor","who is gregory victor"},it="identity"},{q="Where can I find Doctor Gregory Victor?",a="You can find Doctor Gregory Victor inside Hammerfall, in northeastern Arathi Highlands.",al={"gregory victor location","where is victor","doctor victor where"},it="place",gp=true},{q="What role does he play for the Horde?",a="Doctor Victor tests promising field medics in battlefield triage. He teaches them to stabilize the dying and make advanced cloth bandages for frontline combat.",al={"what does gregory victor do","gregory victor first aid","horde trauma doctor"},it="purpose"},{q="Who is his Alliance counterpart?",a="Doctor Gustaf VanHowzen is the Alliance counterpart. He oversees advanced trauma and triage training at Theramore Isle in Dustwallow Marsh.",al={"alliance equivalent doctor victor","alliance triage doctor"},gp=true},{q="Whose side is Doctor Gregory Victor on?",a="Doctor Gregory Victor is loyal to the Horde and the Forsaken. Stationed out at Hammerfall in the Arathi Highlands, he serves as an expert surgeon attending to the faction's wounded and passing on advanced triage knowledge to those willing to learn.",al={"what faction is gregory victor","is doctor victor horde","doctor victor allegiance"},it="side",add="d46fa605"},{q="What does Doctor Gregory Victor want?",a="Doctor Victor is dedicated to field medicine and surgery. He seeks capable battlefield medics who can handle high-pressure triage, testing aspiring healers to ensure they can prioritize treatments and save lives amid the chaos of war.",al={"what does doctor victor want","doctor gregory victor goals","what is victor doing"},it="wants",add="5e053b25"},{q="Why is Doctor Gregory Victor here?",a="Doctor Victor is stationed in Hammerfall to support the Horde's front lines in the contested Arathi Highlands. With constant skirmishes erupting against the Alliance and local threats, an experienced trauma surgeon is essential to keep soldiers alive.",al={"why is gregory victor here","why is doctor victor in hammerfall","reason victor is here"},it="why_here",add="3e1305a9"}},ang={["faction:Horde"]="As a member of the Horde, you can look to Doctor Victor for battlefield medicine at a precarious outpost. He helps warriors on the Arathi front return to fighting shape.",["race:Undead"]="As an undead, you can see Doctor Victor’s work as proof that the Forsaken can master mortal anatomy and restorative surgery, apart from the Royal Apothecary Society’s toxic concoctions."},kw={"arathi highlands","doctor gregory victor","first aid","gregory victor","hammerfall","horde trauma","surgeon","triage"},rel={"subzone:hammerfall","quest:6623","zone:arathi","npc:doctor-gustaf-vanhowzen","topic:forsaken","topic:horde"},src={"Doctor Gregory Victor"}}
E["npc:drum-fel"] = {t="npc",n="Drum Fel",z="arathi",s="At Hammerfall, Drum Fel directs the Horde’s fight to hold Arathi against trolls, ogres, and human remnants. With his wife Korin, he seeks a lasting foothold for the Horde in the region.",h="At Hammerfall, Drum Fel directs the Horde’s fight to hold Arathi against trolls, ogres, and human remnants.",sec={{t="Warden of Hammerfall",b="Drum Fel commands Hammerfall’s defenses and leads the Horde’s push into Arathi. From this fortified refuge, he faces rival factions on every side. The Witherbark forest trolls and Boulderfist ogres hold Boulder'gor and Boulderfist Hall. Drum knows Hammerfall cannot thrive in isolation, so their strength must be broken. He sends veteran champions into hostile territory to disrupt these threats before they can strike the encampment.",sp=0},{t="The Threat in Stromgarde",b="Drum Fel carries his campaign into Stromgarde Keep, where Boulderfist ogres hold among the ruins of the fallen human kingdom. Years ago, Drum defeated the ogre brute Or'Kalar, who has not forgotten the defeat. Now Or'Kalar waits inside Stromgarde, seeking vengeance. Korin, Drum’s wife, quietly hides his presence from her husband. She relies on outside adventurers to remove the threat before Drum charges into an ambush.",sp=1}},faq={{q="Who is Drum Fel?",a="Drum Fel leads the Horde’s military effort from Hammerfall in the Arathi Highlands. He directs campaigns against rival factions in the region.",al={"drum fel","who is drum fel","hammerfall drum"},it="identity"},{q="Where can Drum Fel be found?",a="Drum Fel can be found inside Hammerfall, in northeastern Arathi Highlands, just east of the main road north into the Hinterlands.",al={"drum fel location","where is drum fel","find drum fel"},it="place",gp=true},{q="Who is Korin Fel?",a="Korin Fel is Drum Fel’s wife, and she lives in Hammerfall.",al={"korin fel","drum fel wife"},it="ties"},{q="Why does the ogre Or'Kalar want Drum Fel dead?",a="Years ago, Drum Fel defeated Or'Kalar in battle. The humiliated ogre now waits in the ruins of Stromgarde Keep, seeking vengeance against Drum.",al={"orkalar grudge","why does orkalar hate drum fel","or'kalar drum fel"},it="conflict"},{q="What threats does Drum Fel target?",a="Drum Fel directs strikes against the Boulderfist ogres at Boulder'gor, Boulderfist Hall, and Stromgarde Keep. He also targets the nearby Witherbark troll tribe.",al={"drum fel quests","drum fel enemies","who does drum fel fight"},it="threat"},{q="Whose side is Drum Fel on?",a="Drum Fel is a stalwart leader within the Horde. Stationed at the outpost of Hammerfall, he directs military efforts to secure the safety and dominance of the Horde across the Arathi Highlands.",al={"drum fel faction","who does drum fel serve","drum fel horde"},it="side",add="51d7fbcd"},{q="What does Drum Fel want?",a="Drum Fel wants to ensure that Hammerfall survives and thrives amidst hostile territory. To protect the settlement, he orders decisive campaigns against rival forces threatening the region, including the Boulderfist ogres, the Witherbark trolls, and hostile occupants within the ruins of Stromgarde Keep.",al={"drum fel goals","what does drum fel need","drum fel motive"},it="wants",add="828c27d6"},{q="Why is Drum Fel in Hammerfall?",a="Drum Fel oversees military operations from Hammerfall to safeguard the Horde's foothold in the Arathi Highlands. From this bastion, he coordinates the defense of his people against surrounding threats that seek to wipe the settlement out.",al={"why is drum fel here","drum fel arathi","drum fel purpose arathi"},it="why_here",add="def003ab"}},ang={["faction:Horde"]="For Horde warriors advancing through the Eastern Kingdoms, Drum Fel coordinates the effort to secure the fragile lifeline between the Undercity and the southern territories.",["race:Orc"]="As an orc, Drum Fel shows the hard resolve needed to rebuild orcish lives in the Eastern Kingdoms. He holds ground in the land where the internment camps once stood."},kw={"arathi highlands","boulderfist","drum fel","hammerfall","korin fel","orkalar","witherbark"},rel={"subzone:hammerfall","zone:arathi","npc:tallow","subzone:stromgarde-keep","subzone:boulder-gor","subzone:boulderfist-hall","quest:676","topic:horde"},src={"Drum Fel"}}
E["npc:foggy-mackreel"] = {t="npc",n="Foggy MacKreel",z="arathi",s="On the broken Thandol Span, Foggy MacKreel is stranded above a dizzying drop with a moonshine delivery bound for Southshore on his mind.",h="On the broken Thandol Span, Foggy MacKreel is stranded above a dizzying drop with a moonshine delivery bound...",sec={{t="Stranded on the Span",b="Foggy MacKreel waits on broken pylons beneath the Thandol Span, calm on his dangerous perch. Dark Iron sabotage and war damage shattered the bridge between the Wetlands and the Arathi Highlands. Rescue can wait; MacKreel wants his potent moonshine delivered to the patrons of Southshore in the Hillsbrad Foothills. So he hires passing travelers nimble enough to reach his ledge and finish the delivery.",sp=0}},faq={{q="Who is Foggy MacKreel?",a="Foggy MacKreel is a dwarf courier stranded on ruined stone pillars beneath the broken Thandol Span. The drop does not trouble him; he is focused on delivering his moonshine.",al={"foggy mackreel","who is foggy","mackreel npc"},it="identity"},{q="Where can I find Foggy MacKreel?",a="Foggy MacKreel waits on a stone platform midway down the broken central span of the Thandol Span. Carefully jump down from the bridge structure on the Arathi Highlands side to reach him.",al={"where is foggy mackreel","foggy mackreel location","how to find mackreel"},it="place",gp=true},{q="Why is Foggy MacKreel down there?",a="Foggy MacKreel became stuck in the Thandol Span wreckage during his travels. His chief concern is finding someone to carry his moonshine the rest of the way to Southshore.",al={"why is foggy stranded","how did mackreel get there","why is he on the bridge"},it="why_here"},{q="What quest does Foggy MacKreel offer?",a="Foggy MacKreel offers MacKreel's Moonshine and asks travelers to carry a jug of his potent brew to the tavern in Southshore, across the Arathi Highlands.",al={"foggy quest","mackreel moonshine quest","what quest does foggy give"},it="purpose",gp=true},{q="Whose side is Foggy MacKreel on?",a="Foggy MacKreel is an Alliance-aligned dwarf. Even stranded precariously along the damaged ruins of the Thandol Span, his loyalties and dealings lie squarely with his kin and fellow Alliance settlements, most notably aiming to get his potent brew north into the hands of the folk holding Southshore in the Hillsbrad Foothills.",al={"foggy mackreel faction","is foggy mackreel alliance","foggy mackreel side"},it="side",add="28a25d1f"},{q="What does Foggy MacKreel want?",a="Foggy MacKreel wants his special batch of moonshine safely carried to Southshore. Despite being trapped on a shattered pillar beneath the bridge, he shows surprisingly little care for his own perilous situation, remaining entirely preoccupied with ensuring his brew reaches its destination in Hillsbrad rather than plotting an immediate rescue.",al={"foggy mackreel motive","what does foggy want","foggy mackreel goal"},it="wants",add="c1253653"}},ang={["race:Dwarf"]="As a dwarf, you may know MacKreel's stubborn grit and peculiar priorities. He cares more about delivering strong liquor on time than being stranded over a fatal chasm.",["faction:Alliance"]="As an Alliance courier traveling between Ironforge and Southshore, you may cross paths with Foggy and carry his stranded cargo for a fellow subject of the Alliance."},kw={"arathi","foggy","mackreel","moonshine","southshore","thandol span","wetlands"},rel={"quest:647","subzone:thandol-span","subzone:southshore","zone:arathi","zone:wetlands","topic:dwarf"},src={"Foggy MacKreel"}}
E["npc:orgrim-doomhammer"] = {t="npc",n="Orgrim Doomhammer",z="arathi",s="During the Second War, Orgrim Doomhammer led the Old Horde as its supreme Warchief. He became one of history’s greatest orc warriors. He died freeing the internment camps in the Arathi Highlands, but his legacy lives on in Orgrimmar and through Thrall, who inherited his warhammer and black plate armor.",h="During the Second War, Orgrim Doomhammer led the Old Horde as its supreme Warchief.",sec={{t="Rise of the Warchief",b="Orgrim Doomhammer rose from second-in-command to become Chieftain of the Blackrock clan. Gul'dan offered him demonic blood, but Orgrim refused and kept his doubts hidden beneath fierce loyalty. Near the end of the First War, he turned against the Shadow Council after its treachery and the murder of his childhood friend Durotan.\n\nOrgrim slew Blackhand in honorable combat and took the mantle of Warchief. He purged Gul'dan's warlocks and led the Horde across the Eastern Kingdoms during the Second War. A devastating strategist, he drove human kingdoms to the brink of ruin. Gul'dan's betrayal split his forces, and Orgrim was defeated and captured outside Blackrock Spire.",sp=0},{t="Fall and Legacy",b="Orgrim Doomhammer escaped human captivity and lived in hiding until he met Thrall, Durotan's orphaned son. The young shaman's vision gave Orgrim new purpose, and he rallied the remaining orcish clans to storm the internment camps and free their people.\n\nDuring a fierce battle at an encampment in the Arathi Highlands, a lance struck the Warchief from behind. As he lay dying, Orgrim gave Thrall his black plate armor, his ancestral weapon, the Doomhammer, and the title of Warchief. The liberated outpost was renamed Hammerfall in his honor, and the newly founded capital in Durotar was named Orgrimmar.",sp=0}},faq={{q="Who was Orgrim Doomhammer?",a="Orgrim Doomhammer was Chieftain of the Blackrock clan and Warchief of the Horde during the Second War. After escaping human captivity, he fought beside Thrall to free their imprisoned kin and died in the Arathi Highlands.",al={"who is doomhammer","orgrim doomhammer background","who was warchief doomhammer"}},{q="How did Orgrim Doomhammer die?",a="Orgrim Doomhammer was struck from behind by a knight's lance during an assault on a human internment camp in the Arathi Highlands. Thrall took up his mantle, and the site was named Hammerfall in his memory.",al={"orgrim doomhammer death","how did doomhammer die","who killed doomhammer"}},{q="Why is the Horde capital named Orgrimmar?",a="Thrall named the fortified city in Durotar for Orgrim Doomhammer, his mentor and predecessor. Orgrim saw promise in Thrall and named him the new Warchief, so the Horde could rebuild on honor rather than demonic corruption.",al={"why is it called orgrimmar","orgrimmar namesake","city named after orgrim"}},{q="Did Orgrim drink the demon blood?",a="No. Orgrim Doomhammer refused the demonic blood and concealed his doubts behind loyalty to Blackhand. He later destroyed Gul'dan's Shadow Council from within.",al={"did doomhammer drink blood","was orgrim corrupted","orgrim demon blood"}}},ang={["race:Orc"]="As an orc, you revere Orgrim Doomhammer for freeing your people from lethargy and internment. He chose honor over demonic subjugation.",["faction:Alliance"]="To the Alliance, Orgrim Doomhammer remains a grim symbol of how close the Eastern Kingdoms came to ruin during the Second War. He butchered countless champions before his defeat at Blackrock Spire."},kw={"blackhand","blackrock","doomhammer","hammerfall","orgrim","orgrimmar","thrall","warchief"},rel={"subzone:hammerfall","zone:orgrimmar","zone:arathi","topic:blackrock-clan","topic:old-horde","topic:second-war","topic:first-war","topic:horde"},src={"Orgrim Doomhammer"}}
E["npc:skuerto"] = {t="npc",n="Skuerto",z="arathi",s="At Refuge Pointe, Skuerto scouts the dangerous Arathi Highlands for the Alliance. Archmage Malin sent him with Apprentice Kryten to gather arcane reagents and recover artifacts once owned by Malin's old master, Archmage Trelane.",h="At Refuge Pointe, Skuerto scouts the dangerous Arathi Highlands for the Alliance.",sec={{t="A Scout in the Highlands",b="Skuerto scouts the dangerous Arathi Highlands for the Alliance. The Ironforge dwarf is stationed at Refuge Pointe with Apprentice Kryten. Archmage Malin directs their search for arcane reagents and powerful artifacts once owned by his old master, Archmage Trelane.",sp=0},{t="Pride and Peril",b="Skuerto takes pride in scouting the harsh Highlands and bristles when anyone questions his skill. His work brings him near the region's dangers: the hostile Syndicate, Boulderfist ogres, and ancient entities bound to the land.",sp=0}},faq={{q="Why is Skuerto stationed in Arathi instead of Ironforge?",a="Archmage Malin sent Skuerto to Refuge Pointe with Apprentice Kryten. They gather reagents and recover items left behind by Malin's old master, Archmage Trelane, who fled Stromgarde when it fell under siege.",al={"why is skuerto here","skuerto backstory"},it="why_here"},{q="What is Skuerto's mission at Refuge Pointe?",a="Skuerto and Apprentice Kryten gather arcane reagents and recover powerful magical artifacts once owned by Archmage Trelane, Malin's former master.",al={"skuerto purpose","what does skuerto do","skuerto malin"},it="purpose"},{q="Who are Skuerto's allies in the region?",a="Skuerto works with Apprentice Kryten, his partner in Archmage Malin's work, and with the Alliance defenders holding Refuge Pointe.",al={"skuerto friends"},it="allies"},{q="Who is Skuerto?",a="Skuerto is an Ironforge dwarf scout stationed at Refuge Pointe in the Arathi Highlands. Proud of his reconnaissance skills and notably sensitive to criticism, he operates in the field alongside Apprentice Kryten on behalf of the Alliance.",al={"who is skuerto","skuerto identity","who is the dwarf skuerto"},it="identity",add="9a7bedf3"},{q="Whose side is Skuerto on?",a="Skuerto is firmly loyal to the Alliance and Ironforge. Operating out of the Alliance encampment at Refuge Pointe, he works in coordination with Dalaran mages and local Alliance forces against the threats looming over the Arathi Highlands.",al={"skuerto faction","is skuerto alliance","skuerto allegiances"},it="side",add="1cc8a254"},{q="What does Skuerto want?",a="Skuerto wants to fulfill the mission given to him by Archmage Malin: securing magical reagents and reclaiming powerful lost artifacts that once belonged to Malin's old master, Archmage Trelane, all while defending his reputation as a capable scout.",al={"what does skuerto want","skuerto goals","skuerto motives"},it="wants",add="5f13d7e3"},{q="Who is Skuerto tied to?",a="Beyond working under Archmage Malin and alongside Apprentice Kryten, Skuerto stands with the Alliance defenders holding Refuge Pointe in the Arathi Highlands.",al={"skuerto ties","skuerto connections","who does skuerto know"},it="ties",add="44066d31"}},ang={["race:Dwarf"]="As a dwarf, Skuerto shows the grit of those serving the Alliance on its wild frontiers. His scout's pride is easily bruised."},kw={"arathi highlands","archmage malin","ironforge","refuge pointe","scout","skuerto","trelane"},rel={"subzone:refuge-pointe","zone:arathi","npc:archmage-malin","zone:ironforge","topic:alliance"},src={"Skuerto"}}
E["quest:635"] = {t="quest",n="Crystal in the Mountains",z="arathi",s="In Arathi's northern mountains, a vision draws you toward a gleaming crystal. The Pendant of Myzrael pulses in your hand as a plea for help reaches you.",h="In Arathi's northern mountains, a vision draws you toward a gleaming crystal.",sec={{t="A Silent Plea",b="The Pendant of Myzrael pulses in your hand, carrying a plea from someone in need of help. Then a vision shows a gleaming crystal thrusting from the ground in the mountains north of Arathi. You feel drawn there.",sp=0},{t="At the Crystal",b="At the crystal, its pulse suggests a living force is trapped within.",sp=1}},faq={{q="What starts this journey?",a="The Pendant of Myzrael begins this journey. As you hold it, it pulses with a plea from someone in desperate need of help.",al={"how to get crystal in the mountains","where does pendant of myzrael come from","crystal in the mountains start"}},{q="Where does the vision lead?",a="The vision leads you to a gleaming crystal in Arathi's northern mountains. You feel drawn there.",al={"where is the crystal","crystal in the mountains location","find the crystal from vision"}}},kw={"arathi highlands","crystal","crystal in the mountains","pendant of myzrael","shards of myzrael","vision"},rel={"zone:arathi"},m={start="Pendant of Myzrael",["end"]="Shards of Myzrael",level="35",id=635},src={"Crystal in the Mountains"}}
E["quest:637"] = {t="quest",n="Sully Balloo's Letter",z="arathi",s="At the Thandol Span, Sully Balloo's Letter carries a dwarf's last words to his wife in Ironforge. Found beneath the bridge, it tells where he died.",h="At the Thandol Span, Sully Balloo's Letter carries a dwarf's last words to his wife in Ironforge.",sec={{t="A Voice from the Riverbed",b="Beneath the stone pilings of the Thandol Span, the land bridge between the Wetlands and the Arathi Highlands, a drowned skeleton still clutches an envelope. Its water-damaged pages begin, “My dear Sara,” and preserve the tenderness of Sully Balloo's careful writing.",sp=0},{t="The Price of the Span",b="Alliance forces and their enemies have fought fiercely for the Thandol Span. Dark Iron saboteurs and warbands contesting the borderlands have threatened the crossing. Sully Balloo was among the dwarven soldiers sent north to defend it. His family in the mountains knew nothing of his fate until a diver brought his farewell letter up from beneath the waves.",sp=0},{t="A Widow in Ironforge",b="In Ironforge, Sully's widow Sara Balloo receives the letter and learns where her husband died. Grief and lingering hope had left her unsure whether he was missing or lost forever. His handwritten words force her at last to face the bitter truth of his death.",sp=1}},faq={{q="Where is Sully Balloo's letter found?",a="Sully Balloo's Letter was found in a drowned skeleton's hand beneath the stone pillars of the Thandol Span, between the Wetlands and the Arathi Highlands.",al={"letter location","where is sully balloo","thandol span skeleton"}},{q="Who was Sully Balloo?",a="Sully Balloo was an Alliance dwarven soldier who fell defending the Thandol Span. Before taking watch over the span, he wrote a farewell letter to his wife Sara. His remains and the letter were found beneath the icy waters.",al={"who is sully","sully balloo lore","who was sully balloo"}},{q="Who is Sara Balloo?",a="Sara Balloo is Sully's widow, living in Ironforge. She has spent months waiting for news of her husband's fate on the northern frontier.",al={"where is sara balloo","who is sara","sara balloo location"}},{q="What happens after you deliver the letter?",a="After Sara learns of Sully's death, sorrow overtakes her. She asks that he be memorialized, bringing a further request in Ironforge.",al={"what next","sully quest chain","after delivering letter"},sp=1},{q="Why was the letter still intact underwater?",a="The envelope clutched in the soldier's remains protected the letter. By the time it was retrieved, the pages were waterlogged and partly dissolved. Enough of Sully's careful writing remained legible to read.",al={"why is letter readable","how did envelope survive"}},{q="What real-world inspiration is behind this quest?",a="The story honors Major Sullivan Ballou of the 2nd Rhode Island Infantry. Shortly before his death at the First Battle of Bull Run during the American Civil War, he wrote an iconic, poetic farewell letter to his wife.",al={"sully balloo trivia","sullivan ballou","civil war reference"}}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you honor Sully's final words and a brother-in-arms who died defending the great works of dwarven stonework against northern threats.",["faction:Alliance"]="As an Alliance soldier, you remember the sacrifices frontline fighters make to protect the fragile overland links between the southern and northern Alliance territories."},kw={"arathi","dwarf soldier","ironforge","sara balloo","skeleton","sully balloo","thandol span","waterlogged envelope","wetlands"},rel={"npc:sara-balloo","subzone:thandol-span","quest:631","zone:ironforge","zone:dunmorogh"},m={start="Waterlogged Envelope",["end"]="Sara Balloo",level="30",faction="Alliance",id=637},src={"Sully Balloo's Letter (quest)"}}
E["quest:639"] = {t="quest",n="Sigil of Strom",z="arathi",s="At Hammerfall, Zengu seeks the sigils that guard Trol'kalar, Lord Ignaeus Trollbane's sword. The Syndicate took the Sigil of Strom, and one of its agents in Stromgarde likely carries it.",h="At Hammerfall, Zengu seeks the sigils that guard Trol'kalar, Lord Ignaeus Trollbane's sword.",sec={{t="The Legacy of Trollbane",b="Long ago, Lord Ignaeus of Strom, called Trollbane, was the Arathorian Empire's ablest foe in its war against the trolls. He wielded Trol'kalar in battle. In the trolls' old tongue, its name means troll slayer. Now Trollbane's sons are weakened, and their stronghold lies in ruins.",sp=0},{t="The First Sigil",b="Several sigils guard Trol'kalar, and Stromgarde's survivors each took some. Zengu says they must all be recovered. The Syndicate seized the first, the Sigil of Strom. Zengu believes one of its agents in Stromgarde holds it. Bring the sigil back to Zengu at Hammerfall.",sp=0}},faq={{q="Who is Zengu?",a="At Hammerfall in Arathi, Zengu is gathering the sigils that guard Trol'kalar, Lord Ignaeus Trollbane's sword.",al={"who gives sigil of strom","zengu hammerfall"}},{q="What is Trol'kalar?",a="Trol'kalar means troll slayer in the trolls' ancient tongue. Lord Ignaeus of Strom, called Trollbane, rode into battle against the trolls with the sword.",al={"what is trolkalar","trol'kalar meaning","trollbane sword"}},{q="Why is the Sigil of Strom needed?",a="Several sigils guard Trol'kalar, and Stromgarde's survivors divided them among themselves. Zengu wants them all, beginning with the Sigil of Strom.",al={"why get the sigil","purpose of sigil of strom"}},{q="Who holds the Sigil of Strom?",a="The Syndicate took the Sigil of Strom. One of its agents in Stromgarde is most likely carrying it.",al={"who has the sigil of strom","where is the sigil of strom","syndicate sigil"}}},kw={"arathi highlands","hammerfall","ignaeus","sigil of strom","stromgarde","syndicate","trol'kalar","trollbane","zengu"},rel={"quest:638","quest:640","quest:645","subzone:hammerfall","zone:arathi","topic:syndicate","topic:troll"},m={start="Zengu",["end"]="Zengu",level="37",faction="Horde",id=639,ri={"Sigil of Strom"}},src={"Sigil of Strom (Classic)"}}
E["quest:640"] = {t="quest",n="The Broken Sigil",z="arathi",s="Zengu sends you to recover sigils from the Stromgarde militia. Galen, son of Thoras Trollbane, broke the Sigil of Thoradin into eleven pieces, and you carry them to Tor'gan in Hammerfall.",h="Zengu sends you to recover sigils from the Stromgarde militia.",sec={{t="A Sigil in Pieces",b="Three sigils guard Thoras Trollbane's tomb. You have taken the first from the Syndicate. The firmly entrenched Stromgarde militia holds the other two. Galen, Thoras' son, broke the Sigil of Thoradin into eleven pieces and scattered them among the defenders.",sp=0},{t="To Tor'gan",b="Zengu asks you to gather the pieces from Stromgarde's defenders. Then carry them to Tor'gan, the troll shaman at Hammerfall. He can bind them into a whole sigil.",sp=0},{t="At Hammerfall",b="Tor'gan says Zengu told him you needed help. He examines the pieces and judges the work manageable. All eleven are present, and the sigil's magical structure is easy to restore. Tor'gan tells you to close your eyes. Soon, he declares the Sigil of Thoradin whole again.",sp=1}},faq={{q="What is the Sigil of Thoradin?",a="The Sigil of Thoradin is one of three sigils guarding Thoras Trollbane's tomb. Galen broke it into eleven pieces and scattered them among Stromgarde's defenders.",al={"sigil of thoradin lore","broken sigil meaning","what is the broken sigil"}},{q="Who divided the sigil?",a="Galen, son of Thoras Trollbane, broke the Sigil of Thoradin into eleven pieces and scattered them among Stromgarde's defenders.",al={"who broke the sigil","why is the sigil broken","galen trollbane sigil"}},{q="Where are the sigil fragments held?",a="Stromgarde's defenders hold the pieces among the firmly entrenched militia guarding the remaining sigils.",al={"where to find fragments","who has the fragments","stromgarde defenders sigil"}},{q="Who can bind the broken sigil?",a="Tor'gan, the troll shaman at Hammerfall, can bind the pieces into a whole sigil.",al={"who fixes the sigil","torgan sigil","who binds the fragments"}},{q="What came before this?",a="It follows Sigil of Strom, where you recovered the first sigil from the Syndicate.",al={"previous quest","what quest comes before the broken sigil","sigil chain start"}}},kw={"arathi highlands","broken sigil","galen trollbane","hammerfall","sigil of thoradin","stromgarde","thoras trollbane","tor'gan","zengu"},rel={"quest:641","subzone:hammerfall","zone:arathi","quest:645","topic:shaman","topic:syndicate","topic:troll"},m={start="Zengu",["end"]="Tor'gan",level="40",faction="Horde",id=640,ri={"Sigil Fragment"}},src={"The Broken Sigil"}}
E["quest:641"] = {t="quest",n="Sigil of Thoradin",z="arathi",s="Tor'gan has restored the Sigil of Thoradin, and Zengu waits in Hammerfall for its return. The sigil can open the seal on Trollbane's tomb.",h="Tor'gan has restored the Sigil of Thoradin, and Zengu waits in Hammerfall for its return.",sec={{t="The Restored Sigil",b="Tor'gan's reconstruction has worked. The Sigil of Thoradin can open the seal on Trollbane's tomb, so he sends you back to Zengu in Hammerfall. Zengu has more for you to do.",sp=0},{t="Halfway There",b="Zengu asks whether you have the second sigil. With it, he says, you are halfway to taking Trol'kalar from Trollbane's tomb. The third sigil remains hard to find because its keepers move about Arathi. Zengu trusts you will find it.",sp=1}},faq={{q="What is the Sigil of Thoradin used for?",a="The restored sigil can open the seal on Trollbane's tomb.",al={"sigil of thoradin purpose","what does sigil of thoradin do","why do we need the sigil"}},{q="Who do you bring the Sigil of Thoradin to?",a="Bring the restored sigil to Zengu in Hammerfall. Tor'gan sends you back to him.",al={"where do i take the sigil","who turns in sigil of thoradin","sigil of thoradin turn in"}},{q="Where does this step fit in the search for Trol'kalar?",a="This step follows The Broken Sigil, when Tor'gan reconstructed the sigil from the pieces you brought him.",al={"sigil chain progress","how far along is this quest","what quest is before this"}}},kw={"arathi highlands","hammerfall","sigil of thoradin","tor'gan","trol'kalar","trollbane's tomb","zengu"},rel={"quest:640","quest:645","quest:638","subzone:hammerfall","zone:arathi"},m={start="Tor'gan",["end"]="Zengu",level="40",faction="Horde",id=641},src={"Sigil of Thoradin (Classic)"}}
E["quest:642"] = {t="quest",n="The Princess Trapped",z="arathi",s="Across the Arathi Highlands, an iridescent shard carries Myzrael’s plea from deep underground. She calls herself a princess of the earth, imprisoned by giants, and asks travelers to strengthen a crystal cluster in Drywhisker Gorge.",h="Across the Arathi Highlands, an iridescent shard carries Myzrael’s plea from deep underground.",sec={{t="A Voice from the Stone",b="Strange shards lie scattered across the Arathi Highlands, humming with distant power. Near them, Myzrael’s voice rises from deep beneath the ground. She calls herself a princess of the earth, cast down and bound underground by ancient giants. Cut off from the lands above, she uses the crystals to carry her plea to anyone willing to listen.",sp=0},{t="The Drywhisker Connection",b="Myzrael directs you east to Drywhisker Gorge, where she asks you to strengthen your contact with her. Drywhisker kobolds infest the gorge, and she calls them allies of the giants who hold her captive. They carry Motes of Myzrael and guard a cluster of iridescent shards. Take the motes from the kobolds and use their energy on the formation. That will strengthen the crystal cluster and deepen your communication with the trapped princess.",sp=0}},faq={{q="Who is Myzrael?",a="Myzrael is the voice speaking through the crystal. She calls herself a princess of the earth, imprisoned deep beneath the Arathi Highlands, and calls to passing travelers for help reaching the surface.",al={"who is the trapped princess","who is talking through the crystal","who is myzrael"}},{q="Who trapped Myzrael beneath the highlands?",a="Myzrael says giants imprisoned her beneath Arathi. They bound her deep underground, so she relies on shards scattered across the region to speak with those above.",al={"who imprisoned myzrael","who trapped the princess","why is myzrael underground"}},{q="What are the Motes of Myzrael?",a="Motes of Myzrael are crystalline or elemental fragments carried by Drywhisker kobolds. Myzrael says they hold enough latent earth power to activate the shard clusters and strengthen her link to the surface.",al={"why do the kobolds have motes","drywhisker gorge motes","what are motes of myzrael"}},{q="How are the Drywhisker kobolds connected to Myzrael's captors?",a="Myzrael says the Drywhisker kobolds in Drywhisker Gorge are allies of the giants who imprisoned her. They guard a crystal shard cluster in the gorge, between the princess and the surface.",al={"why are kobolds involved","drywhisker kobolds giants","kobolds working with giants"}},{q="How is Myzrael able to speak from underground?",a="Myzrael sends her voice through iridescent crystal shards that protrude from the soil of the Arathi Highlands. The shards carry her voice through the depths to people on the surface.",al={"how does myzrael speak","iridescent shards arathi","what are the crystal shards"}},{q="Where is Drywhisker Gorge located?",a="Drywhisker Gorge is a rugged cleft in eastern Arathi Highlands. Drywhisker kobolds live there and surround the iridescent shard cluster Myzrael asks you to empower with the gathered motes.",al={"where is drywhisker gorge","where do i take the motes","drywhisker shards location"}}},ang={["class:Shaman"]="As a shaman, you commune with elemental spirits and may recognize Myzrael’s claim to be an earth princess. Her imprisonment underground calls for careful scrutiny of the elements.",["class:Mage"]="As a mage, you may find the resonant shards and motes of earth energy a curious way to communicate and channel power across great distances.",["profession:Mining"]="As a miner, you may encounter Drywhisker kobolds near the gorge and in underground veins in Arathi. You may also find the enchanted crystal shards tied to the princess."},kw={"arathi highlands","drywhisker gorge","drywhisker kobolds","earth princess","iridescent shards","motes of myzrael","myzrael","princess of the earth","the princess trapped"},rel={"zone:arathi","subzone:drywhisker-gorge","topic:kobold"},m={id=642},src={"In-game quest text: The Princess Trapped"},fv=true}
E["quest:643"] = {t="quest",n="Sigil of Arathor",z="arathi",s="Zengu sends you from Hammerfall to seek a sigil carried by human cavalry in the Arathi Highlands. Find their leader, Lieutenant Valorcall, and bring the sigil back.",h="Zengu sends you from Hammerfall to seek a sigil carried by human cavalry in the Arathi Highlands.",sec={{t="The Prince's Cavalry",b="Zengu doubts the humans can claim Stromgarde, much less the whole Arathi Highlands. Yet their prince still sends the last of his horsemen through the countryside. Zengu cannot see why. He knows Lieutenant Valorcall leads those riders and carries one of the sigils. Find Valorcall and bring it back to Hammerfall.",sp=0},{t="On Horseback",b="Zengu warns that Valorcall is hard to catch, for his horse bears him swiftly across the land. If Valorcall is gone, Stromgarde's defenders will suffer a heavy blow. Then the Horde will stand one sigil away from claiming Trol'kalar.",sp=1}},faq={{q="Who sends you to find the Sigil of Arathor?",a="Zengu sends you from Hammerfall to find the Sigil of Arathor.",al={"sigil of arathor quest giver","who gives sigil of arathor","where to get sigil of arathor"}},{q="Who holds the Sigil of Arathor?",a="Lieutenant Valorcall leads the human cavalry and holds the Sigil of Arathor. The human prince gave it to him, and Zengu says Valorcall rides on horseback and is hard to track.",al={"who has the sigil of arathor","where is valorcall","lieutenant valorcall location"}},{q="Why does Lieutenant Valorcall have the sigil?",a="Zengu says the human prince gave one of the sigils to Lieutenant Valorcall, but he does not say why.",al={"why does valorcall have the sigil","who gave valorcall the sigil"}},{q="Where does this fit in the Trol'kalar chain?",a="The Sigil of Arathor is the fifth step in the Trol'kalar chain. It follows the Sigil of Thoradin, and the Sigil of Trollbane comes next.",al={"trolkalar quest chain arathor","what comes before sigil of arathor","what comes after sigil of arathor"}},{q="Where do you bring the sigil once it is found?",a="Bring the sigil back to Zengu in Hammerfall.",al={"where to turn in sigil of arathor","sigil of arathor turn in"}}},kw={"arathi highlands","hammerfall","lieutenant valorcall","sigil of arathor","stromgarde","trol'kalar","valorcall","zengu"},rel={"subzone:hammerfall","zone:arathi","quest:645","topic:human"},m={start="Zengu",["end"]="Zengu",level="41",faction="Horde",id=643,ri={"Sigil of Arathor"}},src={"Sigil of Arathor (Classic)"}}
E["quest:644"] = {t="quest",n="Sigil of Trollbane",z="arathi",s="In Hammerfall, Zengu sends you deep into Stromgarde for the Sigil of Trollbane. Prince Galen keeps the last sigil, which is needed to claim Trol'kalar.",h="In Hammerfall, Zengu sends you deep into Stromgarde for the Sigil of Trollbane.",sec={{t="The Last Sigil",b="Prince Galen, son of Thoras Trollbane, keeps the last sigil in Stromgarde. He waits in a chapel deep in the districts held by the militia. Zengu warns that Galen is well guarded and a fine fighter. You are to kill the prince and carry the sigil back to Zengu in Hammerfall.",sp=0},{t="Zengu's Verdict",b="Zengu asks whether the line of Ignaeus Trollbane is broken. When it is, he declares that Trollbane blood will no longer haunt his people. They now hold every sigil needed to claim Trol'kalar. Zengu vows they will soon strike at the trolls of Zul'Gurub, whom he hates.",sp=1}},faq={{q="Who sends you to retrieve the Sigil of Trollbane?",a="Zengu sends you from Hammerfall to retrieve the Sigil of Trollbane.",al={"sigil of trollbane questgiver","who gives sigil of trollbane","where do i start sigil of trollbane"}},{q="Where is Prince Galen Trollbane located?",a="Prince Galen Trollbane waits in a chapel far inside Stromgarde, in the districts held by the militia.",al={"prince galen trollbane location","where is galen trollbane","galen trollbane stromgarde"}},{q="Why is the Sigil of Trollbane needed?",a="The Sigil of Trollbane is the last sigil Zengu needs to open Thoras Trollbane's tomb. Thoras's son, Prince Galen, keeps it himself.",al={"purpose of sigil of trollbane","why get sigil of trollbane"}},{q="What comes after obtaining the Sigil of Trollbane?",a="After you obtain the Sigil of Trollbane, the chain continues with Trol'kalar.",al={"next quest after sigil of trollbane","what follows sigil of trollbane"}}},kw={"galen trollbane","hammerfall","sigil of arathor","stromgarde","trol'kalar","zengu","zul'gurub"},rel={"quest:645","subzone:hammerfall","zone:arathi","quest:638","subzone:zul-gurub","topic:troll"},m={start="Zengu",["end"]="Zengu",level="42",faction="Horde",id=644,ri={"Sigil of Trollbane"}},src={"Sigil of Trollbane (quest)"}}
E["quest:645"] = {t="quest",n="Trol'kalar",z="arathi",s="At Stromgarde, Zengu sends you after Trol'kalar, now that four sigils have joined as one.",h="At Stromgarde, Zengu sends you after Trol'kalar, now that four sigils have joined as one.",sec={{t="One Sigil from Four",b="Zengu has seen the four sigils unite as the Sigil of Ignaeus. He believes their union can break the wardings on Trollbane's tomb. The tomb lies in the Sanctum behind Stromgarde's chapel, and Zengu sends you there to retrieve Trol'kalar. A fenced path to the right of the chapel entrance descends to the crypt.",sp=0},{t="The Tomb Opens",b="Etchings on Trollbane's tomb match the glowing lines of the sigil. When they meet, a flash of light swallows the sigil. Trol'kalar, the legendary sword, is freed from the stone hands that held it.",sp=1}},faq={{q="Who sends you to retrieve Trol'kalar?",a="Zengu sends you to retrieve Trol'kalar after the four sigils unite as the Sigil of Ignaeus.",al={"who gives this quest","quest giver","zengu"}},{q="Where is Trollbane's tomb located?",a="Trollbane's remains lie in the Sanctum behind Stromgarde's chapel. A fenced path to the right of the chapel entrance descends to the crypt.",al={"where is the tomb","tomb location","crypt location"}},{q="What happens to the four sigils?",a="The four sigils unite as the Sigil of Ignaeus. Zengu believes it can break the wardings on Trollbane's tomb.",al={"what happened to sigils","sigil of ignaeus"}},{q="What is the previous step in this chain?",a="Sigil of Trollbane, the last of the four sigils, comes before this.",al={"previous quest","prior quest","sigil of trollbane"}}},kw={"crypt","sanctum","sigil of ignaeus","stromgarde","trol'kalar","trollbane","zengu"},rel={"subzone:crypt-stromgarde-keep","subzone:sanctum-stromgarde-keep","subzone:hammerfall","zone:arathi","quest:638"},m={start="Zengu",["end"]="Trollbane's Tomb",level="42",faction="Horde",id=645},src={"Trol'kalar (Classic)"}}
E["quest:646"] = {t="quest",n="Trol'kalar",z="arathi",s="At Trollbane's Tomb, Trol'kalar slips free of its stone sheath as the light fades. You carry the sword to Zengu in Hammerfall.",h="At Trollbane's Tomb, Trol'kalar slips free of its stone sheath as the light fades.",sec={{t="A Sword Set Free",b="At Trollbane's Tomb, you find Trol'kalar free of its stone sheath. You carry the sheathed sword to Zengu in Hammerfall, in the Arathi Highlands.",sp=0},{t="What Zengu Says",b="Zengu says Strom and Arathor's forces preyed on the trolls for generations. Now his people hold their greatest weapon, and the slow advance into Zul'Gurub's humid forests will no longer be a struggle. The Darkspear trolls are in your debt, he says. He will deliver the sword to Nimboya at Grom'gol.",sp=1}},faq={{q="Where does Trol'kalar need to go?",a="Carry the sword, still in its stone sheath, to Zengu in Hammerfall, in the Arathi Highlands.",al={"where do i take trolkalar","trol'kalar delivery","trolkalar hand in"}},{q="Where do I find the sword?",a="Find the sword at Trollbane's Tomb, where the fading light has freed it from its stone sheath.",al={"where is trol'kalar","trolkalar location"}},{q="What came before this step?",a="This follows the earlier Trol'kalar step and is the last step in the long chain.",al={"trol'kalar previous","trolkalar chain"}}},kw={"arathi","hammerfall","nimboya","trol'kalar","trollbane","zengu","zul'gurub"},rel={"quest:645","subzone:hammerfall","subzone:zul-gurub","topic:troll","zone:arathi"},m={start="Trollbane's Tomb",["end"]="Zengu",level="42",faction="Horde",id=646},src={"Trol'kalar (2)"}}
E["quest:647"] = {t="quest",n="MacKreel's Moonshine",z="arathi",s="Foggy MacKreel needs his moonshine carried from the broken Thandol Span to Southshore. He drank too much while on watch and now has little time to deliver a fresh batch to Brewmeister Bilger and settle his debt.",h="Foggy MacKreel needs his moonshine carried from the broken Thandol Span to Southshore.",sec={{t="A Guard's Hangover",b="On the shattered Thandol Span, Foggy MacKreel keeps watch through wet, cold, and dull hours. He drinks his homemade moonshine to bear the damp chill. The brew hits hard enough that he compares its aftereffects to siege engines pounding across his skull. One drink too many leaves him asleep through his shift. Longbraid the Grim commands the dwarves defending the Span, and Foggy cannot afford another lapse in discipline.",sp=0},{t="A Race Against the Clock",b="Foggy owes Brewmeister Bilger in Southshore a longstanding debt. He promised a batch of his personal brew to settle the account, but his hangover and watch duties have left him minutes from missing the deadline. You race across the Arathi Highlands with the jug, by gryphon and swift feet. Reach Southshore before Bilger decides Foggy has skipped out on his tab again.",sp=0}},faq={{q="Who is Foggy MacKreel?",a="Foggy MacKreel is a dwarf on the broken part of the Thandol Span, reached from the Arathi Highlands side. He brews extremely stout moonshine and often drinks too freely while on duty.",al={"foggy mackreel","who is foggy","quest giver mackreel"},it="identity"},{q="Why is this delivery so urgent?",a="Foggy passed out drunk during his watch and fell badly behind schedule. He has barely a quarter of an hour to carry the moonshine from the Thandol Span to Southshore and settle his overdue tab with Brewmeister Bilger.",al={"why is there a timer","why 15 minutes","mackreel moonshine timer"},it="motive"},{q="Who is Brewmeister Bilger?",a="Brewmeister Bilger is a master dwarven brewer in the coastal settlement of Southshore, in the Hillsbrad Foothills. He appreciates stout alcohol and has an outstanding business agreement with Foggy MacKreel.",al={"brewmeister bilger","who is bilger","bilger southshore"},it="target"},{q="How does one get the moonshine to Southshore in time?",a="There is no boat from the Span to Southshore. If you know the Refuge Pointe flight path, take a gryphon from Refuge Pointe to Southshore, then find Brewmeister Bilger in town before time runs out.",al={"how to deliver moonshine","fastest way southshore mackreel","moonshine delivery route"},gp=true},{q="Who is Longbraid?",a="Longbraid the Grim is the dwarf commander outside Dun Modr in the Wetlands. He leads the defenders of the Thandol Span, and Foggy dreads Longbraid discovering that he drank himself unconscious while on watch.",al={"captain longbraid","longbraid menethil"},it="people"},{q="Why can't Foggy MacKreel deliver the moonshine himself?",a="Foggy MacKreel indulged far too heavily in his own moonshine the night before and ended up passing out cold during his watch. With a throbbing headache, his official guard post to answer for under Longbraid the Grim, and a rapidly expiring deadline to clear his debts with Brewmeister Bilger, he is in no shape or position to run off to Southshore on his own.",al={"why me mackreel","why deliver moonshine","foggy moonshine why me"},it="why_me",add="d39890fd"}},ang={["race:Dwarf"]="As a dwarf, you know the misery of a terrible hangover made worse by an unpaid brewing debt to a fellow kinsman.",["faction:Alliance"]="As an Alliance traveler, you cross the overland route linking the Thandol Span with Alliance-held Southshore in Hillsbrad."},kw={"bilger","foggy","longbraid","mackreel","menethil","moonshine","southshore"},rel={"npc:foggy-mackreel","npc:brewmeister-bilger","zone:wetlands","subzone:southshore"},m={start="Foggy MacKreel",["end"]="Brewmeister Bilger",level="30",faction="Alliance",id=647},src={"MacKreel's Moonshine (quest)"}}
E["quest:651"] = {t="quest",n="Stones of Binding",z="arathi",s="In Arathi, four Stones of Binding hold Myzrael beneath the ground. A voice from the iridescent shards says the strongest stone needs keys from the other three.",h="In Arathi, four Stones of Binding hold Myzrael beneath the ground.",sec={{t="Four Stones",b="Across Arathi, four stones keep Myzrael beneath the ground, a voice says. The Stone of Inner Binding is strongest, and keys from the Stones of West, East and Outer Binding can unlock it. Gather the Burning Key, the Cresting Key and the Thundering Key. Guardians watch the stones, though someone clever or lucky may find a way to banish them. Carry the keys to the Stone of Inner Binding.",sp=0},{t="At the Inner Stone",b="Myzrael’s voice comes from the stone. The Stones of Binding are open, the shackles are loosening, and freedom draws closer. Myzrael hails you as a noble rescuer.",sp=1}},faq={{q="Where does this step come from?",a="This step follows The Princess Trapped. Its voice comes from the iridescent shards.",al={"stones of binding quest giver","who gives stones of binding","where to start stones of binding"}},{q="What are the four Stones of Binding?",a="The four are the Stone of West Binding, the Stone of East Binding, the Stone of Outer Binding and the strongest, the Stone of Inner Binding.",al={"which stones of binding","arathi binding stones","four stones"}},{q="Which keys are needed to unlock the inner stone?",a="The Burning Key, the Cresting Key and the Thundering Key are gathered from the Stones of West, East and Outer Binding.",al={"binding keys","what keys are needed","keys for stone of inner binding"}},{q="Who guards the binding stones?",a="Guardians watch over the stones, though a clever or lucky adventurer may find a way to banish them.",al={"stone guardians","who guards the stones","binding stone protectors"}},{q="Where must the keys be delivered?",a="Carry the keys to the mightiest stone, the Stone of Inner Binding. It must be unlocked before the others will open.",al={"where do i take the keys","turn in stones of binding","stone of inner binding location"}}},kw={"arathi highlands","burning key","cresting key","iridescent shards","myzrael","stone of inner binding","stones of binding","thundering key"},rel={"quest:642","quest:652","zone:arathi"},m={start="Iridescent Shards",["end"]="Stone of Inner Binding",level="38",id=651},src={"Classic quest text: Stones of Binding"}}
E["quest:652"] = {t="quest",n="Breaking the Keystone",z="arathi",s="The voice has more freedom now, though the Keystone still binds it. The Keystone lies among a ring of stones, and Fozruk holds the key the watchers call the Rod of Order.",h="The voice has more freedom now, though the Keystone still binds it.",sec={{t="The Last Lock",b="Opening the Stones of Binding eased the voice's confinement, but one lock still holds the Keystone. It lies among the circle of stones around you. Fozruk, a stone watcher and one of its captors, holds the key the watchers call the Rod of Order. Carry the rod to the Keystone and open the lock. The voice promises gratitude that will shake the earth to its roots. Geomantic energy fills the Keystone.",sp=0},{t="At the Keystone",b="When you set the rod into the Keystone, a tremor runs beneath you.",sp=1}},faq={{q="What comes before this step?",a="The Stones of Binding came first. Opening them eased much of the voice's confinement.",al={"prerequisite","previous quest","stones of binding prerequisite"}},{q="Who is Fozruk?",a="Fozruk is a stone watcher and one of the voice's captors. He holds the key to the Keystone.",al={"who is fozruk","fozruk lore","stone watcher fozruk"}},{q="What is the Rod of Order?",a="The stone watchers call the key to the Keystone the Rod of Order. Fozruk holds it.",al={"rod of order","what is rod of order","keystone key"}},{q="Where is the Keystone?",a="The Keystone lies among a circle of stones in the Arathi Highlands.",al={"where is breaking the keystone","keystone location","stone circle arathi"}}},kw={"arathi highlands","fozruk","keystone","rod of order","stone of inner binding","stone watcher"},rel={"quest:651","zone:arathi"},m={start="Stone of Inner Binding",["end"]="Keystone",level="42",id=652},src={"Classic quest text: Breaking the Keystone"}}
E["quest:653"] = {t="quest",n="Myzrael's Allies",z="arathi",s="Myzrael is free, yet she must gather strength before she can face her captors. She calls you a noble ally and sends you to Gerrig Bonegrip in a shop in Ironforge's Forlorn Cavern, where he knows how to summon her.",h="Myzrael is free, yet she must gather strength before she can face her captors.",sec={{t="Free to Gather Strength",b="Myzrael is free, but not strong enough to face her captors. They would overpower her now and lock her away again. So she will gather strength in hiding. When she is ready, she means to face the giants and make them rue the day they held her. She calls you a noble ally and says she will need your help to summon her to the surface.",sp=0},{t="Word for Gerrig Bonegrip",b="Myzrael sends you to Gerrig Bonegrip, whose shop is in Ironforge's Forlorn Cavern. He knows how to summon her.",sp=0}},faq={{q="Where can Gerrig Bonegrip be found?",a="Gerrig Bonegrip keeps a shop in Ironforge's Forlorn Cavern.",al={"gerrig bonegrip location","where is gerrig bonegrip","find gerrig bonegrip"}},{q="Why is Myzrael remaining in hiding?",a="Myzrael must gather strength first. If her captors faced her now, they would overpower her and imprison her again.",al={"why is myzrael hiding","where is myzrael going"}},{q="Who are the captors Myzrael speaks of?",a="Myzrael means the giants who had wardship of her. She says she will confront them in time and make them rue having held her.",al={"myzrael captors","who imprisoned myzrael","myzrael giants"}},{q="Why does Myzrael send you to Ironforge?",a="Myzrael sends you to Gerrig Bonegrip because he knows how she can be summoned. She will need your help to summon her to the surface when she is ready.",al={"why go to ironforge","purpose of visiting gerrig"}}},kw={"arathi highlands","forlorn cavern","gerrig bonegrip","giants","ironforge","keystone","myzrael"},rel={"npc:gerrig-bonegrip","subzone:forlorn-cavern","zone:ironforge","zone:arathi"},m={start="Keystone",["end"]="Gerrig Bonegrip",level="40",faction="Alliance",id=653},src={"Myzrael's Allies (Alliance)"}}
E["quest:655"] = {t="quest",n="Hammerfall",z="arathi",s="At Hammerfall, the Horde holds a camp won at the cost of Warchief Orgrim Doomhammer's life. Gor'mul remembers the captives' escape and why the stronghold bears its name.",h="At Hammerfall, the Horde holds a camp won at the cost of Warchief Orgrim Doomhammer's life.",sec={{t="Blood and Broken Chains",b="In the Arathi Highlands, the Alliance once held orcs captive behind wood and steel. Young Thrall and Warchief Orgrim Doomhammer led an assault on the camp's enclosures and freed their kin. Many captives escaped as the defenses fell. Then a mounted lance struck Doomhammer from behind. He died where Hammerfall now stands.",sp=0},{t="The Lingering Shadow of Defeat",b="Gor'mul was among those who did not find freedom that day. In the battle's chaos and the earth's tremors, he watched the Warchief fall and lost the will to fight. His brethren fled, leaving him behind. For years, Gor'mul wandered the highlands in grief. The Horde has reclaimed the site as a fortified base, yet survivors still carry the memory of Doomhammer's death.",sp=0}},faq={{q="Who is Gor'mul?",a="Gor'mul was an orc captive at the internment camp where Hammerfall now stands. Thrall and Doomhammer led an assault to free the captives, but Gor'mul was left behind during the escape. He wandered alone in despair for years.",al={"who is gormul","gor mul backstory","what happened to gormul"}},{q="How did Orgrim Doomhammer die?",a="Orgrim Doomhammer died in the battle to free the Arathi internment camp. An Alliance knight on horseback struck him from behind with a lance.",al={"how did doomhammer die","who killed doomhammer","doomhammer death story"}},{q="Why is the outpost named Hammerfall?",a="Hammerfall bears the name of Warchief Orgrim Doomhammer, who fell there while freeing his people from human captivity. The Horde returned to the ruined camp and made it a permanent base.",al={"why is it called hammerfall","origin of hammerfall name","hammerfall history"}},{q="Who is Tor'gan?",a="Tor'gan is a Horde representative stationed at Hammerfall. He helps care for the encampment and understands the lingering trauma of former captives like Gor'mul.",al={"who is tor'gan","torgan hammerfall","torgan quest"}},{q="Did Thrall take part in the battle here?",a="Yes. Thrall fought beside Warchief Orgrim Doomhammer in the assault on the Arathi internment camp. They broke its defenses and freed captive orcs, but Doomhammer died in the battle.",al={"thrall and doomhammer arathi","liberation of hammerfall","did thrall fight at hammerfall"}},{q="Why is Gor'mul so despondent?",a="Gor'mul watched Doomhammer fall, and the sight crushed his spirit. When the other captives escaped into the wilderness, Gor'mul was left behind to wander without hope until the Horde returned to build Hammerfall.",al={"why is gormul so sad","gormul depression","why did gormul lose hope"}}},ang={["faction:Horde"]="For the Horde, Hammerfall recalls the liberation of the orcish internment camps and Warchief Orgrim Doomhammer's sacrifice.",["race:Orc"]="For orcs, Doomhammer's fall in Arathi remains one of history's most painful moments. It marked the end of an era and the rise of Thrall's new Horde.",["class:Warrior"]="As a warrior, you can remember Orgrim Doomhammer as a legendary fighter. The ground where he fell carries the weight of that battle."},kw={"arathi highlands","doomhammer","gor'mul","hammerfall","internment camp","orgrim doomhammer","thrall","tor'gan"},rel={"subzone:hammerfall","npc:thrall"},m={faction="Horde",id=655},src={"In-game quest text: Hammerfall"},fv=true}
E["quest:657"] = {t="quest",n="Hints of a New Plague?",z="arathi",s="Kinelory is bound for Go'Shek Farm, where Apothecary Jorell's deadly experiments continue. Quae has learned of them from a folder, but she is too hurt from a clash with orcs to go along.",h="Kinelory is bound for Go'Shek Farm, where Apothecary Jorell's deadly experiments continue.",sec={{t="Jorell's Experiments",b="The folder shows that Jorell is conducting deadly experiments at Go'Shek Farm. Quae does not know what they mean for Hillsbrad. But Phin would not want them to continue. Some of Jorell's research has already reached Tarren Mill.",sp=0},{t="Kinelory's Protector",b="Quae fought some orcs while you were away, and now she cannot help Kinelory. Kinelory plans to go to the farm and take the research Jorell has not yet sent to Tarren Mill. She needs your protection on the way.",sp=0},{t="Kinelory's Resolve",b="Kinelory says she will destroy every one of the Forsaken herself if that brings Phin peace. Since the plague, Phin has done so much for Kinelory and the others. They had never thought they would find friends or family again. Kinelory asks you to tell her when you are ready, and then you will set out together at once.",sp=1}},faq={{q="Why can't Quae accompany Kinelory?",a="Quae fought some orcs while you were away and is in no shape to help Kinelory.",al={"why is quae staying","why won't quae help","why escort kinelory alone"}},{q="What was discovered in the folder?",a="The folder reveals Apothecary Jorell's deadly experiments at Go'Shek Farm.",al={"what was in the folder","jorell experiments","what is jorell doing"}},{q="Why are Quae and Kinelory investigating this?",a="Quae and Kinelory are Phin's companions. Phin leads a band of adventurers investigating odd happenings, and he would not want Jorell's experiments to continue.",al={"who is phin","why do they care about the plague","why help phin"}},{q="Where is the research being sent?",a="Some of Jorell's research has already gone to Tarren Mill. Kinelory plans to take what he has not yet sent.",al={"where are the notes going","tarren mill research"}}},kw={"apothecary jorell","forsaken","go'shek farm","kinelory","phin","plague","quae","tarren mill"},rel={"subzone:tarren-mill","topic:forsaken","zone:hillsbrad"},m={start="Quae",["end"]="Kinelory",level="36",faction="Alliance",id=657},src={"Hints of a New Plague? (3)"}}
E["quest:658"] = {t="quest",n="Hints of a New Plague?",z="arathi",s="At Go'Shek Farm, Quae and Kin have watched for days, and Kin saw a courier leave a small house to the south. They suspect she carries notes to Tarren Mill, so Quae asks you to track her and bring back the documents.",h="At Go'Shek Farm, Quae and Kin have watched for days, and Kin saw a courier leave a small house to the south.",sec={{t="Watching the Farm",b="Quae expected Phin Odelic to send you. He worries too much, in Quae's view. Quae and Kin have watched the farm for days, and Kin recently saw a courier leave a small house to the south. Kin talks often, but Quae trusts Kin's senses in dangerous places.",sp=0},{t="The Courier's Folder",b="Quae asks if you are a skilled tracker. The courier may carry notes bound for Tarren Mill, and the documents could shed light on what is happening in Hillsbrad. Find the Forsaken Courier and bring her Sealed Folder to Quae near Go'Shek Farm.\n\nWhile you search, Kin spots an apothecary leaving that same house. Quae suspects the apothecary is up to no good, but needs proof before anyone acts rashly.",sp=0}},faq={{q="Who sent you to find Quae and Kin?",a="Phin Odelic sent you to check on Quae and Kin. Quae expected it, since Phin worries too much.",al={"who sent me to quae","who started hints of a new plague","phin odelic quest"}},{q="Where did the courier come from?",a="Kin saw the courier leave a small house to the south.",al={"where is the courier from","courier location","house south of farm"}},{q="Where is the courier heading?",a="Quae and Kin suspect the courier carries notes bound for Tarren Mill.",al={"courier destination","where is courier going"}},{q="What item are you sent to retrieve?",a="Bring the Forsaken Courier's Sealed Folder to Quae near Go'Shek Farm.",al={"what item does the courier have","sealed folder"}},{q="Who else was spotted at the house?",a="While you were away, Kin spotted an apothecary leaving the same house to the south.",al={"apothecary at the farm","who came out of the house"}},{q="Why does Quae want the documents?",a="The documents might shed light on what is happening in Hillsbrad. Quae needs proof before anyone acts rashly.",al={"why get the documents","what are the notes for"}}},kw={"apothecary","arathi highlands","forsaken courier","go'shek farm","kin","phin odelic","quae","sealed folder","tarren mill"},rel={"quest:657","subzone:go-shek-farm","subzone:tarren-mill","zone:hillsbrad","topic:forsaken"},m={start="Quae",["end"]="Quae",level="36",faction="Alliance",id=658},src={"Hints of a New Plague? (2)"}}
E["quest:660"] = {t="quest",n="Hints of a New Plague?",z="arathi",s="Kinelory is ready to go down to the farm, and asks you to come with her. She fears the undead may harm Hillsbrad while they wait. You are needed to see her safely back.",h="Kinelory is ready to go down to the farm, and asks you to come with her.",sec={{t="Watching Kinelory's Back",b="Kinelory is ready to act after the earlier steps of the investigation. She asks you to go with her down to the farm, then return safely to Quae. The people of Hillsbrad need her protected.",sp=0},{t="A Safe Return",b="Quae thanks you when Kinelory returns. Quae admits she hoped Kinelory would not be too much of a handful. Kinelory is friendly, yet deadly to her enemies.",sp=1}},faq={{q="Who sends you on this escort?",a="Kinelory asks you to go with her when she is ready to set out.",al={"quest giver","who gives quest","who starts hints of a new plague 4"}},{q="Where does Kinelory need to go?",a="Kinelory goes down to a farm, then returns to Quae.",al={"escort route","where does kinelory go","kinelory destination"}},{q="Who do you report to when finished?",a="You report to Quae once Kinelory has returned to her.",al={"turn in","who completes quest","where to turn in"}},{q="What came right before this part of the investigation?",a="The third part of Hints of a New Plague? leads into this part of the investigation.",al={"previous quest","prereq","what comes before"}},{q="What follows after returning safely?",a="The investigation continues with its fifth part.",al={"next quest","what comes next","follow up"}},{q="Why must Kinelory be protected?",a="Kinelory needs protection so she can return safely while the undead may harm the people of Hillsbrad.",al={"why protect kinelory","why care about kinelory"}}},kw={"escort","hillsbrad foothills","hints of a new plague","kinelory","plague","quae"},rel={"zone:hillsbrad"},m={start="Kinelory",["end"]="Quae",level="37",faction="Alliance",id=660},src={"Hints of a New Plague? (4)"}}
E["quest:661"] = {t="quest",n="Hints of a New Plague?",z="arathi",s="In Arathi, Quae and Kinelory remain near the farm while you carry news to Southshore. Quae has the farm items, and Kinelory has returned safely.",h="In Arathi, Quae and Kinelory remain near the farm while you carry news to Southshore.",sec={{t="Word for Southshore",b="Quae is pleased with how you cared for Kinelory. She says Kinelory is in better shape than after a night at the tavern. The items from the farm should help Phin Odelic understand what is happening in Arathi.\n\nSince the farm was attacked, Quae and Kinelory plan to stay there a little longer in case anyone retaliates. They ask you to return to Southshore and speak with Phin.",sp=0},{t="Phin's Answer",b="Phin is glad to hear that Quae and Kinelory are alive and well. He calls them irreplaceable friends and travelling companions. On behalf of the whole group, he thanks you with a gift.\n\nPhin hopes that, with luck, they will learn what the Forsaken are planning and bring it to an end.",sp=1}},faq={{q="Who sends you to speak with Phin Odelic?",a="Quae asks you to go to Southshore once Kinelory is safely back from the farm.",al={"who gives hints of a new plague 5","who starts hints of a new plague","quae quest"}},{q="Why aren't Quae and Kinelory returning to Southshore themselves?",a="Quae and Kinelory plan to stay in Arathi a little longer in case anyone retaliates for the attack on the farm.",al={"why is quae staying in arathi","why stay behind","quae staying"}},{q="Where can Phin Odelic be found?",a="Phin Odelic is in Southshore.",al={"phin odelic location","where is phin","phin odelic southshore"}},{q="What is the purpose of bringing news to Phin Odelic?",a="The items Kinelory brought from the farm should help Phin Odelic understand what is happening in Arathi.",al={"why visit phin","phin odelic purpose","what does phin want"}}},kw={"arathi highlands","forsaken","hillsbrad","kinelory","phin odelic","plague","quae","southshore"},rel={"subzone:southshore","topic:forsaken","zone:hillsbrad"},m={start="Quae",["end"]="Phin Odelic",level="37",faction="Alliance",id=661},src={"Hints of a New Plague? (5)"}}
E["quest:662"] = {t="quest",n="Deep Sea Salvage",z="arathi",s="After Land Ho!, First Mate Nilzlix asks you to recover the charts and logs from two wrecks before anyone leaves the cove.",h="After Land Ho!, First Mate Nilzlix asks you to recover the charts and logs from two wrecks before anyone...",sec={{t="Two Ships Lost in the Reef",b="O'Breen brought three ships into the cove, certain treasure lay there. The Harbinger docked safely. But the Maiden's Folly and the Spirit of Silverpine reached the reef as the tides began to fall. Both struck a temple-like structure and sank fast.",sp=0},{t="What Nilzlix Wants Back",b="First Mate Nilzlix wants you to recover the logs and charts from both wrecks. He fears the information could reach prying eyes. If enemies found it, Fleet Master Seahorn would force the crew down the plank.",sp=0}},faq={{q="Why did the Maiden's Folly and Spirit of Silverpine sink?",a="The Maiden's Folly and the Spirit of Silverpine entered the cove as the tides began to fall. Both struck a temple-like structure in the reef and sank quickly.",al={"why did the ships wreck","how did the ships sink","arathi cove shipwreck cause"}},{q="Who is First Mate Nilzlix?",a="First Mate Nilzlix speaks of the three ships O'Breen led into the cove. He wants you to recover the logs and charts from the two sunken ships.",al={"nilzlix","who gives deep sea salvage"}},{q="Why are the charts and logs so important?",a="Nilzlix fears prying eyes will find the information left behind. If enemies got hold of it, he says Fleet Master Seahorn would force the crew down the plank.",al={"why recover logs","why charts and logs"}},{q="What ship made it to safety?",a="Only the Harbinger docked safely in the cove. The other two ships sank.",al={"which ship survived","harbinger ship"}},{q="Who is Fleet Master Seahorn?",a="Nilzlix names Fleet Master Seahorn as the one who would force the crew down the plank if enemy hands got the records.",al={"fleet master seahorn role","who is seahorn"}},{q="What came before this task?",a="Land Ho! came before this.",al={"deep sea salvage prerequisite","previous quest"}}},kw={"arathi highlands","booty bay","deep sea salvage","harbinger","maiden's folly","nilzlix","o'breen","seahorn","spirit of silverpine"},rel={"quest:663","npc:fleet-master-seahorn","subzone:booty-bay","zone:arathi"},m={start="First Mate Nilzlix",["end"]="First Mate Nilzlix",level="40",id=662,ri={"Maiden's Folly Charts","Maiden's Folly Log","Spirit of Silverpine Charts","Spirit of Silverpine Log"}},src={"Deep Sea Salvage"}}
E["quest:6622"] = {t="quest",n="Triage",z="arathi",s="You are asked to save wounded soldiers with Triage Bandages. Their injuries leave little room for delay.",h="You are asked to save wounded soldiers with Triage Bandages.",sec={{t="The Wounded",b="Critically Injured Soldiers succumb first, while Badly Injured Soldiers follow. Injured Soldiers endure the longest, so the order of care matters as you try to save fifteen patients before six die from their wounds.",sp=0}},faq={{q="What am I being asked to do?",a="You are asked to use Triage Bandages to save fifteen patients before six die from their injuries.",al={"triage quest","what is triage","save the soldiers"}},{q="Which soldiers are in the worst shape?",a="Critically Injured Soldiers die the fastest, followed by Badly Injured Soldiers.",al={"who dies fastest","critical soldiers","worst injured"}},{q="Who can wait longest?",a="Injured Soldiers take the longest to die and should be tended after the more critically wounded.",al={"injured soldier order","who is last","least injured"}},{q="What are Triage Bandages for?",a="Triage Bandages are used to tend to the soldiers' wounds.",al={"bandages use","triage bandages","how to save patients"}}},kw={"badly injured","critically injured","injured soldiers","patients","soldiers","triage","triage bandages","wounds"},m={faction="Horde",id=6622},src={"In-game quest text: Triage"},fv=true}
E["quest:663"] = {t="quest",n="Land Ho!",z="arathi",s="At Faldir's Cove, Lolo warns you that Captain O'Breen's brief stop may last far longer than planned. The Spirit of Silverpine and the Maiden's Folly are lost, and Lolo directs you to the captain.",h="At Faldir's Cove, Lolo warns you that Captain O'Breen's brief stop may last far longer than planned.",sec={{t="Lolo's Welcome",b="Lolo greets you at Faldir's Cove and tells you what has gone wrong. Captain O'Breen promised the crew only a few hours ashore to gather treasure before sailing back to Booty Bay. Lolo doubts they will be away so briefly.\n\nThe Spirit of Silverpine and the Maiden's Folly, two ships in the formation, now lie on the sea floor. If you mean to stay, Lolo says to speak with the captain.",sp=0},{t="The Captain's Account",b="Captain O'Breen fears Seahorn will take the ship if word of the disaster spreads. A contraption belonging to the Professor pointed toward lost treasure near Faldir's Cove. So the Harbinger docked there and signaled the other two ships to follow.\n\nThen the sea rumbled and the water drew back. Both ships struck the reef. O'Breen says it is no ordinary reef, and something lies below. He promises handsome payment to anyone who helps the crew.",sp=1}},faq={{q="What happened to the other ships?",a="The Spirit of Silverpine and the Maiden's Folly were lost and now lie on the sea floor.",al={"where are the other ships","sunken ships faldir","what sank the ships"}},{q="Why did the crew come to Faldir's Cove?",a="Captain O'Breen brought the crew to Faldir's Cove to gather treasure. They expected to stay only a few hours before sailing back to Booty Bay.",al={"why are they here","purpose of expedition","what brought them to arathi"}},{q="Who should you talk to at Faldir's Cove?",a="Lolo the lookout suggests you speak with Captain O'Breen at Faldir's Cove if you plan to stay.",al={"who is captain o'breen","where is shakes o'breen"}}},kw={"booty bay","faldir's cove","harbinger","lolo the lookout","maiden's folly","seahorn","shakes o'breen","spirit of silverpine"},rel={"subzone:faldir-s-cove","quest:662","quest:665","quest:664","subzone:booty-bay","zone:arathi"},m={start="Lolo the Lookout",["end"]="Shakes O'Breen",level="35",id=663},src={"Land Ho!"}}
E["quest:664"] = {t="quest",n="Drowned Sorrows",z="arathi",s="At Faldir's Cove, Captain Steelgut mourns the Maiden's Folly and asks you to kill the Daggerspine naga who slew the wreck's survivors.",h="At Faldir's Cove, Captain Steelgut mourns the Maiden's Folly and asks you to kill the Daggerspine naga who...",sec={{t="A Captain by the Fire",b="At Faldir's Cove, Captain Steelgut sits by the fire and wishes the sea had taken him too. His crew fought hard to save the Maiden's Folly, but water rushed in all at once and the ship sank. O'Breen reached shore safely, while the naga killed the other survivors. Steelgut wants ten Daggerspine raiders and three Daggerspine sorceresses dead.",sp=0}},faq={{q="Who is Captain Steelgut?",a="Captain Steelgut commanded the Maiden's Folly. After the ship was lost, he sat by a fire at Faldir's Cove.",al={"captain steelgut","steelgut","who is the quest giver"}},{q="What happened to the Maiden's Folly?",a="Steelgut says the sea sank the Maiden's Folly. The ship was afloat, then water rushed in all at once despite the crew's hard fight to save it.",al={"maidens folly","what happened to the ship","why did steelgut crash"}},{q="Why does Captain Steelgut want the naga killed?",a="The naga killed the wreck's survivors, and Steelgut wants them dead.",al={"why kill naga","steelgut revenge","daggerspine reason"}},{q="Which naga does Steelgut want dead?",a="Ten Daggerspine raiders and three Daggerspine sorceresses, as Steelgut asks.",al={"which naga to kill","target naga","daggerspine targets"}}},kw={"arathi","daggerspine","faldir's cove","maiden's folly","naga","o'breen","raider","sorceress","steelgut"},rel={"subzone:faldir-s-cove","topic:naga","zone:arathi"},m={start="Captain Steelgut",["end"]="Captain Steelgut",level="40",id=664},src={"Drowned Sorrows (Classic)"}}
E["quest:665"] = {t="quest",n="Sunken Treasure",z="arathi",s="Professor Phizzlethorpe and Doctor Draxlegauge now aid the Blackwater Raiders in their search for lost elven treasure. Before the search can begin, the professor needs your protection while he charges goggles for the dark sea.",h="Professor Phizzlethorpe and Doctor Draxlegauge now aid the Blackwater Raiders in their search for lost elven...",sec={{t="Charging the Goggles",b="Professor Phizzlethorpe asks you to guard him as he prepares for a search beneath the dark sea. Doctor Draxlegauge built goggles to find the lost gems, but they need power from an enchanted stone in a cave a short way uphill. The cave is cursed, and those who draw near are ambushed. Defend the professor while he draws the stone’s energy into the goggles.",sp=0}},faq={{q="Who is asking for help?",a="Professor Phizzlethorpe asks you to guard him on the way to and from the cave while he charges Doctor Draxlegauge’s goggles at the enchanted stone.",al={"who gives this quest","phizzlethorpe","quest giver"}},{q="Why do the goggles need to be charged?",a="Doctor Draxlegauge built the goggles to find the lost gems in the dark sea. They need the stone’s power before they can work.",al={"why charge goggles","goggles purpose","what are the goggles for"}},{q="Why does the professor need an escort?",a="The cave is cursed, and those who draw near are ambushed. You need to defend Professor Phizzlethorpe while he channels the stone’s energy.",al={"why protect phizzlethorpe","what is in the cave"}},{q="Who are the professor and the doctor working for?",a="Professor Phizzlethorpe says he and Doctor Draxlegauge are now full-fledged Blackwater Raiders. Their duty is to help Mr. O’Breen find the lost elven treasure.",al={"who are they helping","mr obreen","blackwater raiders"}}},kw={"arathi highlands","blackwater raiders","draxlegauge","enchanted stone","goggles","o'breen","phizzlethorpe","sunken treasure"},rel={"zone:arathi","topic:gnome"},m={start="Professor Phizzlethorpe",["end"]="Doctor Draxlegauge",level="40",id=665},src={"Sunken Treasure (1)"}}
E["quest:666"] = {t="quest",n="Sunken Treasure",z="arathi",s="In Faldir's Cove, Doctor Draxlegauge lends you his goggles to find ten elven gems for Captain O'Breen. He expects them back when you finish.",h="In Faldir's Cove, Doctor Draxlegauge lends you his goggles to find ten elven gems for Captain O'Breen.",sec={{t="Gems Turned to Stone",b="The elven gems have lain on the sea floor so long that thick stone has hardened around them. The Goggles of Gem Hunting hold the power to find them through those stony shells. Proud of the gnomish ingenuity behind the goggles, Doctor Draxlegauge lends them to you. The gems are for Captain O'Breen.",sp=0},{t="Dry Land for the Doctor",b="Doctor Draxlegauge says scientific work keeps him on safe, dry land, though he could swim down himself. He expects you to return the goggles afterward. Captain O'Breen, he says, will have plenty of use for them.",sp=0}},faq={{q="Who sends you to gather the gems?",a="Doctor Draxlegauge, waiting in Faldir's Cove, sends you to gather ten elven gems for Captain O'Breen.",al={"who gives sunken treasure 2","quest giver sunken treasure"}},{q="Why are special goggles required for the search?",a="Years on the sea floor have hardened the gems into thick stone. The power in the Goggles of Gem Hunting lets you find them easily.",al={"why goggles of gem hunting","what do the goggles do"}},{q="Why doesn't Doctor Draxlegauge dive for the gems himself?",a="Doctor Draxlegauge says important scientific work keeps him on safe, dry land.",al={"why doesn't draxlegauge swim","why draxlegauge stays on land"}},{q="Can you keep the Goggles of Gem Hunting?",a="No. Doctor Draxlegauge lends you the goggles and expects them back when you finish. Captain O'Breen will use them often.",al={"keep gem hunting goggles","do i return goggles"}},{q="Where does this fall in the Sunken Treasure chain?",a="This follows the first part of Sunken Treasure, when Professor Phizzlethorpe charged the goggles. A third part follows.",al={"what comes before this","what is the next step"}}},kw={"arathi highlands","captain o'breen","doctor draxlegauge","elven gem","faldir's cove","fleet master seahorn","goggles of gem hunting","sunken treasure"},rel={"subzone:faldir-s-cove","zone:arathi","npc:fleet-master-seahorn"},m={start="Doctor Draxlegauge",["end"]="Doctor Draxlegauge",level="40",id=666,ri={"Elven Gem"}},src={"Sunken Treasure (2)"}}
E["quest:667"] = {t="quest",n="Death From Below",z="arathi",s="Aboard Shakes O'Breen's ship in the Arathi Highlands, the Daggerspine naga gather to strike. You stand with O'Breen, man the cannon, and help the crew sail back to Booty Bay.",h="Aboard Shakes O'Breen's ship in the Arathi Highlands, the Daggerspine naga gather to strike.",sec={{t="Holding the Deck",b="After the Sunken Treasure, Shakes O'Breen sees the Daggerspine naga gathering to attack. They are ruthless and will keep coming until O'Breen is dead. O'Breen puts the crew's safety ahead of their own and asks you to defend them. Without O'Breen's knowledge of the seas, the crew cannot reach Booty Bay. So you wait aboard with O'Breen for the naga to rise from the water.",sp=0},{t="Afterward",b="When the attack ends, O'Breen says the ship will leave as soon as the tide rises. O'Breen would have offered you a place on the crew, but sees that you have bigger fish to fry.",sp=1}},faq={{q="Who is attacking Shakes O'Breen?",a="The Daggerspine naga gather to attack Shakes O'Breen. They come from the sea and will keep coming until O'Breen is dead.",al={"who attacks shakes","who are the attackers","daggerspine attack"}},{q="Why is protecting Shakes O'Breen so vital to the crew?",a="Shakes O'Breen puts the crew's safety ahead of their own. Without O'Breen's knowledge of the seas, the crew cannot sail back to Booty Bay.",al={"why protect shakes obreen","why is shakes important","shakes obreen navigation"}},{q="How do you repel the naga assault?",a="You stay aboard Shakes O'Breen's ship and man the cannon. You drive back the naga as they come from the sea.",al={"how to beat death from below","how to defend shakes","cannon defense"}},{q="Where does this defense take place?",a="You defend Shakes O'Breen's ship in the Arathi Highlands as the naga come from the sea.",al={"where is death from below","death from below location"}}},kw={"arathi highlands","booty bay","daggerspine","naga","shakes o'breen","ship cannon"},rel={"topic:naga","zone:arathi","subzone:booty-bay"},m={start="Shakes O'Breen",["end"]="Shakes O'Breen",level="44",id=667},src={"Death From Below (Classic)"}}
E["quest:668"] = {t="quest",n="Sunken Treasure",z="arathi",s="Doctor Draxlegauge sends you to Captain O'Breen, who waits at the bridge for the elven gems. After weeks among pirates, the doctor and the professor have learned that keeping pirate treasure is bad for their health.",h="Doctor Draxlegauge sends you to Captain O'Breen, who waits at the bridge for the elven gems.",sec={{t="Treasure for the Captain",b="Doctor Draxlegauge is eager to bring Captain O'Breen the elven gems. The captain waits at the bridge and wants to see them for himself. After weeks among these pirates, the doctor and the professor have learned that keeping pirate treasure is bad for their health. So Draxlegauge gives you the gems to carry to O'Breen.",sp=0}},faq={{q="Who sends you to Captain O'Breen?",a="Doctor Draxlegauge gives you the elven gems to carry to Captain O'Breen.",al={"who gives sunken treasure 3","draxlegauge quest"}},{q="Why is Doctor Draxlegauge so eager to give up the gems?",a="After weeks among these pirates, Doctor Draxlegauge and the professor have learned that keeping pirate treasure is bad for their health.",al={"why hand over elven gems","why give gems to pirate"}},{q="Where does this fall in the chain?",a="This follows the second part of Sunken Treasure, and a fourth part comes after it.",al={"sunken treasure chain position","what comes before sunken treasure 3"}}},kw={"arathi highlands","captain o'breen","doctor draxlegauge","elven gems","pirates","shakes o'breen","sunken treasure"},rel={"zone:arathi","topic:pirate","topic:gnome"},m={start="Doctor Draxlegauge",["end"]="Shakes O'Breen",level="40",id=668},src={"Sunken Treasure (3)"}}
E["quest:669"] = {t="quest",n="Sunken Treasure",z="arathi",s="In Sunken Treasure, Shakes O'Breen is held back by the low tide and watchful creatures, so word must reach Booty Bay.",h="In Sunken Treasure, Shakes O'Breen is held back by the low tide and watchful creatures, so word must reach...",sec={{t="Word for Booty Bay",b="Shakes O'Breen needs Fleet Master Seahorn in Booty Bay to hear of the find at once. The tide is too low for him to leave, and the creatures his crew disturbed watch every move. He asks you to tell Seahorn the treasure has been found and more is being brought up. You carry a sample elven gem as proof.",sp=0}},faq={{q="Why can't Shakes O'Breen deliver the gem himself?",a="The tide is too low for Shakes O'Breen and his crew to leave, and the creatures they disturbed watch their movements.",al={"why cant shakes leave","why is shakes stuck","why does shakes need a courier"}},{q="Who is Fleet Master Seahorn?",a="Fleet Master Seahorn is in Booty Bay, and O'Breen wants him to hear of the find at once.",al={"who is seahorn","where is fleet master seahorn"}},{q="What proof is being carried to Booty Bay?",a="You carry a sample elven gem to prove the treasure was found and more is being brought up.",al={"what is the proof","what gem is delivered"}}},kw={"arathi highlands","blackwater raiders","booty bay","fleet master seahorn","sample elven gem","shakes o'breen","sunken treasure"},rel={"npc:fleet-master-seahorn","subzone:booty-bay","zone:arathi"},m={start="Shakes O'Breen",["end"]="Fleet Master Seahorn",level="40",id=669},src={"Sunken Treasure (4)"}}
E["quest:671"] = {t="quest",n="Foul Magics",z="arathi",s="In the Arathi Highlands, Tor'gan follows a demonic presence to Northfold Manor. From Hammerfall, he seeks help recovering bloodstone amulets from the summoners.",h="In the Arathi Highlands, Tor'gan follows a demonic presence to Northfold Manor.",sec={{t="A Simmering Rage",b="Demonic energy stirs in the Arathi Highlands, and Tor'gan feels it from his post at Hammerfall. The pull draws the orc west toward Northfold Manor. There, he finds signs of demonic summoning, but the lingering corruption makes his blood boil and stirs an involuntary rage tied to the blood curse's history. He retreats before the influence overwhelms his senses, then seeks help from others.",sp=0},{t="The Bloodstone Amulets",b="At Northfold Manor, Tor'gan found a bloodstone amulet on the ground. It showed that dark rituals were being performed there. Such charms help channel and steady demonic summonings, but the amulet he recovered had lost its magic. It held too little power for a thorough study. Tor'gan asks Horde travelers to retrieve ten intact amulets from the manor's practitioners, so he can examine the rituals and learn what entities were summoned.",sp=0}},faq={{q="Who gives the quest Foul Magics?",a="Tor'gan gives the request from Hammerfall, the Horde stronghold in the Arathi Highlands. Sensing a demonic presence nearby, he asks travelers to investigate Northfold Manor.",al={"foul magics quest giver","who starts foul magics","torgan quest arathi"}},{q="Where is Northfold Manor located?",a="Northfold Manor lies west of Hammerfall, in the northern hills of the Arathi Highlands. Once a human homestead, it is now the site of covert demonic summonings using bloodstone charms.",al={"northfold manor location","where is northfold manor","find northfold manor arathi"}},{q="What are Bloodstone Amulets used for?",a="Bloodstone amulets help practitioners channel dark magic during demonic summonings. When a summoning drains an amulet's power, the charm is depleted.",al={"what is bloodstone amulet","bloodstone amulet purpose","why bloodstone amulets"}},{q="Why does Tor'gan feel rage near Northfold Manor?",a="Lingering demonic summoning energies near Northfold Manor stir Tor'gan's rage. Fel magic makes his blood boil and ignites an uncontrollable rage.",al={"why torgan blood boils","torgan rage northfold","why does torgan get angry"}},{q="Why does Tor'gan refuse to return to Northfold Manor?",a="Tor'gan fears the residual demonic power will stir dangerous rage in him. Worried he could lose control or succumb to its corrupting influence, he asks others to recover the amulets.",al={"why wont torgan go to northfold","why torgan doesnt go back","why cant torgan get amulets"}},{q="How many Bloodstone Amulets are needed?",a="Tor'gan asks for ten bloodstone amulets from Northfold Manor. The one he found was depleted, so he needs multiple charged specimens to study and understand the rituals there.",al={"how many bloodstone amulets","bloodstone amulet count","foul magics objective count"}},{q="Who is summoning demons at Northfold Manor?",a="Dark practitioners at Northfold Manor conduct demonic summonings. Their rituals and the fel residue drew Tor'gan's attention from Hammerfall and led to the Horde's investigation.",al={"who is at northfold manor","who is summoning demons northfold","northfold manor cultists"}}},ang={["race:Orc"]="As an orc, you carry a deep and painful history of demonic corruption. Residual fel magic can make your blood boil and stir unnatural rage, as Tor'gan feels near Northfold Manor.",["faction:Horde"]="As a member of the Horde, you know Hammerfall is its lone outpost in the Arathi Highlands. Dark summoners just west of the settlement pose a direct security threat.",["class:Warlock"]="As a warlock, you know the rituals and binding reagents needed to summon demons. The bloodstone amulets at Northfold Manor are objects of particular interest."},kw={"arathi highlands","bloodstone","bloodstone amulet","demonic summoning","foul magics","hammerfall","northfold manor","tor'gan"},rel={"subzone:northfold-manor","subzone:hammerfall"},m={faction="Horde",id=671},src={"In-game quest text: Foul Magics"},fv=true}
E["quest:672"] = {t="quest",n="Raising Spirits",z="arathi",s="Tor'gan seeks a way to lift Gor'mul's spirits at Hammerfall in the Arathi Highlands. Tales of Orgrimmar and Warchief Thrall have brought no comfort, so Tor'gan turns to the Horde's newly rediscovered shamanic traditions.",h="Tor'gan seeks a way to lift Gor'mul's spirits at Hammerfall in the Arathi Highlands.",sec={{t="A Heavy Heart in Hammerfall",b="At Hammerfall in the Arathi Highlands, Gor'mul has fallen into deep melancholy. His companions have told him of Kalimdor, the mighty city of Orgrimmar, and Warchief Thrall's leadership. Yet none of these tales has eased his gloom or given him hope.",sp=0},{t="Spirits of the Wild",b="Tor'gan turns to the Horde's revived spiritual traditions to help Gor'mul. He gathers the eyes of highland raptors roaming Arathi and makes an amulet blessed with their spirits. Through this rite, he hopes the predators' vital force will awaken Gor'mul's will to live.",sp=0}},faq={{q="Who is Tor'gan?",a="Tor'gan is a troll shaman stationed at Hammerfall in the Arathi Highlands. He hopes to help Gor'mul with an amulet made through the Horde's newly rediscovered shamanic traditions.",al={"who is tor'gan","torgan hammerfall","quest giver raising spirits"}},{q="Who is Gor'mul and why does he need cheering up?",a="Gor'mul is an orc at Hammerfall, sunk in despondency and lethargy. Tales of Orgrimmar and Warchief Thrall have not lifted his spirits.",al={"who is gormul","why is gormul sad","orc depressed hammerfall"}},{q="Why does Tor'gan need highland raptor eyes?",a="Tor'gan uses the eyes of Highland Striders and Highland Thrashers to make a shamanic amulet. He hopes their spirits will lend Gor'mul strength and tenacity, and rekindle his fighting spirit.",al={"why raptor eyes","raptor eyes amulet","purpose of raptor eyes"}},{q="Where does this quest take place?",a="Hammerfall is the Horde outpost in the Arathi Highlands. It is named for former Warchief Orgrim Doomhammer and is a fortified haven for orcs remaining in the Eastern Kingdoms.",al={"where is hammerfall","hammerfall location","orcs in arathi"}},{q="What is the newly found shamanistic magic mentioned by Tor'gan?",a="Orcs lost their spiritual bond with the elements and ancestor spirits during demonic corruption and internment. Under Warchief Thrall, the Horde has reclaimed the ancient shamanic path, guided by spiritual harmony rather than fel magic.",al={"shaman magic orcs","orc shamanism new horde","why new shaman magic"}},{q="What stories failed to cheer up Gor'mul?",a="Gor'mul's companions told him of Orgrimmar, the new capital across the sea in Kalimdor, and of Warchief Thrall wielding Orgrim Doomhammer's armor and legendary warhammer.",al={"stories about thrall","what stories did they tell gormul","orgrimmar tales gormul"}}},ang={["class:Shaman"]="As a shaman, you see the Horde's revived traditions brought to bear against Gor'mul's despondency. Tor'gan calls on animal spirits to rekindle his will to live.",["race:Orc"]="As an orc, you know internment and the loss of old ways have burdened veterans like Gor'mul with despair and lethargy. Some struggle to embrace Thrall's new Horde.",["faction:Horde"]="As a member of the Horde, you see comrades at remote outposts like Hammerfall caring for despondent brothers-in-arms."},kw={"arathi highlands","gor'mul","hammerfall","highland raptor eyes","orgrimmar","raising spirits","shamanism","thrall","tor'gan"},rel={"subzone:hammerfall","npc:thrall","zone:orgrimmar"},m={faction="Horde",id=672},src={"In-game quest text: Raising Spirits"},fv=true}
E["quest:673"] = {t="quest",n="Foul Magics",z="arathi",s="In Hammerfall, Tor'gan fears a warlock in Stromgarde is calling demons with an arcane relic. Your first work for him has led to a hunt for the warlock and the relic.",h="In Hammerfall, Tor'gan fears a warlock in Stromgarde is calling demons with an arcane relic.",sec={{t="A Warlock in Stromgarde",b="Tor'gan is certain a warlock within Stromgarde's walls uses an arcane relic to call up terrible demons in great numbers. The burning in his blood grows by the day. So he sends you to find and kill the warlock, then bring back the magical object on the warlock's body. He means to destroy it before its power can taint the land. The warlock is Marez Cowl, and the object is a Befouled Bloodstone Orb.",sp=0},{t="What the Orb Recalls",b="With the orb destroyed, Tor'gan expects his restless nights to give way to peaceful sleep. The orb recalls the dreadful hold demons once had over the orcs. That hold endured until Hellscream freed them from their curse.",sp=1}},faq={{q="Who sends you to hunt the warlock?",a="Tor'gan in Hammerfall sends you into Stromgarde to find the warlock and bring him the magical object on the warlock's body.",al={"who gives foul magics","foul magics quest giver","torgan quest"}},{q="Where is the warlock located?",a="Marez Cowl hides within Stromgarde's walls, west of and outside the Keep, behind a building. You can hear her channeling a spell.",al={"where is marez cowl","stromgarde warlock location","where to find marez cowl"}},{q="What relic are you sent to retrieve?",a="You are sent to retrieve Marez Cowl's Befouled Bloodstone Orb. Tor'gan wants it brought to him for destruction.",al={"what item does torgan want","befouled bloodstone orb","foul magics item"}},{q="Why does Tor'gan want the warlock stopped?",a="The warlock has summoned terrible demons in large numbers using an arcane relic. Tor'gan wants you to remove the relic's power and destroy the orb before it can taint the land.",al={"why destroy the orb","torgan motivation","why stop the warlock"}}},kw={"arathi highlands","bloodstone","hammerfall","marez cowl","stromgarde","torgan","warlock"},rel={"quest:671","subzone:hammerfall","subzone:stromgarde-keep","topic:warlock","zone:arathi"},m={start="Tor'gan",["end"]="Tor'gan",level="40",faction="Horde",id=673,ri={"Befouled Bloodstone Orb"}},src={"Foul Magics (2)"}}
E["quest:674"] = {t="quest",n="Raising Spirits",z="arathi",s="A Horde emissary hopes Raising Spirits will help Gor'mul find his fighting spirit again. The Raptor Talon Amulet is meant to rekindle it, but Gor'mul remains bitter and doubts any trinket can restore the Horde's former glory.",h="A Horde emissary hopes Raising Spirits will help Gor'mul find his fighting spirit again.",sec={{t="A Spark for a Fallen Flame",b="An emissary brings Gor'mul a Raptor Talon Amulet, hoping its power will reach him. The talisman channels the wild strength and ferocity of raptors. It is meant to rekindle the flame that once burned fiercely within the orc warrior.",sp=0},{t="Bitterness and Despair",b="Gor'mul answers the gift with bitter grief. He remembers the mightiest champions struck down by cowardly hands and rejects the talisman as polished bone. He doubts any trinket can restore the Horde to its former glory.",sp=1}},faq={{q="What is Raising Spirits?",a="A Horde emissary brings Gor'mul a Raptor Talon Amulet, hoping it will rekindle the despondent warrior's fighting spirit.",al={"what is raising spirits","raising spirits quest"}},{q="Who is Gor'mul?",a="Gor'mul is a warrior consumed by despair after the mightiest champions fell to cowardly hands. He dismisses tokens and doubts the Horde can regain its former glory.",al={"who is gormul","gor mul"}},{q="Why is the Raptor Talon Amulet brought to Gor'mul?",a="The Raptor Talon Amulet is crafted from polished bone and raptor talons. It is brought to Gor'mul in hope that it can channel raptors' natural strength and ferocity to awaken his inner flame.",al={"why bring amulet","what does raptor talon amulet do"}},{q="Why is Gor'mul despondent?",a="Gor'mul despairs after seeing the mightiest champions slain by cowardly hands. Their fall leaves him convinced that honor and strength can be snuffed out, breaking his will to fight.",al={"why is gormul sad","why is gormul depressed"}},{q="How does Gor'mul react to the amulet?",a="Gor'mul rejects the gift as mere polished bone. He believes it cannot restore the Horde or undo the tragedy he laments.",al={"does gormul like the amulet","gormul reaction"}},{q="What does Gor'mul say about the Horde?",a="Gor'mul doubts the Horde can reclaim its former glory, seeing little hope when treachery can strike down even the greatest heroes.",al={"can the horde be restored","gormul horde glory"}}},ang={["faction:Horde"]="As a member of the Horde, you hear Gor'mul mourn its fallen might and question whether a simple trinket can restore its lost glory.",["class:Warrior"]="As a warrior, you hear of an orc whose fighting spirit has been extinguished by despair and grief over a cowardly strike."},kw={"gor'mul","gormul","horde","raising spirits","raptor amulet","raptor talon amulet","warrior"},rel={"topic:horde","topic:warrior"},m={faction="Horde",id=674},src={"In-game quest text: Raising Spirits"},fv=true}
E["quest:675"] = {t="quest",n="Raising Spirits",z="arathi",s="Tor'gan hopes ancestral magic can restore Gor'mul's pride and will to live. The shaman seeks to lift an old orc veteran from despair.",h="Tor'gan hopes ancestral magic can restore Gor'mul's pride and will to live.",sec={{t="A Broken Spirit",b="Gor'mul grieves that he survived when his fallen Warchief did not. Many orc veterans bear the weight of past wars, but Gor'mul believes fate denied him an honorable death beside his leader. Tor'gan, a shaman, hopes to ease that sorrow by recalling his people's spiritual strength. He prepares an enchanted amulet and trusts ancestral power to rekindle the old warrior's pride.",sp=0},{t="The Limits of the Amulet",b="Tor'gan's amulet reaches Gor'mul, but brings no comfort. Gor'mul casts it into the dirt and asks why anyone would show him mercy when fate denied him an honorable end. Tor'gan accepts that one charm cannot overcome years of sorrow. Still, he remains committed to helping Gor'mul, believing the growing practice of shamanism can guide him back to his former honor.",sp=1}},faq={{q="Who is Gor'mul?",a="Gor'mul is an embittered orc veteran who survived the older Horde's conflicts after his Warchief fell. He believes fate cruelly denied him an honorable death beside that leader and rejects ordinary sympathy.",al={"who is gormul","gormul backstory","what is wrong with gormul"}},{q="Who is Tor'gan and why is he helping Gor'mul?",a="Tor'gan is a shaman trying to lift Gor'mul from despair. He believes ancestral ways can restore broken spirits and shamanism can bring former warriors to spiritual rebirth. He crafts infused charms to remind them of their people's strength.",al={"who is torgan","what does torgan want","torgan purpose"}},{q="What was the purpose of the amulet?",a="Tor'gan prepared the enchanted amulet to awaken Gor'mul's warrior spirit through shamanic energy. Gor'mul rejected it and threw it to the ground, believing its magic could not dispel his bitterness.",al={"what is the amulet","why did gormul throw the amulet","did the amulet work"}},{q="Which Warchief does Gor'mul mourn?",a="Gor'mul does not name the Warchief he mourns. He curses fate for denying him death beside his fallen leader in battle.",al={"which warchief died","who was gormuls warchief","who did gormul serve"}},{q="What does Tor'gan plan to do after the amulet fails?",a="Tor'gan accepts that the amulet lacked enough power on its own. He remains patient and believes shamanism's true power can rekindle Gor'mul's lost pride.",al={"does torgan give up","what happens after raising spirits","will gormul recover"}},{q="Why does Tor'gan use shamanism to help Gor'mul?",a="Tor'gan uses shamanism to mend wounded minds and pride among his people. Shamans heal those wounds and channel the elements for war.",al={"what does this show about shamans","why use shaman magic here"}}},ang={["class:Shaman"]="As a shaman, you see how orcish shamanism can restore the spirits of veterans still burdened by trauma.",["race:Orc"]="As an orc, you may recognize the dishonor Gor'mul feels at being denied an honorable death beside his former Warchief.",["faction:Horde"]="Under Thrall's leadership, the Horde seeks to reintegrate and uplift embittered veterans rather than abandon them to despair."},kw={"amulet","gor'mul","mercy","orc","raising spirits","shaman","tor'gan","veteran","warchief"},rel={"topic:shaman"},m={faction="Horde",id=675},src={"In-game quest text: Raising Spirits"},fv=true}
E["quest:677"] = {t="quest",n="Call to Arms",z="arathi",s="Drum Fel calls the Horde to strike from Hammerfall in the Arathi Highlands. The Witherbark have joined the Boulderfist ogres, and the Horde means to hold its foothold there.",h="Drum Fel calls the Horde to strike from Hammerfall in the Arathi Highlands.",sec={{t="Defending Hammerfall",b="At Hammerfall, Drum Fel rallies the Horde from its fortified outpost in the Arathi Highlands. Old human ruins and hostile powers surround the settlement. The Witherbark forest trolls and Boulderfist ogres have made a pact, putting the Horde's foothold at risk. Drum Fel calls on champions to strike first and keep their enemies from deciding the struggle's course.",sp=0},{t="The Witherbark Threat",b="South of Hammerfall, the Horde's first strikes reach Witherbark territory. The forest trolls have rejected diplomacy and joined the Boulderfist ogres in trying to drive the Horde from the highlands. Hammerfall targets their axe throwers, headhunters and witch doctors to weaken their leaders and show that the Horde intends to stay.",sp=0}},faq={{q="Who offers the quest Call to Arms?",a="Drum Fel, an orc at Hammerfall in the northeastern Arathi Highlands, calls the Horde to fight. He directs defensive and offensive strikes to protect the outpost from nearby threats.",al={"who gives call to arms","where is drum fel","quest giver call to arms"}},{q="Why is Hammerfall targeting the Witherbark trolls?",a="The Witherbark forest trolls have joined the Boulderfist ogres in trying to drive the Horde from the Arathi Highlands. Their hostility puts Hammerfall's foothold at risk.",al={"why kill witherbark","why attack trolls arathi","what did witherbark do"}},{q="Where are the Witherbark trolls located?",a="The Witherbark trolls live in settlements and camps south of Hammerfall, including deep in Witherbark Village near the mountains.",al={"where are witherbark trolls","witherbark camp location","where to find axe throwers arathi"}},{q="What role do the Boulderfist ogres play in this conflict?",a="The Boulderfist are a brutal ogre clan in the Arathi Highlands. Drum Fel says they have joined the Witherbark trolls in trying to drive the Horde from the highlands.",al={"who are boulderfist","ogres in arathi","boulderfist troll alliance"}},{q="What is Hammerfall and why does it need defending?",a="Hammerfall is the Horde's main outpost in the Arathi Highlands, named for Warchief Orgrim Doomhammer. It occupies an old Alliance internment camp and gives the Horde a hard-won sanctuary and military base in the Eastern Kingdoms.",al={"what is hammerfall","hammerfall lore","why is horde in arathi"}},{q="Are the Witherbark trolls part of the Horde?",a="No. The Witherbark are forest trolls native to the Eastern Kingdoms, while the Darkspear jungle trolls belong to the Horde. The Witherbark reject outsiders and have violently refused the Horde's offers.",al={"are witherbark in the horde","are forest trolls friendly to horde","darkspear vs witherbark"}}},ang={["faction:Horde"]="Hammerfall is isolated in the Arathi Highlands, with hostile forces around it. Defending the outpost matters as the Horde tries to hold a place in human lands.",["race:Orc"]="Hammerfall occupies the grounds of a former Second War internment camp. As an orc, defending this new settlement against hostile neighbors carries the weight of liberation.",["race:Troll"]="As a Darkspear troll serving Thrall's Horde, you face the hostile Witherbark forest trolls. Their rejection of the new Horde marks a sharp divide between your peoples."},kw={"arathi highlands","axe thrower","boulderfist","call to arms","drum fel","hammerfall","headhunter","witch doctor","witherbark"},rel={"npc:drum-fel","subzone:hammerfall","topic:troll"},m={faction="Horde",id=677},src={"In-game quest text: Call to Arms"},fv=true}
E["quest:678"] = {t="quest",n="Call to Arms",z="arathi",s="At Hammerfall, Drum Fel sends proven warriors against the Boulderfist ogres. Their attacks threaten the Horde's foothold in Arathi.",h="At Hammerfall, Drum Fel sends proven warriors against the Boulderfist ogres.",sec={{t="A Test of Mettle",b="At Hammerfall, Drum Fel calls on travelers who have aided the outpost to face a real threat. Boulderfist ogres have harassed the Horde expedition and tested its defenders. Fel sends warriors against these foes, not minor skirmishers. He expects them to return alive or with honor, and promises praise for their tenacity in battle.",sp=0},{t="The Boulderfist Threat",b="Southwest of Hammerfall, the Boulderfist clan has dug in near the dwarven bridge between Arathi and the Wetlands. Brutes fight alongside cunning magi, bringing crushing strength and deadly magic. Their aggression threatens Horde supply lines and control of the region. Drum Fel orders warriors to defeat ten Boulderfist brutes and four magi. Their defeat will weaken the clan and show that Hammerfall will not yield ground or tolerate rivals in Arathi.",sp=0}},faq={{q="Who gives the Call to Arms quest?",a="Drum Fel, an officer at Hammerfall in the northeastern Arathi Highlands, gives the call. He sends proven fighters against dangerous foes to protect the outpost and test their strength.",al={"who gives call to arms","drum fel quest","call to arms questgiver"}},{q="Where is the Boulderfist lair located?",a="The Boulderfist lair lies southwest of Hammerfall, along the way to Thandol Span, the dwarven bridge to the Wetlands. Brutes and magi gather in earthen dens and mounds in the highlands.",al={"boulderfist location","where are the ogres","boulderfist lair arathi"}},{q="Which enemies need to be defeated for this task?",a="Drum Fel calls for ten Boulderfist Brutes and four Boulderfist Magi to be defeated before returning to Hammerfall. Brutes attack at close range, while magi cast arcane spells from afar.",al={"call to arms kill count","which ogres to kill","call to arms targets"}},{q="Why are the Boulderfist ogres considered a threat to Hammerfall?",a="The Boulderfists have dug in across Arathi and repeatedly challenged Hammerfall's Horde garrison. Their position near routes to the southern dwarven bridge threatens Horde scouting and supply lines, so Drum Fel wants their strength contained.",al={"why fight boulderfists","are boulderfists hostile to horde","ogre threat in arathi"}},{q="What does Drum Fel mean by returning in body or in spirit?",a="Drum Fel expects his fighters to return alive after succeeding, but honors those who fall fighting valiantly against formidable foes. Facing the ogres with tenacity and fearlessness brings honor, whether a warrior survives or not.",al={"drum fel quote","return in spirit meaning","come in body or spirit"}},{q="Can Alliance players undertake this quest?",a="No. Drum Fel gives this call only to the Horde at Hammerfall. Alliance forces operate from Refuge Pointe to the west and regard Hammerfall's defenders and the Boulderfist ogres as hostile rivals for control of the Arathi Highlands.",al={"is call to arms horde only","alliance call to arms arathi","can alliance do this quest"}},{q="Why does Drum Fel target both brutes and magi?",a="The brutes form the front line and absorb blows, while the magi attack from the rear with destructive magic. Defeating both kinds weakens the Boulderfists' combined strength and keeps them from mounting an organized counterattack against Hammerfall.",al={"why kill magi","boulderfist magi importance","boulderfist brute and magus"}}},ang={["faction:Horde"]="As a member of the Horde, you help secure Hammerfall's foothold in the Eastern Kingdoms by driving back the aggressive Boulderfist ogres.",["race:Orc"]="As an orc, you have a personal stake in Hammerfall, named for Warchief Orgrim Doomhammer, and in driving out the rival brutes threatening this memorial stronghold.",["class:Warrior"]="As a warrior, you face a direct test of endurance and honor against brute force and arcane power.",["class:Mage"]="As a mage, you face Boulderfist Magi who wield arcane energies for destructive ends."},kw={"arathi highlands","boulderfist","boulderfist brute","boulderfist magi","call to arms","drum fel","hammerfall","ogres","thandol span"},rel={"npc:drum-fel","subzone:hammerfall"},m={faction="Horde",id=678},src={"In-game quest text: Call to Arms"},fv=true}
E["quest:679"] = {t="quest",n="Call to Arms",z="arathi",s="At Hammerfall, Drum Fel sends you after the Boulderfist leaders in Stromgarde. After your earlier work, he says it is time to strike the head from the beast.",h="At Hammerfall, Drum Fel sends you after the Boulderfist leaders in Stromgarde.",sec={{t="The Head of the Beast",b="Drum Fel says you are ready to help deliver one last great blow. The Boulderfist leaders have made their lair in Stromgarde’s ruins, which he calls a symbol of human frailty. He sends you to hunt down the lords and the shaman who serve them. They lead attacks meant to drive the Horde from these lands.",sp=0}},faq={{q="Who sends you to fight the Boulderfist leaders?",a="Drum Fel sends you from Hammerfall, the Horde outpost in the Arathi Highlands.",al={"who gives call to arms","drum fel quest","who starts call to arms 3"}},{q="Where are the Boulderfist lords and shaman located?",a="The Boulderfist lords and shaman leading the attacks are holed up in Stromgarde’s ruins, Drum Fel says.",al={"where are boulderfist lords","boulderfist shaman location","where to find ogre leaders"}},{q="Where does this step fit into the chain?",a="This follows the previous Call to Arms and is the last step in the chain that begins with Tallow in Tarren Mill.",al={"what came before call to arms 3","call to arms chain","hammerfall ogre chain"}},{q="What does Drum Fel want done to the Boulderfist leaders?",a="Drum Fel wants you to kill the lords and shaman leading the attacks in one last great blow. They mean to drive the Horde from these lands.",al={"why kill boulderfist lords","why attack stromgarde ogres"}}},kw={"arathi highlands","boulderfist","boulderfist lords","boulderfist shaman","drum fel","hammerfall","stromgarde"},rel={"quest:677","subzone:hammerfall","npc:drum-fel","quest:680","quest:676","npc:tallow","subzone:tarren-mill","zone:arathi"},m={start="Drum Fel",["end"]="Drum Fel",level="40",faction="Horde",id=679},src={"Call to Arms (3)"}}
E["quest:680"] = {t="quest",n="The Real Threat",z="arathi",s="Korin Fel asks you to end the attacks on Hammerfall by slaying Or'Kalar and bringing her his head.",h="Korin Fel asks you to end the attacks on Hammerfall by slaying Or'Kalar and bringing her his head.",sec={{t="A Grudge Against Her Husband",b="Korin Fel says you serve her husband well, though he does not know why Hammerfall is under attack. Or'Kalar serves Mug'thol in Stromgarde and seeks her husband's death. Years ago, her husband defeated the ogre. Now Korin's auguries warn that Or'Kalar has set a trap for him.",sp=0},{t="What Korin Hides",b="Korin has hidden the signs of Or'Kalar's presence from her husband. She fears he would rush off foolishly if he knew where the ogre was, so she asks you to help instead. Or'Kalar is near the Tower of Arathor. Korin expects his death to end the attacks on Hammerfall.",sp=0}},faq={{q="Who is Korin Fel trying to protect?",a="Korin Fel is trying to protect her husband. Her auguries warn that Or'Kalar has set a trap for him. The ogre wants him dead because he defeated him years ago.",al={"korin husband","why does korin need help"}},{q="Why is Or'Kalar attacking Hammerfall?",a="Or'Kalar attacks Hammerfall as Mug'thol's pawn in Stromgarde. He hates Korin Fel's husband, who defeated him years ago. Korin says Or'Kalar's death would stop the attacks.",al={"why does or'kalar hate korin's husband","who is or'kalar","or'kalar motive"}},{q="Where is Or'Kalar located?",a="Close to the Tower of Arathor.",al={"or'kalar location","where to find or'kalar","find or'kalar"}},{q="Why does Korin keep the threat a secret from her husband?",a="Korin fears her husband would rush off foolishly if he learned where Or'Kalar was. So she has hidden every sign of the ogre's presence.",al={"why keep it secret","why hide or'kalar","korin secret"}}},kw={"arathi highlands","hammerfall","korin fel","mug'thol","or'kalar","stromgarde","tower of arathor"},rel={"quest:677","quest:676","subzone:hammerfall","subzone:tower-of-arathor","zone:arathi"},m={start="Korin Fel",["end"]="Korin Fel",level="40",faction="Horde",id=680,ri={"Or'Kalar's Head"}},src={"The Real Threat (Classic)"}}
E["quest:681"] = {t="quest",n="Northfold Manor",z="arathi",s="At Refuge Pointe, Captain Nials seeks your help against the Syndicate at Northfold Manor. Their hold between Stromgarde's defenders and Southshore slows supplies.",h="At Refuge Pointe, Captain Nials seeks your help against the Syndicate at Northfold Manor.",sec={{t="A Struggling Defense",b="Ogres, the Syndicate and the Alliance divide Stromgarde, and the factions fight to a bloody stalemate. The Alliance's forces dwindle as their enemies grow. The defenders need help from Southshore, but supplies arrive slowly.",sp=0},{t="The Syndicate at the Manor",b="The Syndicate holds the ground between the defenders and Southshore. Captain Nials asks you to go to Northfold Manor, the Syndicate's base, and cut down their highwaymen and mercenaries. He hopes easing their pressure will let more supply trains through.",sp=0}},faq={{q="Why does Captain Nials want the Syndicate attacked at Northfold Manor?",a="The Syndicate holds the land between the defenders and Southshore. Captain Nials hopes that slaying them at their base will ease the pressure on the supply trains.",al={"why attack northfold manor","nials objective","purpose of northfold manor quest"}},{q="What is the current situation in Stromgarde?",a="Ogres, the Syndicate and the Alliance have divided Stromgarde, and the factions fight to a bloody stalemate. The Alliance's forces dwindle while its enemies grow.",al={"stromgarde war status","who controls stromgarde","state of stromgarde"}},{q="Where are the Alliance supplies coming from?",a="The defenders look to Southshore for help, but the Syndicate's hold on the land between makes supplies difficult to receive.",al={"who supplies refuge pointe","southshore supplies","where do shipments originate"}},{q="Which enemies need to be eliminated at the manor?",a="Ten Syndicate Highwaymen and six Syndicate Mercenaries at Northfold Manor.",al={"who to kill at northfold","northfold targets","syndicate enemies list"}}},kw={"captain nials","highwayman","mercenary","northfold manor","refuge pointe","southshore","stromgarde","syndicate"},rel={"subzone:refuge-pointe","subzone:northfold-manor","topic:syndicate","subzone:southshore","zone:arathi"},m={start="Captain Nials",["end"]="Captain Nials",level="31",faction="Alliance",id=681},src={"Northfold Manor (Classic)"}}
E["quest:682"] = {t="quest",n="Stromgarde Badges",z="arathi",s="In Stromgarde, the Syndicate pays for militia badges taken from the fallen. At Refuge Pointe, Captain Nials wants them brought back.",h="In Stromgarde, the Syndicate pays for militia badges taken from the fallen.",sec={{t="A Bounty on Soldiers",b="The Syndicate fights a contingent of militia in Stromgarde. Its leaders offer gold for every badge taken from a slain militiaman, hoping to turn their followers against the better-trained soldiers. Captain Nials calls the Syndicate cutthroats and refuses to let them keep trophies from the brave fallen. You enter the part of Stromgarde they hold and bring the badges back to Refuge Pointe. Nials wants them to learn they cannot profit from the dead.",sp=0},{t="After the Hunt",b="Captain Nials promises to tell the fallen militiamen's relatives that their kin died in battle. The news is grim, but he believes it is better than leaving a family to wonder what became of someone who went missing.",sp=1}},faq={{q="Why does the Syndicate want Stromgarde badges?",a="Syndicate leaders offer gold for every badge taken from a fallen militiaman. They hope the payment will drive their followers to fight the better-trained troops.",al={"why syndicate badges","syndicate bounty stromgarde","why collect badges"}},{q="Where are the badges found?",a="You find the badges in the part of Stromgarde controlled by the Syndicate.",al={"where to find badges","stromgarde badge location","badge drop location"}},{q="Who orders the retrieval of the badges?",a="Captain Nials at Refuge Pointe orders the badges recovered. She will not let the Syndicate keep trophies from the fallen militia.",al={"who gives stromgarde badges","captain nials badge quest","questgiver stromgarde badges"}}},kw={"arathi","badges","captain nials","militia","refuge pointe","stromgarde","syndicate"},rel={"subzone:refuge-pointe","topic:syndicate","zone:arathi"},m={start="Captain Nials",["end"]="Captain Nials",level="37",faction="Alliance",id=682},src={"Classic quest text: Stromgarde Badges"}}
E["quest:684"] = {t="quest",n="WANTED: Marez Cowl",z="arathi",s="At Stromgarde, Marez Cowl advises Syndicate leaders and traffics with demons. Her influence threatens Alliance forces in the Arathi Highlands.",h="At Stromgarde, Marez Cowl advises Syndicate leaders and traffics with demons.",sec={{t="A Price on Syndicate Leadership",b="At Refuge Pointe, Alliance commanders offer a bounty on a high-ranking Syndicate leader. Marez Cowl advises the Syndicate and directs its work in Stromgarde’s ruins as a field operative. The bounty aims to break the group’s local command.",sp=0},{t="The Warlock of Stromgarde",b="Marez Cowl is a warlock among the Syndicate’s brigands and dispossessed nobles. She deals openly with demonic powers to enforce her will and defend Syndicate territory. To reach her lair in Stromgarde, you must face armed criminals and the demons she commands.",sp=0}},faq={{q="Who is Marez Cowl?",a="Marez Cowl is a high-ranking Syndicate advisor and operative. She wields influence in the organization and is a dangerous warlock who traffics with demons.",al={"who is marez cowl","marez cowl background","who is she"}},{q="Where is Marez Cowl located?",a="Marez Cowl is in the Syndicate-held part of ruined Stromgarde, in the Arathi Highlands. Criminal forces are entrenched there, and you must find your way through them to reach her lair.",al={"where to find marez cowl","marez cowl location","where is marez"}},{q="Who posted the bounty on Marez Cowl?",a="The Alliance military in the Arathi Highlands offers the bounty. Captain Nials, commander of the Alliance stronghold at Refuge Pointe, oversees it.",al={"who posted bounty marez cowl","who wants marez cowl dead","who pays bounty"}},{q="Why is there a bounty on her head?",a="Marez Cowl is wanted for her Syndicate leadership and her use of demonic summoning in Stromgarde. She threatens the Alliance garrison trying to reclaim the ruined kingdom.",al={"why is marez cowl wanted","why bounty on marez cowl","why kill marez cowl"}},{q="What kind of magic does Marez Cowl use?",a="Marez Cowl uses warlock magic to summon and bargain with demons. Take extreme care when confronting her and the demons she commands.",al={"what makes marez cowl dangerous","marez cowl powers","is marez cowl strong"}},{q="Where do you turn in the bounty for Marez Cowl?",a="After Marez Cowl is slain, deliver her head to Captain Nials at Refuge Pointe, the Alliance outpost in the Arathi Highlands.",al={"where turn in marez cowl bounty","where is captain nials","turn in marez head"}}},ang={["faction:Alliance"]="The Alliance garrison at Refuge Pointe, led by Captain Nials, fights to reclaim Stromgarde. High-ranking Syndicate leaders like Marez Cowl are strategic priorities.",["class:Warlock"]="Marez Cowl belongs to the Syndicate’s darker occult wing. Her use of demonic summoning shows how political renegades turn to demons to extend their influence.",["class:Paladin"]="As a warlock who deals openly with demons in the ruins of an ancient human kingdom, Cowl affronts the Holy Light and Stromgarde’s defense."},kw={"arathi highlands","bounty","captain nials","marez cowl","refuge pointe","stromgarde","syndicate","warlock"},rel={"subzone:refuge-pointe","topic:syndicate","topic:warlock"},m={faction="Alliance",id=684},src={"In-game quest text: WANTED: Marez Cowl"},fv=true}
E["quest:685"] = {t="quest",n="WANTED: Otto and Falconcrest",z="arathi",s="In the Arathi Highlands, the Stromgarde Militia has marked Lord Falconcrest and Otto for death. Falconcrest leads the local Syndicate forces, and Otto guards him with deadly skill. Their deaths would weaken the Syndicate's hold in the region. Proof must reach Captain Nials at Refuge Pointe.",h="In the Arathi Highlands, the Stromgarde Militia has marked Lord Falconcrest and Otto for death.",sec={{t="A Desperate Bounty",b="From Refuge Pointe, Stromgarde's defenders seek to break the Syndicate's hold over their ancestral lands. The militia has placed a bounty on Lord Falconcrest and Otto, his bodyguard. Bring both targets' heads to Captain Nials to claim the reward.",sp=0},{t="Commander and Enforcer",b="Lord Falconcrest directs the Syndicate's push into the Arathi Highlands. His death would disrupt the criminal network's work in the region. Otto is a brutally effective bodyguard. His blades have killed dozens of Stromgarde's remaining militia soldiers.",sp=0}},faq={{q="Who is Lord Falconcrest?",a="Lord Falconcrest is a noble who commands the Syndicate's operations in the Arathi Highlands. He organizes their bid to seize the broken kingdom of Stromgarde, making him a chief target of the local human militia.",al={"who is lord falconcrest","falconcrest lore","who is falconcrest"}},{q="Who is Otto?",a="Otto is Lord Falconcrest's deadly personal bodyguard. A ferocious combatant rather than a strategist, he has slain dozens of Stromgarde defenders in the highlands.",al={"who is otto","falconcrest bodyguard","otto syndicate"}},{q="Why has the Stromgarde Militia placed a bounty on them?",a="The Stromgarde Militia seeks to cripple the Syndicate's leadership in the Arathi Highlands. Falconcrest's death would disrupt their regional command, while Otto's death would remove a lethal threat who has killed many Alliance fighters.",al={"why bounty on falconcrest","why kill otto and falconcrest","stromgarde bounty"}},{q="Who offers the reward for Otto and Falconcrest?",a="Captain Nials, an officer of the Stromgarde Militia at Refuge Pointe in the Arathi Highlands, collects the bounties for Lord Falconcrest and Otto.",al={"where turn in otto falconcrest","who is captain nials","falconcrest bounty turn in"}},{q="What is the Syndicate doing in the Arathi Highlands?",a="The Syndicate is made up of fallen Alteraci nobles and rogue elements seeking land and riches amid northern Lordaeron's collapse. From the Arathi Highlands, they have moved into Stromgarde's ruins to wrest control from its surviving defenders.",al={"what is the syndicate arathi","syndicate role arathi"}},{q="What proof is required to claim the bounty?",a="Bring the severed heads of Lord Falconcrest and Otto directly to Captain Nials at Refuge Pointe as proof of their deaths.",al={"where to take otto head","proof of bounty"}}},ang={["faction:Alliance"]="Lord Falconcrest and his Syndicate operatives threaten Stromgarde's remnants. This bounty matters to the effort to reclaim the highlands.",["race:Human"]="As a human, you face a personal fight. Bringing down the Syndicate's traitorous human nobles helps avenge your fallen kingdom."},kw={"arathi highlands","bounty","captain nials","falconcrest","otto","refuge pointe","stromgarde militia","syndicate"},rel={"topic:syndicate","subzone:refuge-pointe","zone:arathi"},m={faction="Alliance",id=685},src={"In-game quest text: WANTED: Otto and Falconcrest"},fv=true}
E["quest:687"] = {t="quest",n="Theldurin the Lost",z="arathi",s="In the Badlands, the Twilight's Hammer hunts for Theldurin the Lost and the scroll of Myzrael he took when he fled.",h="In the Badlands, the Twilight's Hammer hunts for Theldurin the Lost and the scroll of Myzrael he took when he...",sec={{t="The Man Who Stole the Scroll",b="Theldurin once followed the Twilight's Hammer. Then his mind slipped, and he turned from its teachings. He fled with the scroll of Myzrael, and the order could not catch him.",sp=0},{t="Rumors of the Badlands",b="Word has reached the Twilight's Hammer that Theldurin hides in the Badlands, raving and mad. The order needs the scroll for the Lady's return. First, you must find the man who took it.",sp=0}},faq={{q="Who is Theldurin the Lost?",a="Theldurin the Lost once followed the Twilight's Hammer. After his mind slipped, he rejected its teachings and fled with the scroll of Myzrael.",al={"theldurin backstory","who is theldurin","theldurin lore"}},{q="Why is the Twilight's Hammer looking for him?",a="The Twilight's Hammer seeks Theldurin because he fled with the scroll of Myzrael. The order says it needs the scroll to bring the Lady back.",al={"why find theldurin","why do cultists want theldurin"}},{q="Where did Theldurin flee after leaving the order?",a="Rumors place Theldurin in the Badlands, though the Twilight's Hammer is not certain where he is.",al={"where is theldurin","theldurin location lore"}},{q="What comes directly before this search?",a="The search follows Myzrael's Allies.",al={"previous quest theldurin","prereq for theldurin the lost"}}},kw={"badlands","gerrig bonegrip","myzrael","scroll of myzrael","theldurin","theldurin the lost","twilight's hammer","zaruk"},rel={"npc:theldurin-the-lost","topic:twilight-s-hammer","zone:badlands","zone:arathi"},m={start="Gerrig Bonegrip, Zaruk",["end"]="Theldurin the Lost",level="40",faction="Both",id=687},src={"Theldurin the Lost (quest)"}}
E["quest:688"] = {t="quest",n="Myzrael's Allies",z="arathi",s="Through the keystone, Myzrael declares herself free, though still hidden from her captors. She sends you to Zaruk in Hammerfall, who knows how to summon her.",h="Through the keystone, Myzrael declares herself free, though still hidden from her captors.",sec={{t="Free but Hidden",b="Myzrael declares that she is free through the keystone. She must gather her strength out of sight. Her captors would overpower and imprison her again if they faced her now. In time, she vows to confront the giants who held her and make them regret keeping her.",sp=0},{t="Zaruk of Hammerfall",b="Myzrael calls you a noble ally and says she will need your aid again in time. When ready, she will have you summon her to the surface. For now, she sends you to Zaruk in Hammerfall, who knows how it can be done.",sp=0}},faq={{q="Who sends you to Zaruk?",a="Myzrael herself speaks through the keystone and tells you to see Zaruk in Hammerfall.",al={"who gives myzraels allies","quest giver myzraels allies","who speaks through the keystone"}},{q="Why is Myzrael hiding?",a="Myzrael says her captors would overpower and imprison her again if they faced her now. She hides while gathering strength.",al={"why doesnt myzrael fight","why is myzrael weak","why does myzrael hide"}},{q="Where can Zaruk be found?",a="Zaruk can be found in Hammerfall.",al={"zaruk location","where is zaruk","find zaruk"}},{q="What role does Zaruk play for Myzrael?",a="Myzrael says Zaruk knows how she can be summoned.",al={"why talk to zaruk","what does zaruk know","zaruk purpose"}}},kw={"arathi highlands","giants","hammerfall","keystone","myzrael","zaruk"},rel={"subzone:hammerfall","zone:arathi"},m={start="Keystone",["end"]="Zaruk",level="40",faction="Horde",id=688},src={"Myzrael's Allies (Horde)"}}
E["quest:691"] = {t="quest",n="Worth Its Weight in Gold",z="arathi",s="At Refuge Pointe, Apprentice Kryten needs reagents for Archmage Malin. He asks you to gather tusks, medicine pouches and a shadow hunter's knife from the Witherbark trolls of southeastern Arathi.",h="At Refuge Pointe, Apprentice Kryten needs reagents for Archmage Malin.",sec={{t="Malin's Reagents",b="Archmage Malin sent Kryten and Skuerto to Arathi for reagents. Kryten was unsure how to gather them until you arrived. He needs ten Witherbark tusks, four medicine pouches and one shadow hunter knife. The Witherbark trolls live in southeastern Arathi.",sp=0},{t="What the Witherbark Carry",b="Kryten's research says every Witherbark troll should have tusks. The witch doctors carry medicine pouches. The knife belongs to the mightiest shadow hunters, who receive it after completing their rites of passage. Only battle will show which one carries it.",sp=0}},faq={{q="Who is Apprentice Kryten working for?",a="Archmage Malin sent Kryten and Skuerto to Arathi to gather reagents for him.",al={"who sent kryten","kryten master","why is kryten in arathi"}},{q="Where are the Witherbark trolls located?",a="In the southeast of Arathi, where the Witherbark make their home.",al={"witherbark location","where to find witherbark","witherbark village location"}},{q="Which trolls carry the medicine pouches?",a="Kryten's research says the Witherbark witch doctors carry medicine pouches. Any Witherbark troll should have tusks.",al={"medicine pouch source","who has medicine pouches","witherbark medicine pouch"}},{q="How do you find the shadow hunter knife?",a="The mightiest Witherbark shadow hunters carry the knife, given to them after their rites of passage. Only battle will reveal which one has it.",al={"shadow hunter knife location","who drops shadow hunter knife","rite of passage knife"}}},kw={"apprentice kryten","arathi highlands","archmage malin","medicine pouch","refuge pointe","shadow hunter knife","skuerto","witherbark","witherbark tusk"},rel={"npc:archmage-malin","npc:skuerto","subzone:refuge-pointe","subzone:witherbark-village","zone:arathi","topic:troll"},m={start="Apprentice Kryten",["end"]="Apprentice Kryten",level="36",faction="Alliance",id=691,ri={"Shadow Hunter Knife","Witherbark Medicine Pouch","Witherbark Tusk"}},src={"Worth Its Weight in Gold (Classic)"}}
E["quest:693"] = {t="quest",n="Wand over Fist",z="arathi",s="At Refuge Pointe, Skuerto has found where Trelane's first item went. Kor'gresh holds Trelane's Wand of Invocation in Boulderfist Hall, and Skuerto wants it back.",h="At Refuge Pointe, Skuerto has found where Trelane's first item went.",sec={{t="The Ogre and the Wand",b="After your work for Apprentice Kryten, Skuerto has traced Trelane's first item to Kor'gresh. The ogre holds the wand in Boulderfist Hall and uses blasts of ice to keep his kin in line. Skuerto fears Kor'gresh is close to discovering all its powers. Boulderfist Hall lies south of Refuge Pointe, then east of Thandol Span.",sp=0},{t="Skuerto's List",b="When you return, Skuerto counts the wand as one item found. Three more remain on his list, and all three are in Stromgarde.",sp=1}},faq={{q="Who gives the quest Wand over Fist?",a="At Refuge Pointe in the Arathi Highlands, Skuerto asks you to recover the wand.",al={"wand over fist questgiver","who starts wand over fist","where to get wand over fist"}},{q="Where is Kor'gresh located?",a="Kor'gresh is in Boulderfist Hall, south of Refuge Pointe and then east of Thandol Span.",al={"where is korgresh","korgresh location","find korgresh"}},{q="What item needs to be recovered?",a="Trelane's Wand of Invocation is the first of Trelane's items to be recovered. Kor'gresh has used it to throw blasts of ice at his kin.",al={"what item is kor'gresh holding","what wand","trelane wand"}},{q="What prerequisites are needed for this quest?",a="You reach this work after Worth Its Weight in Gold, the work you did for Apprentice Kryten.",al={"wand over fist pre reqs","prerequisites for wand over fist","previous quest to wand over fist"}}},kw={"arathi highlands","boulderfist hall","korgresh","refuge pointe","skuerto","stromgarde","thandol span","trelane","wand of invocation","wand over fist"},rel={"npc:skuerto","subzone:boulderfist-hall","subzone:refuge-pointe","subzone:thandol-span","zone:arathi"},m={start="Skuerto",["end"]="Skuerto",level="39",faction="Alliance",id=693,ri={"Trelane's Wand of Invocation"}},src={"Wand over Fist (Classic)"}}
E["quest:694"] = {t="quest",n="Trelane's Defenses",z="arathi",s="Ogres now ring the Tower of Arathor, and Skuerto needs its defenses working. An azure agate from the Boulderfist shaman can become a key after Apprentice Kryten at Refuge Pointe enchants it.",h="Ogres now ring the Tower of Arathor, and Skuerto needs its defenses working.",sec={{t="The Tower's Defenses",b="In Stromgarde, ogres ring the Tower of Arathor. Skuerto says you need to activate its defenses to have a chance against them. Only then can you reach the items alive.",sp=0},{t="A Gem for a Key",b="The Boulderfist shaman took certain gems from the tower and have grown fond of them. Skuerto says they will not keep the gems for long. Bring an azure agate to Apprentice Kryten at Refuge Pointe. Kryten knows the spell that will enchant it to work as a key.",sp=0}},faq={{q="Why is an azure agate needed?",a="Skuerto wants the tower's defenses active so you can face the ogres around the Tower of Arathor and reach the items alive. Enchanted, the gem will work as a key.",al={"why azure agate","trelane defenses purpose","why get the gem"}},{q="Where did the azure agates come from?",a="The Boulderfist shaman took the azure agates from the Tower of Arathor and have grown fond of them.",al={"who took the agates","where are the gems from","agate origin"}},{q="Who can enchant the gem?",a="Apprentice Kryten at Refuge Pointe knows the spell to enchant the gem so it works as a key.",al={"who enchants the agate","kryten role","who turns it into a key"}}},kw={"apprentice kryten","azure agate","boulderfist shaman","refuge pointe","skuerto","stromgarde","tower of arathor","trelane's defenses"},rel={"npc:skuerto","quest:695","subzone:tower-of-arathor","subzone:refuge-pointe","zone:arathi","topic:shaman"},m={start="Skuerto",["end"]="Apprentice Kryten",level="39",faction="Alliance",id=694,ri={"Azure Agate"}},src={"Trelane's Defenses (Classic)"}}
E["quest:695"] = {t="quest",n="An Apprentice's Enchantment",z="arathi",s="At the camp, Apprentice Kryten enchants the agate you brought from the Boulderfist shaman. It can wake the tower's defenses, and Kryten sends you to Skuerto before you leave.",h="At the camp, Apprentice Kryten enchants the agate you brought from the Boulderfist shaman.",sec={{t="A Key for the Tower",b="Apprentice Kryten gives you the enchanted gem and explains its power. Touch it to a pedestal at the tower's foot, and its defenses will wake. When you are ready to enter and search for the rest of Trelane's items, use the gem. Kryten will wait for you at the camp. Before you go, speak with Skuerto, who can answer any other questions.",sp=0}},faq={{q="What is the purpose of the enchanted agate?",a="Touch the enchanted agate to a pedestal at the tower's foot, and it wakes the tower's defenses. Use it when you are ready to enter and search for the rest of Trelane's items.",al={"why do i need the agate","enchanted agate use","what does the gem do"}},{q="Who do you need to talk to before leaving camp?",a="Speak to Skuerto before you leave the camp. Kryten says Skuerto can answer any other questions.",al={"who do i talk to","where to go next","who is skuerto"}},{q="Where will Kryten be?",a="Kryten will wait for your return at the camp.",al={"where is kryten","kryten waiting"}}},kw={"apprentice kryten","arathi highlands","enchanted agate","skuerto","tower","trelane"},rel={"npc:skuerto","zone:arathi"},m={start="Apprentice Kryten",["end"]="Skuerto",level="39",faction="Alliance",id=695},src={"An Apprentice's Enchantment"}}
E["quest:696"] = {t="quest",n="Attack on the Tower",z="arathi",s="At Refuge Pointe, Skuerto sends you to search the ogre-held tower for three items tied to Trelane. The phylactery, orb and ember agate should be in chests inside, and Skuerto says Malin will be pleased when you return with them.",h="At Refuge Pointe, Skuerto sends you to search the ogre-held tower for three items tied to Trelane.",sec={{t="Into the Tower",b="After Kryten enchants the gem, Skuerto sends you to find Trelane's phylactery, orb and ember agate. The three items should be in chests inside the tower, ready for you to open. But the ogres are dangerous. The tower's defenses will not deal with them, and the ogres will hurt you if they catch you stealing.",sp=0},{t="Skuerto's Verdict",b="When you return with the three items, Skuerto says Malin could not have asked for a worthier person to help them here. Malin will be delighted to learn their venture has succeeded so completely.",sp=1}},faq={{q="Who assigns this task?",a="Skuerto sends you from Refuge Pointe in the Arathi Highlands after Kryten enchants the gem.",al={"who gives attack on the tower","quest giver attack on the tower","where to get attack on the tower"}},{q="What items are you sent to retrieve?",a="You are sent to retrieve Trelane's phylactery, orb and ember agate. Each should be in a chest inside the tower.",al={"attack on the tower items","what relics to get","trelanes items"}},{q="What will the ogres do?",a="The tower's defenses will not deal with the ogres. If they catch you stealing, they will hurt you.",al={"are the ogres dangerous","tower ogres"}},{q="What comes before this?",a="It follows An Apprentice's Enchantment, where Kryten enchants the gem and sends you to Skuerto.",al={"attack on the tower prerequisite","what quest comes first"}}},kw={"arathi highlands","attack on the tower","malin","ogres","refuge pointe","skuerto","trelane","trelane's ember agate","trelane's orb","trelane's phylactery"},rel={"npc:skuerto","subzone:refuge-pointe","quest:695","zone:arathi"},m={start="Skuerto",["end"]="Skuerto",level="39",faction="Alliance",id=696,ri={"Trelane's Ember Agate","Trelane's Orb","Trelane's Phylactery"}},src={"Attack on the Tower (Classic)"}}
E["quest:697"] = {t="quest",n="Malin's Request",z="arathi",s="In Stormwind, Skuerto's letter carries news from Arathi to Archmage Malin. You are sent to the Mage Quarter with word that Kryten and Skuerto will soon be home.",h="In Stormwind, Skuerto's letter carries news from Arathi to Archmage Malin.",sec={{t="A Letter for the Archmage",b="After your work in Arathi, Skuerto gives you a sealed letter for Archmage Malin in Stormwind's Mage Quarter. It says Kryten and Skuerto will be home soon. Skuerto trusts Malin will repay you well for helping them and wishes you a safe journey.",sp=0},{t="Malin Reads the Letter",b="Archmage Malin opens Skuerto's letter, and his eyes grow wide. Delighted, he says Trelane will be pleased. Malin supposes Kryten and Skuerto share his excitement as they head home to Stormwind.",sp=1}},faq={{q="Who sends you with the letter?",a="Skuerto sends you with a letter for Malin. It says Kryten and Skuerto will be home soon.",al={"who gives the letter","who starts malins request","malins request starter"}},{q="Where is Archmage Malin located?",a="Archmage Malin is in Stormwind's Mage Quarter.",al={"where is archmage malin","archmage malin location","where do i turn this in"}},{q="Who is Kryten?",a="Kryten is Skuerto's companion in the Arathi Highlands. Skuerto says they will be home soon.",al={"who is kryten","kryten arathi"}},{q="What comes before this step?",a="This follows Attack on the Tower, the work Skuerto asked you to do at the tower in Arathi.",al={"previous quest","prereq","what leads to this"}}},kw={"arathi highlands","archmage malin","kryten","mage quarter","malin's request","sealed letter","skuerto","stormwind"},rel={"npc:archmage-malin","npc:skuerto","subzone:mage-quarter","zone:arathi","topic:stormwind-kingdom","topic:mage"},m={start="Skuerto",["end"]="Archmage Malin",level="39",faction="Alliance",id=697},src={"Malin's Request (2)"}}
E["quest:701"] = {t="quest",n="Guile of the Raptor",z="arathi",s="Tor'gan seeks to awaken Gor'mul's dormant warrior spirit through the guile of the raptor. He gathers Highland Fleshstalker hearts to make an enchanted charm and restore Gor'mul's fighting resolve.",h="Tor'gan seeks to awaken Gor'mul's dormant warrior spirit through the guile of the raptor.",sec={{t="Awakening the Dormant Warrior",b="Tor'gan wants to draw Gor'mul out of his listlessness and restore the warrior spirit that lies dormant. He turns to primal magic instead of persuasion, hoping a charm filled with wild predators' essence will stir Gor'mul to action. Through the charm, he seeks to renew Gor'mul's martial resolve and show him the strength of this power.",sp=0},{t="The Heart of the Predator",b="Tor'gan needs Highland Fleshstalker hearts to call on the instincts of a cunning hunter. In shamanic and primal traditions, a predator's heart carries its ferocity and guile. Tor'gan uses these trophies to make a physical token and weave a spell. He hopes they will give Gor'mul a predator's cunning and help him rediscover his calling.",sp=0}},faq={{q="Who is Tor'gan?",a="Tor'gan is a spiritual figure who seeks to help Gor'mul. He believes Gor'mul has lost touch with his inner strength, so he gathers reagents for an item infused with beast magic to rouse him.",al={"who is tor'gan","torgan","quest giver"}},{q="Who is Gor'mul?",a="Gor'mul has lost his fighting spirit, and the warrior within him lies dormant. Tor'gan means to infuse him with primal predator essence, so Gor'mul can witness new power and rise to fight again.",al={"who is gormul","why help gormul","dormant warrior"}},{q="Why does Tor'gan need raptor hearts?",a="Tor'gan needs twelve raptor hearts to make a physical talisman and weave the enchantment meant to infuse Gor'mul. Primal magic draws on predators' hearts to channel their instincts, guile, and power.",al={"why raptor hearts","what are hearts for","raptor magic"}},{q="Where do the raptor hearts come from?",a="The hearts come from Highland Fleshstalkers, predatory raptors known for relentless hunting and cunning. Tor'gan believes their hearts can fuel the spell that will awaken Gor'mul.",al={"where to get hearts","which raptors","highland fleshstalkers"}},{q="What does the guile of the raptor signify?",a="The guile of the raptor means a predator's cunning, swift reflexes, and lethal instinct. Tor'gan believes this nature can break through Gor'mul's lethargy and revive his combat instincts.",al={"what is guile of the raptor","what power","raptor guile meaning"}},{q="What is the ultimate goal of the ritual?",a="Tor'gan uses the gathered hearts to make an item and weave a spell. He hopes to show Gor'mul new power and awaken his dormant warrior identity, so Gor'mul can reclaim his path.",al={"is gormul cured","what happens after ritual","does it work"}}},ang={["class:Warrior"]="As a warrior, you know Tor'gan hopes to rouse Gor'mul's dormant warrior spirit with raptors' cunning and ferocity.",["faction:Horde"]="As a member of the Horde, you see a tradition of drawing on primal beasts and natural spirits to restore purpose to a listless or troubled comrade."},kw={"dormant warrior","gor'mul","guile of the raptor","highland fleshstalkers","raptor hearts","tor'gan","warrior"},rel={"topic:warrior"},m={faction="Horde",id=701},src={"In-game quest text: Guile of the Raptor"},fv=true}
E["quest:702"] = {t="quest",n="Guile of the Raptor",z="arathi",s="At Hammerfall, Tor'gan sends you to Gor'mul with an orb to rouse the warrior's spirit. Its energy bears the raptor's essence and may give Gor'mul fresh purpose.",h="At Hammerfall, Tor'gan sends you to Gor'mul with an orb to rouse the warrior's spirit.",sec={{t="Tor'gan's Orb",b="Tor'gan gives you an orb meant to fill Gor'mul with the raptor's essence. He hopes it will rouse the warrior's spirit and set him on a fresh course in life.\n\nOnce Gor'mul is himself again, Tor'gan plans to explain the Horde's present state. He hopes to win the help of a great warrior in its unceasing battles.",sp=0},{t="Gor'mul's Bitterness",b="Gor'mul greets your return with bitterness. He says all he wants is more of Tor'gan's pity, then mocks you with talk of brightly colored string.",sp=0},{t="A Strange Power",b="The orb draws Gor'mul's interest. He remarks on the strange power it gives off.",sp=1},{t="The Raptor Within",b="As Gor'mul takes the orb, his blood stirs and the raptor's guile slips through him. He wonders aloud if this is the shamanism Tor'gan spoke of. Then he declares himself renewed, with his strength returning.",sp=1}},faq={{q="Who is Gor'mul?",a="At Hammerfall, Gor'mul is a despondent warrior. Tor'gan hopes to lift his spirits and set him on a new course, so the Horde can gain the aid of a great warrior.",al={"who is gormul","gormul lore","what is wrong with gormul"}},{q="What is the purpose of Tor'gan's Orb?",a="Tor'gan's Orb bears energy meant to fill Gor'mul with the raptor's essence. It may rouse his spirit and give him fresh purpose.",al={"what does the orb do","torgan orb purpose","guile orb"}},{q="What came before this step?",a="An earlier Guile of the Raptor comes first. This step builds on what happened there.",al={"previous quest","prereq"}}},kw={"arathi highlands","gor'mul","hammerfall","raptor essence","tor'gan","torgan's orb"},rel={"subzone:hammerfall","quest:701","zone:arathi","topic:horde","topic:warrior"},m={start="Tor'gan",["end"]="Gor'mul",level="37",faction="Horde",id=702},src={"Guile of the Raptor (2)"}}
E["quest:79358"] = {t="quest",n="Storm, Earth, and Fire",z="arathi",s="Veyric Thunderhame asks you to gather twisted elemental totems in Arathi Highlands. He hopes to learn how other peoples practice shamanism and find a way to counter the quilboar's elemental working.",h="Veyric Thunderhame asks you to gather twisted elemental totems in Arathi Highlands.",sec={{t="A Counter-Ritual",b="Veyric Thunderhame in Arathi Highlands needs your help after the quilboar flooded Thousand Needles. He says their use of the elements has stirred outrage, and a counter-ritual will require better knowledge of these twisted forces. A book describes how Azeroth's many peoples practice shamanism. Veyric asks you to bring him twisted fire, earth, air, and water totems so he can learn from them.",sp=0}},faq={{q="Who is asking for the totems?",a="Veyric Thunderhame in Arathi Highlands asks you to collect twisted fire, earth, air, and water totems.",al={"who wants the totems","veyric's request"}},{q="Why does Veyric need the totems?",a="Veyric wants to understand the twisted elements as he works toward a counter-ritual against the quilboar's elemental working.",al={"why totems","what are they for"}},{q="What happened in Thousand Needles?",a="The quilboar flooded Thousand Needles, and Veyric says their use of the elements has stirred outrage.",al={"thousand needles flood","what did the quilboar do"}},{q="What does the book describe?",a="The book describes the many peoples of Azeroth and how they practice shamanism.",al={"shamanism book","what's in the book"}},{q="Which totems does Veyric ask for?",a="He asks for twisted fire, earth, air, and water totems.",al={"totem types","fire earth air water"}}},ang={["class:Shaman"]="As a shaman, you are asked to help Veyric learn how peoples across Azeroth practice shamanism and understand the twisted elements."},kw={"arathi highlands","counter-ritual","quilboar","shamanism","storm earth and fire","thousand needles","twisted totems","veyric thunderhame"},rel={"zone:thousandneedles","zone:arathi","topic:quilboar"},m={faction="Alliance",id=79358},src={"In-game quest text: Storm, Earth, and Fire"},fv=true}
E["quest:79624"] = {t="quest",n="Anyone Can Cook",z="arathi",s="An illegible recipe appears to describe a meat dish, and you suspect ogre writing. Find an ogre who can read it.",h="An illegible recipe appears to describe a meat dish, and you suspect ogre writing.",sec={{t="A Strange Recipe",b="The recipe is written in a language you cannot read, and its subject seems to be a meat dish. Ogre is your best guess, given where it came from and what it describes. You hope to find an ogre who can translate it.",sp=0}},faq={{q="What is the recipe for?",a="It appears to be for some sort of meat dish.",al={"recipe purpose","what dish","meat recipe"}},{q="What language is the recipe written in?",a="You do not understand the language. Ogre is your best guess.",al={"recipe language","what writing","can't read recipe"}},{q="Who can read the recipe?",a="You are looking for an ogre who can read it.",al={"translate recipe","who can read it","ogre reader"}},{q="Who is Skonk?",a="Skonk is an ogre who is listening for the recipe.",al={"Skonk","who skonk","ogre Skonk"}}},ang={["profession:Cooking"]="As a cook, you have a reason to wonder what sort of meat dish the illegible recipe describes."},kw={"anyone can cook","illegible recipe","meat dish","ogre","recipe","skonk","translation"},m={id=79624},src={"In-game quest text: Anyone Can Cook"},fv=true}
E["quest:79677"] = {t="quest",n="A Quick Grocery Run",z="arathi",s="Skonk asks you to gather ingredients for a dish in Arathi Highlands. He learned to cook after other ogres mocked his size and fighting ability.",h="Skonk asks you to gather ingredients for a dish in Arathi Highlands.",sec={{t="Skonk's Ingredients",b="Skonk, an ogre in Arathi Highlands, needs ingredients for a dish he knows how to make. Other ogres laughed at his size and called him weak, so he turned to cooking. You gather the ingredients and bring them to him.",sp=0}},faq={{q="Who is Skonk?",a="Skonk is an ogre who learned to cook after other ogres mocked his size and fighting ability.",al={"skonk","who's skonk"}},{q="Why does Skonk cook?",a="Other ogres laughed at Skonk for being smaller and called him weak, so he learned to cook instead of fight.",al={"why cook","skonk cooking"}},{q="What does Skonk need?",a="Skonk needs ingredients for a dish he can make.",al={"ingredients","what ingredients"}},{q="Where do I bring the ingredients?",a="Bring the ingredients to Skonk in Arathi Highlands.",al={"where skonk","bring ingredients"}}},ang={["profession:Cooking"]="As a cook, you can help Skonk gather ingredients for a dish he knows how to make."},kw={"arathi highlands","cooking","dish","ingredients","ogre","skonk","teasing"},rel={"zone:arathi"},m={id=79677},src={"In-game quest text: A Quick Grocery Run"},fv=true}
E["quest:79678"] = {t="quest",n="Taste Testing",z="arathi",s="Skonk invites you to taste a new dish made over a hot fire. The tasting is his way of sharing with a new friend who has helped him.",h="Skonk invites you to taste a new dish made over a hot fire.",sec={{t="A New Dish",b="Skonk has a new dish ready over the fire, and he wants to share it with you. After the favors you have done for him, he thinks you should get to try it too. The recipe is ready for tasting.",sp=0}},faq={{q="Who is Skonk?",a="Skonk is making a new dish and invites you to taste it.",al={"skonk","who's skonk"}},{q="What does Skonk want me to do?",a="Skonk wants you to taste the recipe with him.",al={"taste test","what does skonk want"}},{q="Why is Skonk sharing the dish?",a="Skonk says you have done him many favors, so he wants you to try his new dish.",al={"why food","why share"}},{q="What does Skonk think of the recipe?",a="After the tasting, Skonk says the recipe is delicious.",al={"is it good","recipe taste"}}},kw={"dish","fire","food","recipe","skonk","taste testing","tasting"},m={id=79678},src={"In-game quest text: Taste Testing"},fv=true}
E["quest:79976"] = {t="quest",n="This Must Be The Place",z="arathi",s="At This Must Be The Place, a camper has vanished moments before anyone could catch up. A torn note says the writer has taken their work underground to keep it from the wrong hands.",h="At This Must Be The Place, a camper has vanished moments before anyone could catch up.",sec={{t="A Hasty Departure",b="Someone broke camp at this secluded spot only moments ago. An inadequately secured sleeping bag unrolls underfoot, while heavy canvas lies bundled over assorted gear. A small scrap of paper holds a hurried parting message, but whoever camped here has vanished before anyone could catch up.",sp=0},{t="Into the Underground",b="The torn note says its author has taken their work underground to keep it from the wrong hands. Whether these are final words or a clue to the researcher's next hidden shelter remains unknown. The equipment lies abandoned for whoever found the campsite.",sp=1}},faq={{q="Who wrote the torn note?",a="The note does not name its author. The writer says only that they have taken their work underground to keep it from the wrong hands, leaving the campsite and equipment behind.",al={"who wrote the note","note author","who left the message"}},{q="What work is being taken underground?",a="The note does not reveal what work the author is taking underground. The writer says they want to keep it safe from unspecified adversaries.",al={"what underground work","why take work underground","what work"}},{q="Where did the campsite's occupant go?",a="The occupant left moments before anyone arrived, and their destination is unknown. The note hints they may have gone to another hidden shelter.",al={"did i miss them","where did they go","where is the author"}},{q="What was left behind at the campsite?",a="The traveler left an inadequately secured sleeping bag that unrolls on the ground, heavy canvas bundled over assorted gear, and a discarded pack containing miscellaneous gear.",al={"what is left behind","supplies at camp","what was in the pack"}},{q="Is this a clue leading to another hideout?",a="The note could be a farewell or a clue to the author's next underground shelter. It does not settle which.",al={"is there another hideout","next camp","more clues"}},{q="Who are the 'wrong hands' mentioned in the note?",a="The note does not identify the wrong hands. The author feared pursuit or theft and left before their work could be compromised.",al={"who are the wrong hands","wrong hands meaning","who is chasing the author"}}},kw={"abandoned camp","equipment pack","hideout","sleeping bag","this must be the place","torn note","underground"},m={id=79976},src={"In-game quest text: This Must Be The Place"},fv=true}
E["quest:8393"] = {t="quest",n="Claiming Arathi Basin",z="arathi",s="An Alliance Brigadier General outside Arathi Basin asks you to bring three Arathi Basin Marks of Honor. The marks are the only thing named in this request.",h="An Alliance Brigadier General outside Arathi Basin asks you to bring three Arathi Basin Marks of Honor.",sec={},faq={{q="What does the Brigadier General ask for?",a="The Alliance Brigadier General asks you to bring three Arathi Basin Marks of Honor.",al={"arathi marks","three marks","what do I bring"}},{q="Where do I bring the marks?",a="Bring the marks to an Alliance Brigadier General outside the battlegrounds.",al={"where turn in","brigadier location","where deliver marks"}},{q="Who is asking for the marks?",a="An Alliance Brigadier General outside the battlegrounds asks for the marks.",al={"who wants them","arathi general","who gives this"}}},ang={["faction:Alliance"]="As an Alliance member, you are asked to bring three Arathi Basin Marks of Honor to an Alliance Brigadier General."},kw={"alliance","arathi basin","brigadier general","claiming arathi basin","marks of honor"},rel={"zone:arathibasin","topic:alliance"},m={faction="Alliance",id=8393},src={"In-game quest text: Claiming Arathi Basin"},fv=true}
E["quest:8400"] = {t="quest",n="Fight for Warsong Gulch",z="arathi",s="The Alliance seeks proof of your valor on the front lines in Warsong Gulch. An Alliance Brigadier General stationed outside the battlegrounds calls for three Marks of Honor earned against the Horde.",h="The Alliance seeks proof of your valor on the front lines in Warsong Gulch.",sec={{t="The General's Call",b="An Alliance Brigadier General stationed near the field of battle calls on soldiers returning from the front. If you have fought in Warsong Gulch, three Marks of Honor prove your standing and your deeds against the Horde. Bearing these tokens back to high command shows that the Alliance holds its ground in the disputed canyon.",sp=0}},faq={{q="Who takes the Warsong Gulch Marks of Honor?",a="An Alliance Brigadier General stationed outside the battleground gathers the marks to track the war effort.",al={"who wants marks of honor","brigadier general marks"}},{q="How many marks do you need to bring?",a="Three Warsong Gulch Marks of Honor are needed to prove your deeds on the battlefield.",al={"how many marks wsg","marks needed warsong"}},{q="Where is the Alliance Brigadier General?",a="The Brigadier General waits outside the battlegrounds where the Alliance coordinates its troops.",al={"where is brigadier general","alliance general location"}}},ang={["faction:Alliance"]="As an Alliance soldier, bringing your battle marks to the Brigadier General proves your service in the ongoing struggle against the Horde in Warsong Gulch."},kw={"alliance","ashenvale","battlegrounds","brigadier general","marks of honor","warsong gulch"},rel={"zone:warsonggulch","topic:alliance"},m={faction="Alliance",id=8400},src={"In-game quest text: Fight for Warsong Gulch"},fv=true}
E["quest:847"] = {t="quest",n="Guile of the Raptor",z="arathi",s="Tor'gan's orb has filled Gor'mul with a raptor's essence. The power makes him wonder about shaman magic, and he will hear Tor'gan out for now.",h="Tor'gan's orb has filled Gor'mul with a raptor's essence.",sec={{t="A Warrior Convinced",b="Power runs through Gor'mul, and he wonders if it is the shamans' power Tor'gan tried to show him. The thought interests him. So he asks you to tell Tor'gan he is convinced for now and will hear what Tor'gan has to say.",sp=0},{t="Tor'gan's Reply",b="Tor'gan will speak with Gor'mul once the enchantment wears off. He thanks you for helping bring Gor'mul back among the living. Gor'mul is grateful too, Tor'gan believes.",sp=1}},faq={{q="Who sends you to speak with Tor'gan?",a="Gor'mul sends you to speak with Tor'gan. After feeling the orb's power, he asks you to say he is convinced for now.",al={"who starts guile of the raptor 3","who gives this quest","where does this start"}},{q="Why does Gor'mul change his mind about Tor'gan?",a="Gor'mul wonders whether the power he felt came from the shamans, as Tor'gan tried to show him. The thought interests him, so he is convinced for now and will listen to Tor'gan.",al={"why did gormul change his mind","gormul shaman magic","is gormul convinced"}},{q="What came before this step?",a="You brought Tor'gan's orb to Gor'mul in the earlier step.",al={"previous quest","prereq guile of the raptor"}}},kw={"arathi highlands","gor'mul","guile of the raptor","hammerfall","shaman","tor'gan"},rel={"subzone:hammerfall","topic:shaman","zone:arathi"},m={start="Gor'mul",["end"]="Tor'gan",level="37",faction="Horde",id=847},src={"Guile of the Raptor (3)"}}
E["quest:92519"] = {t="quest",n="Ward Restocking",z="arathi",s="At Hammerfall, Doctor Gregory Victor is short of remedies, antidotes, and elixirs for the infirmary. The missing tonics are at Go'Shek Farm.",h="At Hammerfall, Doctor Gregory Victor is short of remedies, antidotes, and elixirs for the infirmary.",sec={{t="A Shortage in the Ward",b="Doctor Gregory Victor tends Hammerfall’s wounded and ailing in the medical ward. The nearby Forsaken apothecary usually supplies the infirmary with remedies, antidotes, and elixirs. When those deliveries stop, Victor turns to capable travelers to keep the clinic stocked.",sp=0},{t="The Recluse of Go'Shek Farm",b="Apothecary Jorell works in a cramped shack at Go'Shek Farm, south and west of Hammerfall. Doctor Victor says Jorell is often absent. The eccentric Forsaken chemist may neglect his duties or succumb to his own noxious concoctions. Couriers sent for the packaged tonics should find the medicine waiting, whether Jorell is there or not.",sp=0}},faq={{q="Who offers the quest Ward Restocking?",a="Doctor Gregory Victor oversees Hammerfall’s medical ward and infirmary. When regular deliveries fail, he asks dependable travelers to retrieve supplies.",al={"who gives ward restocking","quest giver ward restocking","doctor gregory victor quest"}},{q="Where is Apothecary Jorell located?",a="Apothecary Jorell works from a small shack at Go'Shek Farm, south and slightly west of Hammerfall along the road in the Arathi Highlands.",al={"where is apothecary jorell","jorell lab location","where to find tonics"}},{q="Why does Doctor Gregory Victor send you to Go'Shek Farm?",a="Doctor Gregory Victor sends you to Go'Shek Farm because Apothecary Jorell failed to deliver an urgently needed crate of antidotes and elixirs to the Hammerfall infirmary.",al={"why go to goshek farm","what is at goshek farm"}},{q="What supplies are needed for the ward?",a="The ward needs a case of Packaged Tonics containing Apothecary Jorell’s antidotes and elixirs. They will replenish the Hammerfall medical ward’s dwindling stocks.",al={"what are packaged tonics","what items do you pick up"}},{q="Why hasn't Apothecary Jorell delivered the supplies himself?",a="Doctor Gregory Victor suspects Jorell either poisoned himself again while brewing concoctions in his poorly ventilated shack or neglected his duties to the ward.",al={"what happened to jorell","is jorell dead","why didn't jorell deliver"}},{q="Where must the supplies be delivered?",a="Bring the case of tonics from Go'Shek Farm to Doctor Gregory Victor at the medical ward in Hammerfall.",al={"where do tonics go","who to turn in ward restocking"}}},ang={["faction:Horde"]="As a member of the Horde, you know Hammerfall needs steady shipments of tonics and medicine. They help keep its soldiers, defenders, and travelers standing against threats in the Arathi Highlands.",["race:Undead"]="As an Undead, you know Apothecary Jorell carries the Royal Apothecary Society’s presence into Arathi. His erratic behavior and toxic experiments at Go'Shek Farm frustrate even his allies."},kw={"apothecary jorell","arathi highlands","doctor gregory victor","go'shek farm","hammerfall","packaged tonics","ward restocking"},rel={"subzone:hammerfall","subzone:go-shek-farm","npc:doctor-gregory-victor"},m={faction="Horde",id=92519},src={"In-game quest text: Ward Restocking"},fv=true}
E["quest:92707"] = {t="quest",n="The Giant in the Den",z="arathi",s="You carry the colossal wristguards wrenched from the corpse of a fallen goliath. Drum Fel at Hammerfall must see the size of the brutes prowling the wilds to prepare his soldiers for the danger ahead.",h="You carry the colossal wristguards wrenched from the corpse of a fallen goliath.",sec={{t="Trophy of the Wilds",b="You carry the enormous wristguards of a fallen goliath, wrenched straight from the brute's remains. They are wide enough that your entire arm fits through without touching metal. Drum Fel watches over Hammerfall and cannot afford blind spots, so proof of such hulking enemies belongs before him.",sp=0},{t="Words from Hammerfall",b="Drum Fel is neither shocked nor shaken by the immense wristguards. The outpost has clashed with Witherbark goliaths before and expects to trade blows with them again. Even so, he commends your instinct to bring word of the threat straight to Hammerfall's defenders.",sp=1}},faq={{q="Who is Drum Fel?",a="Drum Fel is an orc officer stationed at the Horde outpost of Hammerfall, watchful of all threats lurking across the surrounding lands.",al={"who is drum fel","drum fel hammerfall"}},{q="What is a Witherbark goliath?",a="They are hulking brutes fighting for the Witherbark troll tribe, so massive that a grown traveler can slip an entire arm through one of their wristguards.",al={"what are goliaths","witherbark trolls goliath"}},{q="Why must the wristguards go to Hammerfall?",a="Drum Fel must stay informed of every danger prowling the highlands, and the wristguards warn the outpost of the sheer size of the brutes out in the wilds.",al={"why hammerfall","take bracers to hammerfall"}}},ang={["faction:Horde"]="As a warrior of the Horde, carrying proof of slain monsters to Drum Fel in Hammerfall shows you share his watchful eye over the highlands."},kw={"bracers","drum fel","goliath","hammerfall","witherbark","wristguards"},rel={"npc:drum-fel","subzone:hammerfall"},m={faction="Horde",id=92707},src={"In-game quest text: The Giant in the Den"},fv=true}
E["quest:92867"] = {t="quest",n="Ground to Keep",z="arathi",s="Groundskeeper Lomar asks you to drive intruders from Stromgarde Keep. The kingdom’s remaining sculptures and sacred burial grounds need protection.",h="Groundskeeper Lomar asks you to drive intruders from Stromgarde Keep.",sec={{t="A Kingdom's Remains",b="In Stromgarde Keep, Groundskeeper Lomar asks you to drive back the Boulderfist, Syndicate, and Witherbark intruders. He says Stromgarde has more in reserve, and that it must stay hidden for its own protection. Support is growing for preserving the kingdom’s remaining sculptures and sacred burial grounds.",sp=0}},faq={{q="Who is asking for help?",a="Groundskeeper Lomar asks you to drive the Boulderfist, Syndicate, and Witherbark intruders from Stromgarde Keep.",al={"who wants help","groundskeeper lomar","who gave this"}},{q="Why should Stromgarde’s remains be protected?",a="Support is growing for preserving Stromgarde’s remaining sculptures and sacred burial grounds.",al={"why protect stromgarde","what needs protecting","keep the sculptures safe"}},{q="Which intruders are in Stromgarde Keep?",a="The Boulderfist, Syndicate, and Witherbark have taken up residence in Stromgarde Keep.",al={"who's in the keep","enemies in stromgarde","boulderfist syndicate witherbark"}},{q="What must remain hidden?",a="Lomar says Stromgarde has more in reserve, and it must remain hidden for its own protection.",al={"what is hidden","stromgarde reserves","what must stay secret"}}},kw={"boulderfist","burial grounds","ground to keep","groundskeeper lomar","sculptures","stromgarde","stromgarde keep","syndicate","witherbark"},rel={"subzone:stromgarde-keep","topic:syndicate"},m={faction="Alliance",id=92867},src={"In-game quest text: Ground to Keep"},fv=true}
E["quest:92872"] = {t="quest",n="Dutiful Steps",z="arathi",s="Caretaker Alaric asks you to carry tomb dust from the Stromgarde Keep crypt to the sea. The rite renews a cycle of remembrance for the fallen.",h="Caretaker Alaric asks you to carry tomb dust from the Stromgarde Keep crypt to the sea.",sec={{t="Toward the Sea",b="Your way back to the sunlit world begins with a small satchel. Caretaker Alaric asks you to take it to the cliffs behind Stromgarde Keep and cast its contents into the Great Sea. The dust comes from the tomb below the keep, where its guardians preserve ceremonial rites for honoring the fallen. Each season, some is spread across Azeroth’s oceans as a symbolic renewal.",sp=0}},faq={{q="Who is asking me to carry the dust?",a="Caretaker Alaric asks you to carry the tomb dust from the Stromgarde Keep crypt to the sea.",al={"who gave me this","Alaric's request"}},{q="What is in the satchel?",a="The satchel holds dust from the tomb beneath Stromgarde Keep.",al={"what's in the pouch","tomb dust"}},{q="Why is the tomb dust spread across the sea?",a="Each season, some tomb dust is spread across Azeroth’s oceans as a symbolic act of renewing cycles.",al={"why throw dust in the ocean","what's the dust for"}},{q="Where am I meant to cast the satchel?",a="Caretaker Alaric asks you to cast the tomb dust into the Great Sea from the cliffs behind Stromgarde Keep.",al={"where to throw it","cliffs behind Stromgarde"}},{q="What do the tomb’s guardians preserve?",a="The tomb’s guardians preserve knowledge of ceremonial rites used to honor the fallen.",al={"what's in the tomb","ceremonial rites"}}},kw={"caretaker alaric","ceremonial rites","crypt","dutiful steps","fallen","great sea","pouch of tomb dust","stromgarde keep","tomb dust"},rel={"subzone:crypt-stromgarde-keep","subzone:stromgarde-keep"},m={faction="Alliance",id=92872},src={"In-game quest text: Dutiful Steps"},fv=true}
E["quest:95143"] = {t="quest",n="Finding Tan'jani",z="arathi",s="A traveler asks you to find their brother Tan'jani. Messages place him south of Loch Modan, with the latest pointing toward Rog'mar in Riverglades.",h="A traveler asks you to find their brother Tan'jani.",sec={{t="A Brother Missing",b="A traveler's brother, Tan'jani, has gone searching for something unknown. One message places him somewhere south of Loch Modan. A bloodstained letter mentions Riverglades and Rog'mar farther south, and the traveler asks you to find him there.",sp=0}},faq={{q="Who is Tan'jani?",a="Tan'jani is the brother of the traveler asking you to find him.",al={"tan'jani","tan jani","missing brother"}},{q="Where was Tan'jani last mentioned?",a="A bloodstained letter mentions Riverglades and Rog'mar, farther south than Loch Modan.",al={"where is tan'jani","tan'jani location","rog'mar"}},{q="What was Tan'jani searching for?",a="Tan'jani was always searching for something, but his brother does not know what.",al={"what was he looking for","tan'jani searching","why did he leave"}},{q="What do the messages say?",a="One traveler reported meeting Tan'jani somewhere south of Loch Modan. A bloodstained letter mentions Riverglades and Rog'mar, but most of it cannot be read.",al={"tan'jani messages","bloodstained letter","what happened to the letter"}}},kw={"bloodstained letter","loch modan","missing brother","riverglades","rog'mar","tan jani","tan'jani"},rel={"zone:riverglades","zone:lochmodan"},m={faction="Horde",id=95143},src={"In-game quest text: Finding Tan'jani"},fv=true}
E["quest:95315"] = {t="quest",n="The Riverglades Report",z="arathi",s="Captain Nials sends you south with correspondence for Demar Brant at Farholde Keep. A scout reports an enemy force gathering beyond the Wetlands, near a settlement called Farholde.",h="Captain Nials sends you south with correspondence for Demar Brant at Farholde Keep.",sec={{t="A Scout’s Word",b="Captain Nials has heard that a large enemy force is gathering far south of the Wetlands. A settlement called Farholde may lie there, though its name is only familiar to him. He gives you correspondence for Demar Brant, who leads the detachment at Farholde Keep on the Riverglades’ southeastern coast.",sp=0}},faq={{q="What did the scout report?",a="The scout reported a large enemy force gathering far south, beyond the Wetlands.",al={"scout report","what's happening south"}},{q="Who is Captain Nials sending me to?",a="You are to deliver Captain Nials’ correspondence to Demar Brant at Farholde Keep.",al={"who gets the letter","demar brant"}},{q="Where is Farholde Keep?",a="Farholde Keep lies along the southeastern coast of the Riverglades.",al={"where's farholde","keep location"}},{q="What is Farholde?",a="Captain Nials has heard of a settlement called Farholde near the gathering force.",al={"farholde settlement","what's farholde"}}},kw={"captain nials","correspondence","demar brant","farholde","farholde keep","riverglades report","scout","wetlands"},rel={"zone:riverglades","zone:wetlands","topic:alliance"},m={faction="Alliance",id=95315},src={"In-game quest text: The Riverglades Report"},fv=true}
E["quest:95663"] = {t="quest",n="Dragonmaw Rumors",z="arathi",s="The Deathstalkers seek clearer word about Dragonmaw magic rumored in the Wetlands. You are sent to meet their agent in the hills above the clan's camp.",h="The Deathstalkers seek clearer word about Dragonmaw magic rumored in the Wetlands.",sec={{t="Whispers in the Wetlands",b="A Deathstalker in the Wetlands needs your help as rumors gather around the Dragonmaw clan. They are said to command magic that binds dragons, and whispers claim they prepare a display of that power. Broken symbols offered no firm proof, so you are sent to meet an agent in the hills above their camp.",sp=0}},faq={{q="What are the Dragonmaw rumored to be doing?",a="The rumor says the Dragonmaw are preparing a display of magic strong enough to make dragons serve.",al={"dragonmaw rumors","what are dragonmaw planning","dragonmaw magic"}},{q="Why do the Deathstalkers need help?",a="The Deathstalkers have only broken symbols and uncertain whispers about the Dragonmaw, so an agent needs assistance in the hills above the clan's camp.",al={"deathstalker needs help","why help deathstalkers","what do they need"}},{q="Where is the Deathstalker agent?",a="The agent is in the hills above the Dragonmaw camp in the Wetlands.",al={"agent location","where meet agent","deathstalker agent hills"}},{q="What did the broken symbols reveal?",a="The broken symbols carried only uncertain whispers about a rumored Dragonmaw display of magic.",al={"broken symbols","what symbols showed","symbols dragonmaw"}},{q="What happens when you meet the agent?",a="The Deathstalker agent will reveal the next steps when you meet her in the hills above the Dragonmaw camp.",al={"meet the agent","next steps","what does agent say"}}},kw={"broken symbols","deathstalker agent","deathstalkers","dragonbinding","dragonmaw","dragonmaw camp","dragonmaw rumors","wetlands"},rel={"quest:1886","quest:92472","zone:wetlands"},m={faction="Horde",id=95663},src={"In-game quest text: Dragonmaw Rumors"},fv=true}
E["quest:96016"] = {t="quest",n="The Tempest's Weapons",z="arathi",s="You hold the Eye of the Tempest, drawn from a trial against the primal elements. Now you bring the potent relic into the Alterac Mountains to find Bath'rah the Windwatcher.",h="You hold the Eye of the Tempest, drawn from a trial against the primal elements.",sec={{t="A Relic for the Windwatcher",b="A fierce clash against the elements leaves you holding the Eye of the Tempest. The storm has settled, and Bath'rah the Windwatcher awaits you among the heights of the Alterac Mountains. The hermit knows the ways of such forces and watches for what you bring.",sp=0},{t="Craft of the Storm",b="Bath'rah recognizes the Eye as an artifact of deep and ancient strength. It has been a long time since the Windwatcher worked such power into shape. He bids you guard what cost so much to claim.",sp=1}},faq={{q="Who is Bath'rah the Windwatcher?",a="Bath'rah is a troll hermit and craftsman living in the Alterac Mountains who works with elemental forces.",al={"bath'rah windwatcher","who is bathrah","bath'rah location"}},{q="Where do I deliver the Eye of the Tempest?",a="The Eye of the Tempest must be brought to Bath'rah the Windwatcher in the Alterac Mountains.",al={"eye of the tempest turn in","eye of the tempest deliver","where to bring eye of the tempest"}},{q="What is the Eye of the Tempest?",a="The Eye of the Tempest is a powerful elemental artifact won through battle against the elements.",al={"eye of the tempest lore","what does eye of the tempest do","eye of the tempest"}}},kw={"alterac mountains","bath'rah","elements","eye of the tempest","tempest","windwatcher"},rel={"npc:bath-rah-the-windwatcher","zone:alterac","quest:1791"},m={faction="Alliance",id=96016},src={"In-game quest text: The Tempest's Weapons"},fv=true}
E["quest:96135"] = {t="quest",n="Heed My Call",z="arathi",s="A shaman calls you to the steam pools of Thousand Needles, where corrupted totems can draw out the quilboar’s elementals. The Razormane will resist your interference.",h="A shaman calls you to the steam pools of Thousand Needles, where corrupted totems can draw out the quilboar’s...",sec={{t="At the Steam Pools",b="The steam pools hold fire, earth, water, and air, making them a fitting place for the defenses. A shaman asks you to set twisted totems there and prepare for the Razormane to resist. The corruption around the totems is meant to summon the quilboar’s elementals.",sp=0},{t="The Elements Answer",b="The shaman asks whether the quilboar ritual has ended. When the storm within you disperses, the breeze carries word of victory, and the elements have granted you their respect.",sp=1}},faq={{q="Why use the steam pools?",a="The pools hold fire, earth, water, and air, so the shaman considers them suitable for defenses.",al={"steam pools why","why this spot"}},{q="What are the twisted totems for?",a="Their corruption is meant to summon the quilboar’s elementals.",al={"totems purpose","twisted totems"}},{q="Who is resisting the totems?",a="The Razormane quilboar are expected to resist your interference.",al={"razormane mad","who will fight"}},{q="What does the shaman ask me to do?",a="The shaman asks you to place twisted totems at the Thousand Needles steam pools and put an end to the quilboar ritual.",al={"what do I do","totem task"}}},kw={"elementals","heed my call","quilboar","razormane","shaman","steam pools","totems","twisted totems"},rel={"zone:thousandneedles","topic:quilboar"},m={faction="Alliance",id=96135},src={"In-game quest text: Heed My Call"},fv=true}
E["quest:96784"] = {t="quest",n="Master of Disguise",z="arathi",s="Myrokos sends you to Stromgarde Keep to learn about a secret Syndicate deal. A disguise may let you speak with the Syndicate members there.",h="Myrokos sends you to Stromgarde Keep to learn about a secret Syndicate deal.",sec={{t="A Secret Deal",b="Myrokos wants you to learn who among the Syndicate knows of an important deal at Stromgarde Keep. Disguised as one of their members, you can speak with them somewhat freely. The deal remains secret, and Myrokos needs someone inside the keep to uncover what is known.",sp=0}},faq={{q="What does Myrokos want me to find out?",a="Myrokos wants you to find someone in Stromgarde Keep who knows about an important secret deal involving the Syndicate.",al={"myrokos deal","what deal","syndicate deal"}},{q="Why am I wearing a disguise?",a="Your disguise lets you speak with Syndicate members somewhat freely inside Stromgarde Keep.",al={"why disguise","syndicate disguise","disguise quest"}},{q="Where do I look for someone who knows about the deal?",a="You are looking for someone inside Stromgarde Keep who knows about the Syndicate's secret deal.",al={"where deal","stromgarde keep","find syndicate member"}},{q="Who is Anastasia?",a="Anastasia is the one who responds with suspicion when you mention the deal.",al={"anastasia","anastasia deal","who asks about deal"}}},kw={"anastasia","disguise","master of disguise","myrokos","secret deal","stromgarde keep","syndicate"},rel={"subzone:stromgarde-keep","topic:syndicate"},m={id=96784},src={"In-game quest text: Master of Disguise"},fv=true}
E["quest:96785"] = {t="quest",n="Ain't No Telling",z="arathi",s="Anastasia at Stromgarde Keep will not discuss her superiors’ secret deal without a reason. You need something valuable enough to make her talk.",h="Anastasia at Stromgarde Keep will not discuss her superiors’ secret deal without a reason.",sec={{t="A Reason to Talk",b="At Stromgarde Keep, Anastasia refuses to share what her superiors are doing with a newcomer. She asks for something important or valuable before she will speak. You need to find something in the keep that convinces her to give details about the secret deal.",sp=0},{t="The Bargain",b="Anastasia reacts when you show her what you found. She agrees to tell you about the deal if you give it back to her.",sp=1}},faq={{q="Who is Anastasia?",a="Anastasia is the person who can give you details about her superiors’ secret deal.",al={"anastasia","who's anastasia","anastasia deal"}},{q="Why won't Anastasia talk?",a="Anastasia says she will not share her superiors’ dealings without a good reason.",al={"why won't she talk","anastasia won't tell","why so secretive"}},{q="What does Anastasia want?",a="Anastasia asks for something important or valuable before she will discuss the deal.",al={"what does she want","give anastasia something","anastasia bargain"}},{q="Where do I look for something to convince her?",a="Anastasia asks you to find something within Stromgarde Keep to convince her.",al={"where to look","find something for anastasia","stromgarde keep item"}}},kw={"ain't no telling","anastasia","higher-ups","secret deal","stromgarde keep","valuable"},rel={"subzone:stromgarde-keep"},m={id=96785},src={"In-game quest text: Ain't No Telling"},fv=true}
E["quest:96786"] = {t="quest",n="The Syndicate Sting",z="arathi",s="In Stromgarde, you get word of a secret Syndicate handoff near Thoradin’s Wall. The object being traded remains unknown, and Myrokos Silentform at Ravenholdt Manor wants it.",h="In Stromgarde, you get word of a secret Syndicate handoff near Thoradin’s Wall.",sec={{t="A Secret Handoff",b="Falconcrest arranged the handoff. Some of his men are meeting at the southern part of Thoradin’s Wall, though even those sent to collect the goods may not know what they are taking. You are asked to break up the deal and bring the traded object back to Myrokos Silentform at Ravenholdt Manor.",sp=0}},faq={{q="Who sent men to the handoff?",a="Falconcrest sent men to make the handoff at the southern part of Thoradin’s Wall.",al={"who sent them","falconcrest men","who arranged the deal"}},{q="Where is the secret deal?",a="The handoff is set for the southern part of Thoradin’s Wall.",al={"handoff location","where deal","thoradin wall deal"}},{q="What is being traded?",a="The object being traded is unknown, and even the men sent to collect it may not know what it is.",al={"what's the object","what are they picking up","secret item"}},{q="What does Myrokos want?",a="Myrokos Silentform asks you to break up the deal, take the object being traded to the Syndicate, and return it to him at Ravenholdt Manor.",al={"myrokos wants","what am i doing","what to bring back"}}},kw={"falconcrest","myrokos silentform","ravenholdt manor","secret handoff","syndicate","the syndicate sting","thoradin's wall","traded object"},rel={"subzone:ravenholdt-manor","subzone:thoradin-s-wall","topic:syndicate","topic:ravenholdt"},m={id=96786},src={"In-game quest text: The Syndicate Sting"},fv=true}
E["quest:97539"] = {t="quest",n="Silky Sutures",z="arathi",s="At Hammerfall, Doctor Gregory Victor is turning to spider silk as infirmary supplies dwindle. Siege damage remains unrepaired, and the outpost's guards and laborers still need care.",h="At Hammerfall, Doctor Gregory Victor is turning to spider silk as infirmary supplies dwindle.",sec={{t="The Crumbling Outpost",b="Hammerfall endures in the Arathi Highlands, though siege damage still mars its defenses. Doctor Gregory Victor, the outpost's physician, sees the neglect as official policy. With little support and crumbling fortifications around him, he keeps the infirmary running. Its care helps laborers and sentinel guards stay on their feet and ready for conflict.",sp=0},{t="Makeshift Medical Supplies",b="Medical supplies are running low at Hammerfall, so Doctor Victor seeks another way to stitch wounds. Tough highland spider silk can be twisted into resilient sutures when bandages and ordinary thread are scarce. Victor jokes that infection is the least of a wounded soldier's worries. The silk gives the infirmary thread to patch up defenders in hostile territory.",sp=0},{t="Gallows Humor in Hammerfall",b="Doctor Gregory Victor greets travelers with dry jokes about grave prognoses and stitches made from spider silk. His humor masks the hard truth of running a frontline clinic while Hammerfall remains isolated. Regular aid is rare in the highlands, and travelers can help keep the clinic supplied. Victor relies on improvised remedies and determination to care for the wounded as the outpost decays around him.",sp=0}},faq={{q="Who is Doctor Gregory Victor?",a="Doctor Gregory Victor oversees Hammerfall's infirmary as its medical officer and trauma surgeon. He treats wounded guards and laborers with a blunt manner and mordant wit. Despite shortages and unrepaired siege damage, he keeps the ward working.",al={"who is victor","gregory victor lore","hammerfall doctor"}},{q="Why does Doctor Victor need spider silk?",a="Doctor Victor needs spider silk because Hammerfall's infirmary is nearly out of ordinary supplies. He twists strong highland spider silk into sutures to close wounds when proper thread is unavailable.",al={"why spider silk","surgical spidersilk use","spider silk sutures"}},{q="What condition is Hammerfall in during this quest?",a="Hammerfall shows clear signs of neglect and strain. Its siege damage remains unrepaired, and Doctor Victor sees that neglect as official policy. With little aid or supplies, the guards, laborers, and medical staff must make do.",al={"hammerfall status","why is hammerfall damaged","state of hammerfall"}},{q="Where do the spiders for this quest come from?",a="The spiders roam the wilderness of the Arathi Highlands around Hammerfall. They must be hunted across the highland plains to gather silk for Doctor Victor's sutures, then brought back to the clinic.",al={"arathi spiders","where to find spidersilk","surgical spidersilk location"}},{q="Why is Doctor Victor sarcastic about infection?",a="Doctor Victor jokes that infection is the least of a wounded soldier's worries when he stitches them with spider silk. His dark humor reflects the demands of frontline care, where stopping blood loss and treating grave wounds come before sterile conditions.",al={"doctor humor","spider silk infection","victor jokes"}},{q="Why are supplies so scarce at Hammerfall?",a="Hammerfall is isolated in a contested part of the Arathi Highlands and faces hostile threats. Reinforcements and supplies arrive infrequently, leaving the garrison and infirmary short of materials, tools, and healing supplies.",al={"why no supplies","hammerfall supply shortage","lack of help hammerfall"}},{q="Who does the infirmary in Hammerfall treat?",a="Doctor Gregory Victor's infirmary treats the laborers and guards stationed at Hammerfall. Keeping them healthy helps the outpost remain fortified and functional despite danger and structural damage.",al={"who does victor treat","hammerfall patients","clinic patients"}}},ang={["faction:Horde"]="Hammerfall is a vital Horde stronghold in the Arathi Highlands. Doctor Victor's work keeps its defenders healthy and ready to protect the faction's position there.",["race:Undead"]="As an undead, you bring the Forsaken's pragmatic, unsentimental medical knowledge to Hammerfall, using resources from the highlands to keep the clinic working."},kw={"arathi highlands","doctor gregory victor","field sutures","hammerfall","infirmary","silky sutures","spider silk","surgical spidersilk"},rel={"npc:doctor-gregory-victor","subzone:hammerfall","zone:arathi"},m={faction="Horde",id=97539},src={"In-game quest text: Silky Sutures"},fv=true}
E["subzone:boulder-gor"] = {t="subzone",n="Boulder'gor",z="arathi",s="Boulder'gor commands western Arathi, north of Stromgarde, where Boulderfist ogres and Witherbark trolls share an encampment.",h="Boulder'gor commands western Arathi, north of Stromgarde, where Boulderfist ogres and Witherbark trolls share...",sec={{t="A Den of Ogres and Trolls",b="North of Stromgarde Keep’s crumbling ramparts, Boulder'gor rises above the central roads of Arathi. The Boulderfist Outpost mound stands among its shadows, a stronghold of ogre power across the highlands. Boulderfist ogres share fires and fortifications with Witherbark forest trolls. Their shadowy spellcasters add dark magic to the clan’s brute force, and together they endanger travelers on the roads.",sp=0},{t="Surrounding Territory",b="From Boulder'gor’s slopes, you can look across the open highlands of western Arathi. The hill lies between Stromgarde’s Syndicate-infiltrated ruins and the plains’ wild elemental sites. Heavily guarded and hostile, Boulder'gor remains a tribal stronghold against Alliance and Horde wanderers.",sp=0}},faq={{q="What is Boulder'gor?",a="Boulder'gor rises as a hill and encampment north of Stromgarde Keep in the Arathi Highlands. Boulderfist ogres and Witherbark forest trolls hold it in force.",al={"where is bouldergor","bouldergor info","what is this place"}},{q="Why are forest trolls living alongside ogres here?",a="The Witherbark trolls and Boulderfist ogres maintain a pragmatic alliance in Arathi. Both seek dominance over the highlands and aim to fend off rival factions, joining troll shadowcraft with brute ogre strength.",al={"why are trolls here","witherbark ogre alliance","trolls and ogres"}},{q="What major landmarks are near Boulder'gor?",a="Boulder'gor lies directly north of Stromgarde Keep. Boulderfist Outpost’s ogre mound stands within the hill.",al={"nearby places","what is next to bouldergor","landmarks"}},{q="Is Boulder'gor friendly to the Horde or Alliance?",a="Neither faction is welcome. Boulderfist ogres and Witherbark trolls aggressively defend Boulder'gor from Alliance and Horde outsiders.",al={"can i go there safely","is bouldergor hostile"}}},ang={["race:Troll"]="As a Darkspear troll, you will find no kinship with the Witherbark forest trolls of Boulder'gor. They hold ancient grudges against outsiders, even other troll tribes.",["faction:Alliance"]="As an Alliance soldier seeking to reclaim Stromgarde, you face a serious threat at Boulder'gor, on the fallen kingdom’s northern doorstep."},kw={"arathi highlands","boulder'gor","boulderfist","bouldergor","ogres","stromgarde","witherbark"},rel={"subzone:boulderfist-outpost","subzone:stromgarde-keep","zone:arathi","topic:troll"},src={"Boulder'gor"}}
E["subzone:boulderfist-hall"] = {t="subzone",n="Boulderfist Hall",z="arathi",s="Boulderfist ogres hold the southern hills of the Arathi Highlands, north of Thandol Span. Under Kor'gresh Coldrage, they threaten the nearby roads and valleys.",h="Boulderfist ogres hold the southern hills of the Arathi Highlands, north of Thandol Span.",sec={{t="A Bastion of Brute Strength",b="Boulderfist Hall shelters the Boulderfist clan in the southern bluffs of the Arathi Highlands. Its earthen walls and deep caverns house ogre brutes and magi, near Witherbark Village and the bridge at Thandol Span. Kor'gresh Coldrage leads the clan from deep within the mound, with enforcers such as Phalanax at his side. The ogres hold the surrounding roads by force, making travel between Arathi and the Wetlands dangerous for travelers and supply caravans.",sp=0}},faq={{q="What is Boulderfist Hall?",a="Boulderfist Hall is a fortified mound and cave complex in the southern Arathi Highlands. The Boulderfist clan makes its base there.",al={"what is this place","boulderfist mound","ogre cave arathi"}},{q="Who rules Boulderfist Hall?",a="Kor'gresh Coldrage leads the ogres from a deep cavern in the mound. Champions such as Phalanax stand beside him.",al={"who leads boulderfist hall","ogre boss arathi","kor'gresh"}},{q="Why is this location strategically important?",a="Close to Thandol Span, the Boulderfist ogres can threaten the overland route between the Arathi Highlands and Khaz Modan. They prey on travelers and choke off traffic.",al={"why ogres here","thandol span danger"}},{q="Are the Boulderfist allied with the nearby Witherbark trolls?",a="No formal alliance binds the Boulderfist ogres and the Witherbark forest trolls. They live near one another at Witherbark Village, and at Boulder'gor elsewhere in the highlands, Witherbark trolls share ground with ogres. Both groups remain hostile to outsiders of every faction.",al={"ogres and trolls friends","witherbark alliance"}}},ang={["faction:Alliance"]="Above Thandol Span, Boulderfist ogres threaten Alliance couriers and reinforcements traveling north from Ironforge into Arathi.",["faction:Horde"]="To secure the Arathi Highlands, you must break the ogres' independent power and clear the southern ridge. That protects Horde movement from Hammerfall."},kw={"arathi highlands","boulderfist","boulderfist hall","kor'gresh coldrage","ogre mound","phalanax","thandol span"},rel={"zone:arathi","subzone:thandol-span","subzone:witherbark-village"},src={"Boulderfist Hall"}}
E["subzone:boulderfist-outpost"] = {t="subzone",n="Boulderfist Outpost",z="arathi",s="Deep within Boulder'gor, Boulderfist ogres hold a fortified mound and its inner halls. A few Witherbark trolls dwell among them in the Arathi Highlands.",h="Deep within Boulder'gor, Boulderfist ogres hold a fortified mound and its inner halls.",sec={{t="A Stronghold within the Mound",b="Boulderfist Outpost lies at the heart of Boulder'gor in western Arathi. Brute enforcers rule the settlement above, while the clan's strength gathers inside the mound. Carved from earth and stone, its dark halls serve as a den and a holding place. A few Witherbark troll witch doctors live among the ogres, a sign that the tribes sometimes share this ground.",sp=0}},faq={{q="Where is Boulderfist Outpost located?",a="Boulderfist Outpost lies within Boulder'gor, the larger ogre settlement in the western Arathi Highlands.",al={"boulderfist outpost location","where is boulderfist outpost","boulderfist mound entrance"}},{q="Why are there trolls inside an ogre outpost?",a="Witherbark forest trolls dwell nearby in the Arathi Highlands and sometimes share ground with the Boulderfist ogres. A few Witherbark witch doctors practice their craft inside the mound alongside them.",al={"why are witherbark here","trolls in boulderfist","witherbark trolls arathi"}},{q="Who is imprisoned in the outpost?",a="No named captives are known to be held in the outpost today. Boulderfist enforcers and a few Witherbark witch doctors occupy its damp corridors, where intruders should expect a fight rather than a rescue.",al={"boulderfist prisoners","who is trapped in boulderfist","captives in arathi ogres"}},{q="Who leads the ogres inside the outpost?",a="Boulderfist brute enforcers patrol the interior. An exceptionally fierce ogre named Kovork lurks within the mound as a notable threat.",al={"kovork","boulderfist boss arathi","boulderfist rare"}}},ang={["faction:Alliance"]="Alliance scouts crossing Arathi should give the mound a wide berth. Boulderfist enforcers attack intruders on sight.",["faction:Horde"]="Boulderfist ogres make no distinction between factions. They attack Horde wanderers as readily as their Alliance rivals."},kw={"arathi","boulder'gor","boulderfist","captives","kovork","ogre mound","prisoners","witherbark"},rel={"subzone:boulder-gor","zone:arathi","topic:troll"},src={"Boulderfist Outpost"}}
E["subzone:circle-of-east-binding"] = {t="subzone",n="Circle of East Binding",z="arathi",s="In eastern Arathi, water elementals guard the Circle of East Binding, southwest of Hammerfall. At its heart, the Stone of East Binding draws fierce contest.",h="In eastern Arathi, water elementals guard the Circle of East Binding, southwest of Hammerfall.",sec={{t="The Eastern Ward",b="East of Stromgarde, the Circle of East Binding lies among Arathi's rugged highlands. The Stone of East Binding rises at its center, charged with elemental magic. Cresting exiles roam the ground around it. These swirling water elementals fiercely defend the stone from any mortal who approaches.",sp=0},{t="Elemental Imprisonment",b="Ancient stones across Arathi bind volatile elemental forces. Around the eastern circle, restless water spirits show the strain on those wards. Drawn to the stone's magic or trapped by it, they lash out at travelers on the nearby road to Hammerfall.",sp=0}},faq={{q="Where is the Circle of East Binding located?",a="The Circle of East Binding lies in eastern Arathi, south of the main road and southwest of Hammerfall, the Horde camp.",al={"east binding location","where is circle of east binding","circle of east binding map"}},{q="What creatures are found here?",a="Aggressive water elementals called cresting exiles roam the circle and guard the Stone of East Binding.",al={"east binding mobs","what monsters are at east binding","cresting exiles"}},{q="Why are there water elementals in the highlands?",a="Ancient stones across Arathi bind elemental forces. The water elementals here may be held by the eastern ward stone or drawn to its energy.",al={"why water elementals arathi","east binding elemental lore"}},{q="What is the purpose of the Stone of East Binding?",a="The Stone of East Binding belongs to a network of binding stones across the Arathi Highlands. They were built to anchor, channel, and imprison volatile elemental forces.",al={"stone of east binding purpose","what does east binding stone do"}}},ang={["class:Shaman"]="As a shaman, you may see Arathi's binding stones as an ancient way to suppress elemental forces, far from the balance and communion you seek.",["faction:Horde"]="Just down the road from Hammerfall, volatile water spirits around the circle trouble Horde patrols and supply lines."},kw={"arathi highlands","circle of east binding","cresting exile","elementals","hammerfall","stone of east binding"},rel={"zone:arathi","subzone:hammerfall"},src={"Circle of East Binding"}}
E["subzone:circle-of-inner-binding"] = {t="subzone",n="Circle of Inner Binding",z="arathi",s="Beneath the Arathi Highlands, the Circle of Inner Binding holds Myzrael beneath ancient stones. The Stone of Inner Binding anchors the strongest ward, but cracks let the imprisoned princess reach out to wanderers.",h="Beneath the Arathi Highlands, the Circle of Inner Binding holds Myzrael beneath ancient stones.",sec={{t="The Core Seal",b="South of the main road, towering slabs ring the Stone of Inner Binding on a plateau. The stone thrums with the strongest ward beneath Arathi and its dense geo-magical power. Rumbling Exiles patrol the stones, drawn by the site's resonance or bound there as guardians.\n\nCracks in the inner seal let the imprisoned Myzrael reach out telepathically. She whispers pleas for freedom to unsuspecting wanderers who handle shards of her stone.",sp=0}},faq={{q="What is the purpose of the Circle of Inner Binding?",a="The Circle holds the Stone of Inner Binding, the strongest ward anchoring Myzrael's prison beneath the earth. It works with other elemental circles scattered through the Arathi Highlands to restrain her below the surface.",al={"why is this circle here","what does the inner binding do","circle of inner binding lore"}},{q="What creatures guard this circle?",a="Powerful earth elementals guard the circle, chiefly Rumbling Exiles. These rocky behemoths attack anyone who approaches the ritual stones.",al={"what enemies are here","inner binding mobs","rumbling exile"}},{q="Who is whispering through the stone?",a="Myzrael is an ancient and powerful elemental princess imprisoned deep beneath the earth. Her psychic reach has pierced the fractured seal, letting her contact mortal minds through the binding shard.",al={"who talks to you here","myzrael voice","whispering stone"}},{q="Where is the Circle of Inner Binding located?",a="The Circle stands on an elevated ridgeline in the southern Arathi Highlands, just east of Stromgarde Keep.",al={"inner binding location","where is circle of inner binding","how to find inner binding"}}},ang={["class:Shaman"]="As a shaman, you can feel raw earthen energy surging through the Circle of Inner Binding. Its ancient, heavy elemental bonds are clear, while the earth spirits' unnatural agitation warns of corruption beneath the soil.",["class:Mage"]="As a mage, you can read an intricate pattern in the stones. Their geometric arrangement forms a lasting containment field that channels and anchors immense subterranean magical pressures."},kw={"arathi highlands","circle of inner binding","earth elementals","myzrael","rumbling exile","stone of inner binding","stromgarde keep"},rel={"zone:arathi","subzone:stromgarde-keep"},src={"Circle of Inner Binding"}}
E["subzone:circle-of-west-binding"] = {t="subzone",n="Circle of West Binding",z="arathi",s="Near Thoradin's Wall, Burning Exiles overrun the Circle of West Binding and guard its stone. The ancient ritual site is one of several scattered across the Arathi Highlands.",h="Near Thoradin's Wall, Burning Exiles overrun the Circle of West Binding and guard its stone.",sec={{t="The Western Keystone",b="Near Thoradin's Wall, the Stone of West Binding stands at the Circle of West Binding. The site belongs to a wider network of ancient ritual places scattered across the Arathi Highlands. Burning Exiles overrun the grounds and guard the stone. Their fiery presence makes an approach perilous for travelers crossing the western plains.",sp=0}},faq={{q="What is the Circle of West Binding?",a="The Circle of West Binding is an ancient ritual site in western Arathi Highlands, near Thoradin's Wall. The Stone of West Binding stands there, guarded by hostile fire elementals.",al={"circle of west binding","stone of west binding","west binding circle"}},{q="Why are there fire elementals here?",a="The Burning Exiles inhabit and guard the Stone of West Binding. These elemental forces are drawn or bound to ancient magical foci built across the Arathi Highlands.",al={"burning exiles arathi","why fire elementals west binding","elementals circle of west binding"}},{q="Who is Ruul Onestone?",a="Ruul Onestone is a Boulderfist ogre mage who prowls the site. He is a rare and dangerous brute, not a scholar of the binding stone.",al={"ruul onestone","ruul","dwarf at west binding"}}},ang={["class:Mage"]="As a mage, you can find insight in Arathi's binding stones into how ancient mages and shamans anchored and subdued planar elemental entities.",["class:Shaman"]="As a shaman, you can read the Burning Exiles' volatile presence as a sign of elemental unrest still tethered to these ancient Arathi keystones."},kw={"arathi highlands","burning exile","circle of west binding","elemental","ruul onestone","stone of west binding","thoradin's wall"},rel={"zone:arathi","subzone:thoradin-s-wall"},src={"Circle of West Binding"}}
E["subzone:crypt-stromgarde-keep"] = {t="subzone",n="Crypt",z="arathi",s="In Stromgarde Keep, loyalists guard the royal crypt beneath the Sanctum. It holds King Thoras Trollbane’s tomb and the treasures of his line.",h="In Stromgarde Keep, loyalists guard the royal crypt beneath the Sanctum.",sec={{t="The Tomb of Thoras Trollbane",b="Beneath Stromgarde Keep’s Sanctum lies King Thoras Trollbane’s tomb. He led Stromgarde through the Second War. The city is in ruins, divided between Syndicate rogues and Boulderfist ogres, yet the surviving Stromgarde militia still holds this quarter.\n\nPrince Galen Trollbane watches over the crypt with the royal caretakers. They keep his father’s body and legacy safe from scavengers and enemies outside.",sp=0},{t="The Vault of Trol'kalar",b="The crypt guards artifacts of the Trollbane line. Among them is Trol'kalar, an ancient runed greatsword forged centuries ago to slay trolls. Sworn caretakers, including Alaric, Nevlin, and Weston, protect the chamber and its treasures with powerful safeguards.\n\nGalen and his loyalists keep watch. Rival factions and hostile trolls across Arathi covet the blade’s ancient power.",sp=0}},faq={{q="Who is buried in the crypt?",a="King Thoras Trollbane, Stromgarde’s late ruler, is buried in the crypt. His son, Prince Galen Trollbane, watches over the tomb amid the ruined city.",al={"who is buried here","whose tomb is this","crypt tomb"}},{q="What is Trol'kalar?",a="Trol'kalar is an ancient heirloom blade of the Trollbane family. Its name means “troll slayer” in the ancient tongue. It was forged to fight the forest trolls of the Arathi basin.",al={"trolkalar sword","trollbane sword","what is trolkalar"}},{q="Who guards the crypt?",a="Prince Galen Trollbane and Stromgarde’s royal caretakers guard the crypt, including Alaric, Nevlin, and Weston. They defend the burial chamber from Syndicate thieves and Boulderfist ogres.",al={"crypt guards","who defends the crypt","caretakers"}},{q="Where is the crypt located?",a="The crypt lies within Stromgarde Keep in the Arathi Highlands, deep in the Sanctum district behind the keep’s chapel. It is in the quarter still held by Stromgarde loyalists.",al={"crypt location","how to find the crypt","where is stromgarde crypt"}}},ang={["race:Human"]="As a human of the Alliance, you can see Stromgarde’s decline in this tomb. Here rests one of the Alliance’s fiercest wartime leaders, from one of its seven great kingdoms.",["faction:Alliance"]="As an Alliance member, you find one of Arathi’s last bastions of Alliance heritage in Stromgarde’s royal crypt. Its defenders hold off bandits, ogres, and the Horde."},kw={"arathi","crypt","galen","sanctum","stromgarde","thoras","trol'kalar","trollbane"},rel={"subzone:sanctum-stromgarde-keep","subzone:stromgarde-keep","zone:arathi"},src={"Crypt (Stromgarde Keep)"}}
E["subzone:dabyrie-s-farmstead"] = {t="subzone",n="Dabyrie's Farmstead",z="arathi",s="In northern Arathi, the Dabyries keep their farm against the dangers around them. Kenata Dabyrie holds fast with her sons, loyal to Stromgarde and the Alliance in a realm broken by the Third War.",h="In northern Arathi, the Dabyries keep their farm against the dangers around them.",sec={{t="A Bastion in the Highlands",b="Kenata Dabyrie and her sons hold their farm against the dangers around them. Fardel and Marcel work the fields while a local family militia guards the grounds. Few human homesteads still endure in the broken kingdom of Stromgarde. Aggressive wildlife and bandits threaten the farm, and the Forsaken press from the north. The Dabyries keep their home in a land where few human settlements remain.",sp=0},{t="Bitter Feuds",b="The Forsaken have turned against the Dabyries, and Genavie Callow is among their bitterest foes. Once a noblewoman, Callow lost her lands and kin during the Third War. She accuses the surviving Dabyrie family of taking her family's heirlooms amid the plague's chaos. Now Horde mercenaries target the modest farm to settle old grudges from the north.",sp=1}},faq={{q="Who lives at Dabyrie's Farmstead?",a="Kenata Dabyrie lives at the farm with her sons, Fardel and Marcel. They are human citizens of Stromgarde, loyal to the Alliance and defended by a sworn local militia.",al={"who owns dabyrie farm","dabyrie family","kenata dabyrie"}},{q="Why is the Horde targeting this farm?",a="The Forsaken woman Genavie Callow holds a grudge against the Dabyries. She accuses them of taking her family's estate and surviving heirlooms while her relatives perished in the Third War.",al={"why kill dabyrie","genavie callow quest","horde dabyrie quest"}},{q="Is Dabyrie's Farmstead part of Stromgarde?",a="Yes. The Dabyries consider themselves subjects of Stromgarde and allies of the broader Alliance, though their capital lies in ruins to the south.",al={"is dabyrie alliance","stromgarde farm"}},{q="What threats surround the farmstead?",a="Highland predators and roaming Syndicate cutthroats threaten the farm. Forsaken forces press from the north.",al={"threats to dabyrie","danger near dabyrie farm"}}},ang={["faction:Alliance"]="As an Alliance traveler, you can find a rare reminder here that Stromgarde's people still survive and fight for their land amid encroaching enemies.",["race:Undead"]="As Forsaken, you see a prosperous human farm holding goods your people say were taken from families who perished during the Third War."},kw={"arathi","callow","dabyrie","fardel","farmstead","kenata","marcel","stromgarde"},rel={"zone:arathi","subzone:stromgarde-keep","topic:forsaken","topic:alliance","topic:third-war","topic:syndicate"},src={"Dabyrie's Farmstead"}}
E["subzone:drowned-reef"] = {t="subzone",n="Drowned Reef",z="arathi",s="Ships bound for Faldir's Cove risk the Drowned Reef off Arathi's southern coast. Ancient ruins lie below, where Daggerspine naga seem able to command the bay's tides.",h="Ships bound for Faldir's Cove risk the Drowned Reef off Arathi's southern coast.",sec={{t="A Graveyard of Ships",b="Beyond the hidden entrance to Faldir's Cove, shattered ships rest beneath the waves. The Maiden's Folly and the Spirit of Silverpine lie among them. Daggerspine naga dwell on the reef under Prince Nazjak's command. They seem able to command the bay's tides, and crews seeking shelter in the cove may be doomed by them.",sp=0},{t="The Sunken City",b="Deep beneath the reef lie the ruins of an ancient elven city. Dive among the drowned buildings, and calcified elven gems can still be found among the remains.",sp=0}},faq={{q="What is the Drowned Reef?",a="The Drowned Reef lies off the southern coast of the Arathi Highlands, just offshore from Faldir's Cove. Its waters endanger ships, while ancient ruins lie beneath the sea.",al={"drowned reef","where is drowned reef","arathi reef"}},{q="Why are there so many sunken ships here?",a="Ships face danger in the waters off Arathi's southern coast. Daggerspine naga seem able to command the bay's tides, putting crews seeking refuge in Faldir's Cove at risk.",al={"why are ships sinking","sunken ships arathi","maidens folly"}},{q="Who controls the Drowned Reef?",a="Daggerspine naga inhabit the Drowned Reef's flooded ruins under Prince Nazjak's command. They prey on stranded sailors and guard their submerged territory.",al={"who leads the naga here","prince nazjak","daggerspine naga arathi"}},{q="What are the ruins submerged beneath the reef?",a="The ruins beneath the Drowned Reef belong to an ancient elven city. Calcified elven gems remain among its drowned buildings.",al={"underwater ruins arathi","elven ruins drowned reef"}}},ang={["race:NightElf"]="As a Night Elf, you may see the flooded halls and calcified gems as reminders of the Kaldorei empire. It shattered into the sea ten thousand years ago during the Great Sundering."},kw={"arathi highlands","daggerspine","drowned reef","faldir's cove","maiden's folly","naga","prince nazjak","spirit of silverpine","sunken ruins"},rel={"zone:arathi","subzone:faldir-s-cove","topic:naga"},src={"Drowned Reef"}}
E["subzone:drywhisker-gorge"] = {t="subzone",n="Drywhisker Gorge",z="arathi",s="Northeast of Hammerfall, Drywhisker kobolds hold a gorge in the eastern mountains of the Arathi Highlands. They guard its inner cavern, rich mineral deposits and ancient elemental relics buried underground.",h="Northeast of Hammerfall, Drywhisker kobolds hold a gorge in the eastern mountains of the Arathi Highlands.",sec={{t="A Warren in the Eastern Crags",b="Drywhisker kobolds hold the crags east of Hammerfall. Their clan has dug deep into the mountains and fiercely guards its winding passages. Below, they mine veins of Lesser Bloodstone Ore. Their stronghold lies close enough to trouble the orcs at Hammerfall.",sp=0},{t="Secrets of the Deep Cavern",b="Deep in the Drywhisker cavern lies a stone shard. The kobolds are allied with the towering stone giants of the highlands and tend motes of ancient earth magic. The shard holds a trapped fragment of Princess Myzrael's essence. She is an ancient earth entity bound below the surface.",sp=1}},faq={{q="Who lives in Drywhisker Gorge?",a="The Drywhisker clan of kobolds lives in the gorge and its cavern passages. They defend their territory and mining operations, along with the relics hidden within.",al={"drywhisker gorge inhabitants","what is in drywhisker gorge","who controls drywhisker gorge"}},{q="Where is Drywhisker Gorge located?",a="Drywhisker Gorge cuts through the eastern mountains of the Arathi Highlands, northeast of Hammerfall. A rugged path climbs through the hills east of the outpost to the cavern entrance.",al={"how to get to drywhisker gorge","drywhisker gorge location","where is the cave in arathi"}},{q="What makes the cave inside significant?",a="The cave holds rare deposits of Lesser Bloodstone Ore and an ancient stone shard. The shard contains a fragment of Princess Myzrael's imprisoned essence.",al={"what is in the cave","drywhisker cave secrets","myzrael shard"}},{q="Why are the kobolds allied with mountain giants?",a="The Drywhisker clan is allied with the local stone giants. The kobolds serve and guard earth relics and elemental motes tied to Princess Myzrael's bindings deep beneath Arathi.",al={"kobolds and giants","why are drywhiskers with giants"}}},ang={["profession:Mining"]="Miners prize the Drywhisker cavern as the only known source of Lesser Bloodstone Ore. The dense, crimson-veined mineral lies deep within the kobold-held rock.",["faction:Horde"]="The hostile Drywhisker kobolds live just over the mountain ridge east of Hammerfall. They threaten the outpost's eastern flank."},kw={"arathi highlands","drywhisker","drywhisker gorge","hammerfall","kobold","lesser bloodstone ore","princess myzrael","stone shard"},rel={"zone:arathi","subzone:hammerfall","topic:kobold"},src={"Drywhisker Gorge"}}
E["subzone:faldir-s-cove"] = {t="subzone",n="Faldir's Cove",z="arathi",s="Blackwater Raiders now shelter at Faldir's Cove after disaster struck their fleet on the Arathi coast. The harbor also recalls the early settlers who sailed south from here to found Stormwind.",h="Blackwater Raiders now shelter at Faldir's Cove after disaster struck their fleet on the Arathi coast.",sec={{t="A Gateway South and a Pirate Haven",b="South of Stromgarde Keep, Faldir's Cove lies behind the bluffs, reached through a hidden tunnel beneath the ground. The harbor bears the name of Faldir, an ancient Arathor explorer whose expedition sailed across the Great Sea to establish Stormwind. Now Blackwater Raiders from Booty Bay shelter in its waters. Captains Steelgut and O'Breen led them north in search of ancient elven treasures, but their expedition became trapped in the bay.",sp=0},{t="The Wreck of the Blackwater Fleet",b="The Blackwater expedition met disaster on the Arathi coast. Unnatural tides, stirred by territorial naga on the offshore Drowned Reef, shattered two of their three ships. Only the Harbinger reached Faldir's Cove intact. With naga prowling the waters and their navigation charts lost beneath the waves, the surviving pirates and gnomish researchers are stranded. They rely on travelers to fight the aquatic horrors and recover salvage from the seabed.",sp=0}},faq={{q="Who was Faldir?",a="Faldir was an ancient pioneer from the human empire of Arathor. He and his followers sailed south from this coast across the sea to establish the settlements that became Stormwind.",al={"faldir lore","who is faldir","faldir founder"}},{q="How do you reach Faldir's Cove?",a="Reach Faldir's Cove through a hidden tunnel just southeast of Stromgarde Keep's outer southern walls. The passage runs beneath the ground and opens onto the secluded shore.",al={"how to get to faldir's cove","faldir cove entrance","cave to faldirs cove"}},{q="Why are the Blackwater Raiders here?",a="Captain Steelgut and Captain O'Breen led the Blackwater Raiders north from Booty Bay to seek sunken elven treasures. Gnomish inventors came with them, carrying devices designed to detect gems in the offshore reefs.",al={"why are pirates here","blackwater raiders arathi","what are the pirates doing"}},{q="What happened to their ships?",a="Hostile naga on the Drowned Reef stirred unnatural tides that destroyed two of the expedition's three vessels. The flagship Harbinger reached the cove, but the crew's charts sank beneath the waves.",al={"why are ships wrecked","sunken ships arathi","who sank the ships"}}},ang={["race:Human"]="As a human, you stand on the coast where your ancestors left Arathor and sailed south toward the settlements that became Stormwind.",["race:Gnome"]="As a gnome, you can find Doctor Draxlegauge and Professor Phizzlethorpe at the camp, using engineering devices to study and extract elven gems from the calcified coastal reefs."},kw={"blackwater raiders","captain o'breen","captain steelgut","draxlegauge","drowned reef","faldir","faldir's cove","harbinger","phizzlethorpe"},rel={"subzone:drowned-reef","zone:arathi","subzone:stromgarde-keep","subzone:booty-bay","topic:stormwind-kingdom","topic:naga"},src={"Faldir's Cove"}}
E["subzone:go-shek-farm"] = {t="subzone",n="Go'Shek Farm",z="arathi",s="Go'Shek Farm gathers food and livestock for Hammerfall in the Arathi Highlands. Forsaken apothecaries also work there in secret.",h="Go'Shek Farm gathers food and livestock for Hammerfall in the Arathi Highlands.",sec={{t="A Horde Outpost in the East",b="South of Hammerfall, Go'Shek Farm lies just north of hostile Witherbark troll territory. The Horde holds the farm, and Hammerfall Grunts patrol its fields and stables. Its food and livestock help the orcish settlement keep its foothold in the Arathi Highlands.",sp=0},{t="The Apothecary's Workshop",b="The Royal Apothecary Society keeps a quiet presence at Go'Shek Farm, led by figures such as Apothecary Jorell. Couriers carry notes, reagents, and research between the farm and Tarren Mill, studying early forms of the Forsaken's new plague. Alliance scouts seek to intercept the messengers and learn what poison is being prepared in the Arathi soil.",sp=1}},faq={{q="Why is the Horde occupying Go'Shek Farm?",a="Go'Shek Farm supplies food and livestock to nearby Hammerfall. It also gives the Forsaken a guarded place for sensitive chemical and alchemical research.",al={"who owns goshek farm","why are orcs at goshek farm","goshek farm horde"}},{q="Who used to own this farm?",a="The farm's earlier owners are not recorded. Today, orcs from nearby Hammerfall work and guard it for the Horde.",al={"goshek farm history","human farm arathi","primwell skye"}},{q="What kind of experiments are happening here?",a="Forsaken apothecaries conduct secretive alchemical work at the farm. Alliance agents investigate courier traffic and records there to learn its nature.",al={"apothecary jorell","plague experiments arathi","forsaken research goshek"}},{q="Why are there Alliance agents watching the farm?",a="Quae and Kinelory investigate suspicious traffic between Go'Shek Farm and Tarren Mill. They seek evidence of the Forsaken's activities and need help reaching it.",al={"quae kinelory","alliance scouting goshek","hints of a new plague"}}},ang={["faction:Alliance"]="The farm supplies Hammerfall and houses Forsaken apothecaries whose secretive work has drawn Alliance scrutiny.",["faction:Horde"]="Keeping Go'Shek Farm secure helps provision Hammerfall and guard its perimeter against the encroaching Witherbark trolls."},kw={"apothecary jorell","arathi","go'shek farm","goshek","hammerfall","kinelory","quae","swee","witherbark"},rel={"subzone:hammerfall","zone:arathi","subzone:tarren-mill","quest:367","topic:forsaken","topic:horde","subzone:witherbark-village","topic:alliance"},src={"Go'Shek Farm"}}
E["subzone:hammerfall"] = {t="subzone",n="Hammerfall",z="arathi",s="Horde forces hold Hammerfall in the Arathi Highlands, where old losses and a hard-won freedom shape the outpost. Orcs and Forsaken defend it against Boulderfist ogres, Witherbark trolls, and the League of Arathor.",h="Horde forces hold Hammerfall in the Arathi Highlands, where old losses and a hard-won freedom shape the...",sec={{t="A Legacy of Liberation",b="Beneath Hammerfall lie the ruins of an Alliance internment camp. After the Second War, the human Alliance built vast camps across Lordaeron for defeated orcs, and this was among the largest. Years later, Thrall and Orgrim Doomhammer struck at the camp to free its lethargic captives.\n\nAs they retreated, an Alliance knight charged and drove a lance through Doomhammer's backplate. The Warchief was mortally wounded. After the Third War, the new Horde reclaimed the ruins and named its outpost Hammerfall in his memory.",sp=0},{t="A Foothold in the Highlands",b="Hammerfall gives the Horde a foothold in Arathi. Its garrison faces aggressive Boulderfist ogres from Boulder'gor and Boulderfist Hall, as well as the native Witherbark trolls. Forsaken Defilers use the outpost to claim resources in the contested Arathi Basin. There they oppose the Alliance's League of Arathor.",sp=0}},faq={{q="Why is this base called Hammerfall?",a="The base honors Orgrim Doomhammer, who was mortally wounded by an Alliance knight's lance while freeing orcs from the internment camp.",al={"why hammerfall","hammerfall name origin","who died at hammerfall"}},{q="What was Hammerfall before the Horde rebuilt it?",a="Before the Horde rebuilt it, the site held one of the largest Alliance of Lordaeron internment camps. It was built after the Second War to imprison captive orcs.",al={"hammerfall history","what was hammerfall before","internment camp arathi"}},{q="Who leads the defense of Hammerfall right now?",a="Orc Drum Fel rules Hammerfall and directs its defense against the Boulderfist ogres and Witherbark forest trolls. Tallow, a Forsaken warrior at Tarren Mill, first sends recruits to attack the Boulderfist ogres of Boulder'gor.",al={"hammerfall leaders","who is in charge of hammerfall","tallow drum fel"}},{q="Why are the Forsaken stationed here?",a="Forsaken Defilers operate from Hammerfall to secure supplies from the Arathi Basin. They oppose the Alliance's League of Arathor.",al={"forsaken hammerfall","why are undead in hammerfall","defilers arathi"}}},ang={["race:Orc"]="For orcs, Hammerfall is hallowed ground. Orgrim Doomhammer gave his life here freeing captive clanmates and passing the mantle of Warchief to Thrall.",["faction:Horde"]="For the Horde, Hammerfall is its fortress in the central Arathi Highlands. Hostile ogres, forest trolls, and remnants of the Alliance surround it."},kw={"arathi highlands","boulderfist","defilers","hammerfall","internment camp","orgrim doomhammer","thrall","witherbark"},rel={"npc:orgrim-doomhammer","zone:arathi","npc:thrall","npc:drum-fel","npc:tallow","subzone:boulder-gor","subzone:boulderfist-hall","topic:second-war"},src={"Hammerfall"}}
E["subzone:northfold-manor"] = {t="subzone",n="Northfold Manor",z="arathi",s="The Syndicate holds Northfold Manor in northwestern Arathi. Once a prosperous human homestead, the estate fell into ruin after Stromgarde collapsed and now shelters criminals and dark practices.",h="The Syndicate holds Northfold Manor in northwestern Arathi.",sec={{t="A Den of Brigands",b="Near the passage through Thoradin's Wall, Northfold Manor spreads across the rolling highlands. The estate once supported the kingdom of Stromgarde. After the realm fractured, displaced Alteraci nobles and Syndicate outlaws claimed the manor house, barn, and fields as their base.\n\nMercenaries, highwaymen, and pathstalkers gather there, leaving the crops untended. From the farmstead, they ambush travelers on nearby roads and coordinate the Syndicate's presence across Arathi.",sp=0},{t="Demonic Undertones",b="Demonic summoning has marked Northfold Manor. Sensitive spellcasters and shamans in the region feel traces that linger across the grounds. Bloodstone amulets, potent talismans used to fuel dark invocations, lie discarded there. Their presence points to Syndicate rogues entangling themselves with demonic magic beyond ordinary banditry.",sp=1}},faq={{q="Who controls Northfold Manor?",a="The Syndicate controls Northfold Manor and uses the estate as an armed encampment. Its ranks include dispossessed Alteraci nobles, bandits, and rogue mercenaries.",al={"who lives here","who owns northfold","syndicate farm"}},{q="What dark magic is being practiced here?",a="Those sensitive to magic can feel lingering traces of demonic summoning at Northfold Manor. Syndicate forces there possess bloodstone amulets that help channel dangerous demonic rituals.",al={"demons at northfold","bloodstone","what are they summoning"}},{q="Why does the Horde care about this farm?",a="At Hammerfall, the troll shaman Tor'gan sensed an unnatural disturbance brewing across the highlands. His search for its source led him to Northfold Manor, where the Horde now investigates the Syndicate's occult activities.",al={"horde interest northfold","why tor'gan cares"}},{q="Who is Singer?",a="Singer is an elusive Syndicate figure sometimes seen among the brigands inside Northfold Manor's main house.",al={"singer","singer rare","who is singer"}}},ang={["faction:Horde"]="Hammerfall's shamans keep watch over Northfold Manor. They send warriors to seize the bloodstone talismans the Syndicate uses in attempts at demonic summoning.",["class:Shaman"]="As a shaman, you may feel demonic residue around Northfold Manor disrupting the natural elements. It brings spiritual unease and fiery rage to shamans attuned to the elements."},kw={"arathi highlands","bloodstone","northfold manor","singer","stromgarde","syndicate","tor'gan"},rel={"topic:syndicate","zone:arathi","topic:horde","quest:255","topic:troll"},src={"Northfold Manor"}}
E["subzone:refuge-pointe"] = {t="subzone",n="Refuge Pointe",z="arathi",s="Refuge Pointe holds its ground in the Arathi Highlands as Stromgarde's remnant prepares to reclaim its fallen keep. The camp guards the trade road at the highlands' heart while Alliance forces face rivals across the region.",h="Refuge Pointe holds its ground in the Arathi Highlands as Stromgarde's remnant prepares to reclaim its fallen...",sec={{t="A Bastion for Stromgarde's Remnants",b="Stromgarde's surviving soldiers hold Refuge Pointe. After the Third War and the fall of Stromgarde Keep, most of the kingdom's people fled south for safer lands. Those who stayed formed a vanguard under Captain Nials. Battle-hardened Stromgarde soldiers stand with League of Arathor forces and Alliance specialists. Together, they are the last organized Stromgarde force in its ancestral homeland.",sp=0},{t="Stretched to the Limit",b="Refuge Pointe has no reserves to spare. The Forsaken and Horde hold Hammerfall, while Witherbark trolls, Syndicate rogues, and Boulderfist ogres press the garrison from other sides. When dwarven commanders at battered Thandol Span asked for help against the Dark Iron clan, Captain Nials had to refuse.\n\nEvery soldier and supply at Refuge Pointe must defend the highlands and prepare to retake Stromgarde Keep.",sp=0}},faq={{q="Why is the Alliance presence here so small?",a="Most of Stromgarde's surviving civilians fled south after the kingdom fell in the Third War. The small force at Refuge Pointe is a remnant of its army, joined by an Alliance expedition. With supplies stretched thin and enemies on every front, they struggle to hold their camp.",al={"why is refuge pointe small","why so few soldiers","alliance numbers arathi"}},{q="Why won't Refuge Pointe send soldiers to help at the Thandol Span?",a="Captain Nials refused the dwarves' request for troops to defend Dun Modr and Thandol Span from Dark Iron attacks. Stromgarde Keep is overrun, and hostile forces surround Refuge Pointe. Every soldier must help hold the highlands and prepare to reclaim the fallen capital.",al={"why no help dun modr","captain nials thandol span","plea to the alliance quest"}},{q="Who commands the camp?",a="Captain Nials commands Refuge Pointe's garrison. She directs Stromgarde's operations across the highlands, from scouting and skirmishes with the Syndicate and ogres to patrols along the main road.",al={"refuge pointe leader","who is in charge here","captain nials"}},{q="What is the League of Arathor?",a="The League of Arathor is an Alliance coalition seeking to reclaim the Arathi Highlands and secure resources in neighboring Arathi Basin. Its forces fight beside Stromgarde's remnant at Refuge Pointe to keep the Forsaken-led Defilers from controlling the fertile valley.",al={"league of arathor","who are league of arathor","arathi basin alliance"}}},ang={["faction:Alliance"]="Refuge Pointe is your military sanctuary and flight hub in the Arathi Highlands. Here, you find relief in a territory contested by ogres, the Syndicate, and the Horde.",["race:Human"]="As a human, you can look to Refuge Pointe and remember Stromgarde's former glory as humanity's martial heartland. Its defenders refuse to abandon their homeland despite overwhelming odds."},kw={"arathi highlands","arathor","captain nials","league of arathor","refuge pointe","stromgarde","thandol span"},rel={"zone:arathi","subzone:stromgarde-keep","quest:634","subzone:thandol-span","topic:alliance","npc:longbraid-the-grim","npc:skuerto","topic:third-war"},src={"Refuge Pointe"}}
E["subzone:sanctum-stromgarde-keep"] = {t="subzone",n="The Sanctum",z="arathi",s="Behind the chapel in Stromgarde Keep, the Sanctum remains a sacred refuge. It guards the way to the Trollbane family crypt amid Arathi's ruin.",h="Behind the chapel in Stromgarde Keep, the Sanctum remains a sacred refuge.",sec={{t="A Bastion in the Ruins",b="Syndicate infiltrators and Boulderfist ogres have taken much of Stromgarde Keep. Yet defenders still hold the Sanctum and the chapel beside it. Behind the Church of Light, the Sanctum borders the keep's graveyard and marks the way into the royal crypt, where Stromgarde's kings rest. Prince Galen Trollbane's loyalists defend this ground to protect their kingdom's ancestral heritage and faith from the invaders.",sp=0},{t="Threshold of the Kings",b="Stone flags cover the passage into the royal tomb beneath the Sanctum. The ground is consecrated for quiet reflection and worship of the Holy Light. After King Thoras Trollbane's murder and Stromgarde's collapse, the Sanctum became a defensive retreat. Royal guards hold its halls against anyone seeking the inner tomb. At this sacred threshold, an ancient human lineage clings to survival.",sp=0}},faq={{q="What is the Sanctum?",a="The Sanctum lies behind the Church of Light's chapel within Stromgarde Keep. It adjoins the keep's graveyard and leads into the Trollbane family crypt.",al={"what is sanctum","stromgarde sanctum","sanctum stromgarde keep"}},{q="Who controls the Sanctum right now?",a="Surviving Stromgarde soldiers loyal to the Alliance and Prince Galen Trollbane hold the Sanctum. Human guards defend the chapel and Sanctum while Syndicate bandits and Boulderfist ogres overrun the rest of the ruined city.",al={"who is in the sanctum","sanctum guards","who holds the sanctum"}},{q="What lies beyond the Sanctum?",a="The Trollbane family crypt lies beyond the Sanctum. It holds Stromgarde's fallen rulers, including the recently slain King Thoras Trollbane.",al={"where does sanctum lead","sanctum crypt","what is behind the sanctum"}},{q="Why is this area important to Stromgarde?",a="The Sanctum is consecrated for worship of the Holy Light and guards the resting place of Stromgarde's kings. Its defenders fight to keep invaders from desecrating their ancestors' graves.",al={"why care about sanctum","sanctum significance","why is sanctum defended"}}},ang={["class:Paladin"]="As a paladin, you find the chapel and Sanctum among the last undefiled sanctuaries of the Holy Light in Arathi's fallen capital. Defending them is a solemn duty.",["faction:Alliance"]="As an Alliance member, you help hold the Trollbane ancestral seat and keep the Alliance presence alive in Stromgarde's contested ruins."},kw={"arathi","chapel","church of light","crypt","galen","sanctum","stromgarde","trollbane"},rel={"subzone:stromgarde-keep","subzone:crypt-stromgarde-keep","zone:arathi","topic:light","topic:alliance"},src={"Sanctum (Stromgarde Keep)"}}
E["subzone:stromgarde-keep"] = {t="subzone",n="Stromgarde Keep",z="arathi",s="In the Arathi Highlands, Stromgarde Keep is divided between its royal defenders, the Syndicate and Boulderfist ogres. The fallen kingdom's battered capital holds only part of its fortress.",h="In the Arathi Highlands, Stromgarde Keep is divided between its royal defenders, the Syndicate and...",sec={{t="Cradle of Humanity",b="Strom began as the first capital of the unified human empire of Arathor. King Thoradin founded it nearly three millennia ago. From this fortress, humanity prepared its victory over the forest trolls. Here, high elven magi taught the first hundred human spellcasters and began the long history of human wizardry.\n\nDalaran, Lordaeron and Stormwind rose as younger sister kingdoms while Strom's influence waned. The stubborn Trollbane dynasty remained and renamed the city Stromgarde. Through the Second War, it stood as a proud warrior bastion and an anchor of the Alliance of Lordaeron against the Orcish Horde.",sp=0},{t="A Shattered Bastion",b="The devastation of the Third War brought mounting disasters and treachery, and Stromgarde finally broke. Its majestic stone city is now split into three warring sectors. Aristocratic Syndicate traitors hold the grand inner keep, while Boulderfist ogres have overrun the former sanctum of the mage district.\n\nPrince Galen Trollbane and the battered Stromgarde military hold the remaining quarter. They wage a hard, bloody war on several fronts to keep their ancestral home from vanishing into memory.",sp=0}},faq={{q="Who controls Stromgarde Keep right now?",a="Three warring forces divide the ruined city. The Syndicate holds the central inner keep, Boulderfist ogres occupy the ruined mage district, and Prince Galen Trollbane leads the surviving Stromgarde army from the remaining quarter.",al={"who lives in stromgarde","who owns stromgarde keep","who is in stromgarde"}},{q="What was the Empire of Arathor?",a="The Empire of Arathor was the first unified human nation, founded nearly three thousand years ago under King Thoradin. Its capital, Strom, stood where Stromgarde Keep now stands.",al={"what is strom","first human kingdom","arathor empire"}},{q="Why is the city in ruins?",a="Stromgarde's kingdom was left vulnerable and isolated in the chaos after the Third War. Betrayal within the city, attacks by the criminal Syndicate and assaults by Boulderfist ogres shattered its defenses.",al={"why is stromgarde destroyed","what happened to stromgarde"}},{q="Who is Galen Trollbane?",a="Prince Galen Trollbane is the royal scion and commander of Stromgarde's surviving forces. From his embattled redoubt inside the keep, he directs the desperate defense against the Syndicate and the ogres.",al={"prince trollbane","who is prince galen"}}},ang={["race:Human"]="As a human, you can look to Stromgarde as the ancient heart of your race. The first human tribes united under Thoradin here, and high elves taught them the arcane arts. Seeing criminals and ogres overrun the city is a bitter sight.",["faction:Alliance"]="As an Alliance member, you can look to Stromgarde, a founding member of the Alliance of Lordaeron during the Second War. Its beleaguered defenders remain one of the last loyal strongholds in the north, fighting to avoid total ruin."},kw={"arathi","arathor","boulderfist","galen","strom","stromgarde","stromgarde keep","syndicate","thoradin","trollbane"},rel={"zone:arathi","topic:syndicate","topic:alliance-of-lordaeron","topic:second-war","topic:third-war","topic:stormwind-kingdom","topic:lordaeron","subzone:dalaran"},src={"Stromgarde Keep"}}
E["subzone:thandol-span"] = {t="subzone",n="Thandol Span",z="arathi",s="At Thandol Span, the surviving bridge lies under attack. Its stone arches link the Wetlands of Khaz Modan with the Arathi Highlands of southern Lordaeron, but Dark Iron infiltrators have sabotaged one crossing.",h="At Thandol Span, the surviving bridge lies under attack.",sec={{t="The Fight for the Crossing",b="Ironforge Mountaineers guard the surviving bridge. They fight to hold the roadway and drive back Dark Iron sappers, though the defense costs them dearly. If the bridge falls, northern trade and military movements will rely almost entirely on sea routes. Alliance forces in the Arathi Highlands will lose their immediate reinforcement.",sp=0},{t="A Lifeline Severed",b="Dwarves built the Thandol Span after the War of the Three Hammers to link Ironforge with the Wildhammer clan at Aerie Peak. Its bridges rank among the grandest works of dwarven stonecraft, strong enough to bear entire marching armies. During the Second War, armies crossed between Lordaeron and Khaz Modan here, including Sir Anduin Lothar's counter-offensive south.\n\nNow Dark Iron saboteurs have struck from nearby Dun Modr. Led by Balgaras the Foul and Kam Deepfury, they used explosives to shatter one span and threaten the overland route between the allied realms.",sp=1,bt={"q303.3"}}},faq={{q="What is the Thandol Span?",a="The Thandol Span carries you across a deep canyon between the Wetlands in northern Khaz Modan and the Arathi Highlands in southern Lordaeron. Dwarves built its two stone arches.",al={"thandol span overview","what is this bridge","thandol bridge"},it="place"},{q="Why is one of the bridges broken?",a="Dark Iron dwarves attacked from the captured outpost of Dun Modr. They used explosives to demolish one of the two spans and cut Alliance supply lines.",al={"who blew up the bridge","thandol span destroyed","why is thandol span broken"},it="ruin"},{q="Why was the Thandol Span originally built?",a="Ironforge dwarves built the Span after the War of the Three Hammers to strengthen trade, diplomacy, and ties with their Wildhammer cousins across the canyon in the north.",al={"who built thandol span","thandol history","why was it built"},it="origin"},{q="Did armies cross here during the Second War?",a="Yes. The Old Horde crossed the sea to invade Lordaeron. Later, Sir Anduin Lothar led the Alliance counter-offensive across the Span, driving the orcs back into Khaz Modan.",al={"thandol span second war","orcs at thandol span","lothar thandol span"},it="history"},{q="Who controls the Thandol Span?",a="The Thandol Span is held and guarded by the dwarves of Ironforge. Despite suffering brutal raids and sabotage from Dark Iron infiltrators operating out of nearby Dun Modr, Ironforge mountaineers continue to defend the surviving bridge, keeping open the vital link between Khaz Modan and the northern kingdoms.",al={"who controls thandol span","who runs thandol span","thandol span guards"},it="residents",add="6e9af8e2"},{q="Is the Thandol Span dangerous?",a="Yes, traveling across the Span is hazardous. Dark Iron saboteurs recently infiltrated the gorge and detonated explosives, completely severing one of the two twin arches and leaving the remaining span vulnerable. Hostile Dark Iron dwarves linger nearby in the northern Wetlands and around Dun Modr, actively plotting further strikes against travelers and Ironforge defenders holding the line.",al={"is thandol span safe","thandol span danger","threats at thandol span"},it="danger",add="a33b8b45"}},ang={["race:Dwarf"]="As a dwarf of Ironforge, you can take pride in the Span as a masterwork of your stonemasons. Yet it is a painful battleground where Dark Iron kin have brought destruction to your doorstep.",["faction:Alliance"]="As an Alliance member, you depend on the Span as the only direct overland link between Khaz Modan and the beleaguered northern outposts of Lordaeron. Its defense is vital to the war effort."},kw={"arathi highlands","balgaras","dark iron","dun modr","ironforge","kam deepfury","thandol span","wetlands"},rel={"subzone:dun-modr","zone:wetlands","zone:arathi","quest:631","quest:303","quest:378","npc:kam-deepfury","topic:second-war"},src={"Thandol Span"}}
E["subzone:thoradin-s-wall"] = {t="subzone",n="Thoradin's Wall",z="arathi",s="At Thoradin's Wall, broken stone divides the Arathi Highlands from the Hillsbrad Foothills. King Thoradin ordered it built long ago to shield early humanity from Amani troll incursions.",h="At Thoradin's Wall, broken stone divides the Arathi Highlands from the Hillsbrad Foothills.",sec={{t="A Bulwark of Ancient Arathor",b="Thoradin's Wall once guarded Strom's western frontier. Nearly three thousand years ago, King Thoradin raised it across the valley corridor to shield humanity's young settlements from Amani forest troll raids. Strom stood at the heart of Arathor, the first unified human empire. The wall protected its heartland, giving humanity room to survive and challenge troll supremacy in the north.",sp=0},{t="Centuries of Decay",b="Thoradin's Wall now lies in severe disrepair. Great breaches split its ramparts, worn down by weather, warfare, and abandonment. Arathor splintered into rival kingdoms, and neighboring Lordaeron later fell to the Scourge. No central realm remains to maintain the masonry. Travelers and roaming bandits pass freely through the broken archways between Hillsbrad and the untamed Arathi Highlands.",sp=0}},faq={{q="Who built Thoradin's Wall?",a="King Thoradin commissioned Thoradin's Wall nearly three thousand years ago. He unified humanity's tribes and founded the Empire of Arathor.",al={"who made thoradins wall","creator of thoradins wall","thoradin wall origins"},it="origin"},{q="Why was the wall built in the first place?",a="King Thoradin ordered Thoradin's Wall built to defend Strom, humanity's early capital, and its fledgling settlements from raids by the neighboring Amani troll empire.",al={"purpose of thoradins wall","why build the wall","what was thoradins wall for"},it="purpose"},{q="Why is the wall so broken down today?",a="Thousands of years of weathering, conflict, and neglect have broken down Thoradin's Wall. After Arathor splintered into independent human nations, the frontier fortification lost its strategic priority and fell into disrepair.",al={"why is thoradin wall broken","who destroyed thoradins wall","why ruined"},it="ruin"},{q="What regions does Thoradin's Wall separate?",a="Thoradin's Wall separates the Hillsbrad Foothills to the west from the Arathi Highlands to the east.",al={"where is thoradins wall","what does the wall divide","border of thoradins wall"}},{q="What is Thoradin's Wall?",a="Thoradin's Wall is an ancient, colossal stone rampart that spans the border between the Arathi Highlands and Hillsbrad Foothills. Raised millennia ago during the height of the Empire of Arathor, it served as humanity's grand defensive bulwark to shield the heartlands around Strom from the fierce incursions of the Amani trolls. Today, though heavily weathered and broken, its towering arches and crumbling stones still loom over the trade road.",al={"what is thoradins wall","thoradin wall info","about thoradins wall"},it="place",add="b3263746"},{q="What happened at Thoradin's Wall?",a="For generations, the wall held firm against countless raids by the forest trolls of Zul'Aman, defending humanity's cradle. Over subsequent centuries, neglect, wars, and the sheer passage of time saw its defenses decay into the ruins standing today.",al={"history of thoradins wall","thoradins wall battles","what happened here"},it="history",add="a3fa6dab"},{q="Why is it called Thoradin's Wall?",a="The wall is named in honor of High King Thoradin, the legendary warlord who first unified the warring human tribes into the glorious Empire of Arathor. Shortly after establishing his empire and founding its great capital of Strom, Thoradin ordered the construction of this vast fortification to secure mankind's survival against hostile wilderness threats, ensuring his name remained etched in stone across the frontier.",al={"why is it called thoradins wall","who is thoradins wall named after","thoradin wall name"},it="name",add="bb7d6206"}},ang={["race:Human"]="As a human, you stand before Thoradin's Wall and face human antiquity in the enduring masonry of King Thoradin, who first unified the scattered human tribes.",["race:Troll"]="As a troll, you see in these ruined fortifications the trace of ancient territorial wars, when humanity halted the forest trolls' domain."},kw={"amani","arathi","arathor","hillsbrad","strom","thoradin","thoradin's wall","wall"},rel={"zone:arathi","zone:hillsbrad","topic:troll","topic:dwarf","topic:syndicate"},src={"Thoradin's Wall"}}
E["subzone:tower-of-arathor"] = {t="subzone",n="Tower of Arathor",z="arathi",s="Boulderfist ogres hold the Tower of Arathor among the ruins of Stromgarde Keep. The spire once served Archmage Trelane in the former mage district, southwest in the keep.",h="Boulderfist ogres hold the Tower of Arathor among the ruins of Stromgarde Keep.",sec={{t="A Bastion Overrun",b="In Stromgarde Keep's mage district, the spire rises above ruins and bears the name of the ancient Empire of Arathor. It once served the realm's sorcerers, most notably Archmage Trelane. He devised a magical defensive grid keyed to enchanted gemstones to guard the sanctum.\n\nAfter the Third War, the Syndicate and the Boulderfist ogre clan assaulted Stromgarde, and the kingdom fractured. Trelane tried to hold the tower with his arcane wards, but the ogres overwhelmed him. He fled the city for his life and left his most prized arcane artifacts behind. Now the Boulderfist brute Ruul Onestone and his followers hold the spire.",sp=0},{t="Reclaiming the Lost Relics",b="Even in exile, Trelane would not abandon his life's work. He enlisted his former pupil, Archmage Malin of the Kirin Tor, and an expedition set out to retrieve his phylactery, orb, and ember agate. Working from Refuge Pointe, Malin's agents learned that the ogres had pillaged the stones needed to command the tower's automated defenses.\n\nThe agents crafted a replacement enchanted agate and placed it on the pedestals framing the tower's threshold. This awakened conjured water elementals to purge the ogre occupiers, allowing adventurers to recover Trelane's heirlooms.",sp=1}},faq={{q="What is the Tower of Arathor?",a="The Tower of Arathor rises in the southwestern ruins of Stromgarde Keep. Named for the ancient human empire of Arathor, it served as a center of study for the kingdom's mages until invading ogres took it.",al={"tower of arathor","stromgarde mage tower","arathi tower"}},{q="Who lives in the tower now?",a="Boulderfist ogres occupy the tower and the surrounding mage district. The ogre mage Ruul Onestone dwells inside the spire with his guards, who have rooted out and guarded the relics left by its former master.",al={"who is in the tower of arathor","tower of arathor mobs","tower of arathor boss"}},{q="Who was Archmage Trelane?",a="Archmage Trelane was a prominent wizard of Stromgarde who lived and studied in the tower. He created its gemstone-powered wards, then fled into exile after failing to defend the sanctum from the Boulderfist assault.",al={"archmage trelane","who owned the tower","trelane"}},{q="How do the tower's defenses work?",a="Trelane keyed the tower to awaken when an enchanted agate is placed on the pedestals flanking its entrance. The arcane matrix then conjures hostile water elementals to battle intruders occupying the entrance.",al={"how to activate tower defenses","trelane's defenses","tower pedestals"}}},ang={["class:Mage"]="As a Mage, you can see what became of Stromgarde's arcane enclave and Archmage Trelane's mastery of defensive elemental constructs.",["faction:Alliance"]="As an Alliance member, you can help Archmage Malin's agents recover Trelane's lost artifacts in contested Stromgarde Keep. That denies potent magical relics to the encroaching Boulderfist clan."},kw={"arathi","boulderfist","malin","ruul onestone","skuerto","stromgarde","tower of arathor","trelane"},rel={"subzone:stromgarde-keep","zone:arathi","npc:archmage-malin","npc:skuerto","quest:690","topic:syndicate","topic:alliance","topic:third-war"},src={"Tower of Arathor"}}
E["subzone:witherbark-village"] = {t="subzone",n="Witherbark Village",z="arathi",s="In the southeastern Arathi Highlands, Witherbark Village shelters hostile forest trolls beside a secluded lake. The tribe raids Stromgarde's Alliance remnants and the Horde outpost at Hammerfall.",h="In the southeastern Arathi Highlands, Witherbark Village shelters hostile forest trolls beside a secluded...",sec={{t="Stronghold of the Forest Trolls",b="Witherbark trolls hold the shore and paths around their mountain lake. Fishers, axe throwers, and witch doctors live in huts along the water. Zalas Witherbark and the tribe's shadow hunters direct their people from a great cavern behind the settlement.\n\nThe Witherbark have joined forces with the Boulderfist ogres to claim more of the highlands. They have also taken a firm foothold in the ruins of Stromgarde Keep. Any outsider who enters their territory risks a fierce attack.",sp=0}},faq={{q="Who lives in Witherbark Village?",a="The Witherbark tribe, forest trolls native to the region, holds the settlement. Headhunters, axe throwers, fishers, and witch doctors defend the lake and its surrounding paths.",al={"who are witherbark","witherbark trolls","who controls witherbark village"}},{q="What is inside the large cave behind the village?",a="The great cavern holds the tribe's leaders. Chieftain Zalas Witherbark and the shadow hunters direct the tribe's raids and defenses from within its tunnels.",al={"witherbark cave","cave behind witherbark village","zalas witherbark location"}},{q="Why are the Witherbark trolls working with ogres?",a="The Witherbark have formed a loose alliance of convenience with the local Boulderfist ogres. Together, they can press Stromgarde's weakened human defenders and threaten rivals such as the Horde at Hammerfall.",al={"witherbark ogre alliance","trolls and boulderfist","why are trolls allied with ogres"}},{q="Are the Witherbark friendly to the Horde?",a="No. The Witherbark resent the modern Horde and its Darkspear trolls, and they fight the Horde at Hammerfall. They attack Horde travelers on sight.",al={"are witherbark horde","can horde talk to witherbark","witherbark reputation"}}},ang={["faction:Horde"]="The Witherbark give no deference to the new Horde. They often clash with scouts from Hammerfall and threaten travel through the eastern passes.",["race:Troll"]="As a Darkspear troll, you will find no kinship with the Witherbark. These forest trolls regard jungle trolls and the Horde with deep hostility."},kw={"arathi highlands","forest trolls","nimar the slayer","witherbark","witherbark village","zalas witherbark"},rel={"zone:arathi","subzone:hammerfall","topic:troll","topic:horde","topic:alliance"},src={"Witherbark Village"}}
E["zone:arathi"] = {t="zone",n="Arathi Highlands",z="arathi",s="In Arathi, ruined Stromgarde leaves the highlands at war on several fronts. The kingdom's remnants, the Horde, Syndicate nobles, and invading ogres fight for the ancient birthplace of the Empire of Arathor in southeastern Lordaeron.",h="In Arathi, ruined Stromgarde leaves the highlands at war on several fronts.",sec={{t="Cradle of Humanity",b="The dry plains of Arathi once formed the heart of a united human realm. Millennia ago, King Thoradin gathered the divided tribes beneath the Arathi banner and built their capital, Strom, on ground that was easy to defend. During the Troll Wars, humanity made its compact with the high elves here and learned the arcane arts to drive back the Amani.\n\nNoble bloodlines later spread north into Lordaeron and south toward Stormwind. The imperial guard remained and formed Stromgarde, a martial kingdom that guarded the border against forest trolls for ages.",sp=0},{t="A Shattered Kingdom",b="Under King Thoras Trollbane, Stromgarde helped defend the Alliance during the Second War. The Third War and its aftermath broke the kingdom. It escaped the worst of the Scourge plague, but King Thoras's mysterious death plunged the realm into turmoil. Boulderfist ogres came down from the hills, while nobles of Alterac in the Syndicate seized wide districts of Stromgarde Keep.\n\nPrince Galen Trollbane and his loyalists now hold a small part of the city and their refuge at Refuge Pointe. Against heavy odds, they fight a bitter guerrilla war.",sp=0},{t="The War for the Highlands",b="Arathi is contested by forces with different claims. In the northeast, the Horde made Hammerfall from an abandoned human internment camp and named it for Warchief Orgrim Doomhammer. The outpost anchors their northern holdings and protects their allies in Hillsbrad. The Witherbark trolls seek vengeance against the humans who once persecuted them, while the Argus Wake guides the Syndicate's occupation.\n\nAt the plateau's center, the ancient Circles of Binding hold elementals in place. They restrain an old power buried beneath the stone.",sp=1}},faq={{q="What happened to Stromgarde Keep?",a="After King Thoras Trollbane died, strife engulfed Stromgarde and attackers closed in. Boulderfist ogres took the outer districts, while the Syndicate seized the keep's sanctum. Prince Galen Trollbane and his dwindling garrison hold one fortified corner and fight for their capital.",al={"why is stromgarde ruined","who controls stromgarde","stromgarde status"}},{q="What is Hammerfall?",a="Hammerfall is a Horde outpost built in the remains of a human internment camp where orcs were held after the Second War. Its name honors former Warchief Orgrim Doomhammer, who died leading the campaign to free captives from camps across Lordaeron.",al={"horde base arathi","history of hammerfall","why is it called hammerfall"}},{q="Where does the Alliance operate in Arathi?",a="Alliance soldiers and Stromgarde defenders operate from Refuge Pointe, a naturally fortified canyon in the center of the highlands. From there, they attack to reclaim Stromgarde Keep and push back ogres and trolls.",al={"alliance base arathi","refuge pointe","where are the stromgarde humans"}},{q="What are the stone circles across the plains?",a="The Inner, Outer, East, and West Circles of Binding are ancient magical seals guarded and maintained by rogue elementals. They imprison an unknown, primordial being deep beneath the highlands.",al={"circles of binding","elementals in arathi","stone circles"}},{q="How do you reach the Arathi Highlands?",a="From the north and west, travelers cross the breach in Thoradin's Wall from the Hillsbrad Foothills. From Khaz Modan in the south, they cross the dwarven bridge of the Thandol Span over the chasm between the highlands and the Wetlands.",al={"getting to arathi","how to get to arathi highlands","arathi entrance"}},{q="What is the Syndicate doing in Arathi?",a="The Syndicate is made up of exiled Alteraci nobles who seek new domains by pillaging fallen realms. In Arathi, they have taken large parts of Stromgarde Keep and nearby farms, including Northfold Manor.",al={"why is syndicate in arathi","syndicate stromgarde","who leads the syndicate here"},sp=1}},ang={["race:Human"]="As a human, you share roots with every kingdom in the Empire of Arathor. Seeing its ancient seat broken and overrun by ogres and thieves is a deep cultural loss.",["faction:Horde"]="As a member of the Horde, you know Hammerfall as sacred ground. It honors Orgrim Doomhammer's sacrifice to free an enslaved people from internment.",["class:Warrior"]="As a warrior, you follow Stromgarde's celebrated martial tradition. Its rugged battlegrounds are a revered trial by arms.",["profession:Mining"]="As a miner, you can find iron and mithril in Arathi's craggy ridges. Drywhisker Gorge is the only known source of lesser bloodstone ore."},kw={"arathi","arathi highlands","arathor","boulderfist","galen trollbane","hammerfall","refuge pointe","stromgarde","syndicate","thandol span","thoradin's wall"},rel={"subzone:stromgarde-keep","subzone:hammerfall","subzone:refuge-pointe","subzone:thandol-span","subzone:thoradin-s-wall","npc:orgrim-doomhammer","zone:hillsbrad","zone:wetlands"},src={"Arathi Highlands (Classic)","Arathi Highlands"}}
